export const DOC_PAGES: Record<string, DocPage> = {
  "introduction": {
    "id": "introduction",
    "title": "Welcome to CounterAttack",
    "eyebrow": "Built by attackers, made for defenders",
    "lede": "CounterAttack is an attack surface management platform. It maps everything you have exposed to the internet, scans it for vulnerabilities, and runs incident checks that sweep the public web for signs your sites have already been hacked. It works from the outside, the way an attacker would, with no agents, no credentials, and nothing to install.",
    "html": "<span class=\"eyebrow\" data-id=\"Dibangun oleh penyerang, dibuat untuk pembela\">Built by attackers, made for defenders</span>\n  <h1 data-id=\"Selamat datang di CounterAttack\">Welcome to CounterAttack</h1>\n  <p class=\"lede\" data-id=\"CounterAttack adalah platform attack surface management. CounterAttack memetakan semua yang Anda ekspos ke internet, memindainya untuk mencari kerentanan, dan menjalankan Incident Check yang menyisir web publik untuk mencari tanda-tanda situs Anda sudah diretas. CounterAttack bekerja dari luar, seperti cara seorang penyerang, tanpa agent, tanpa credentials, dan tanpa perlu instalasi apa pun.\">CounterAttack is an attack surface management platform. It maps everything you have exposed to the internet, scans it for vulnerabilities, and runs incident checks that sweep the public web for signs your sites have already been hacked. It works from the outside, the way an attacker would, with no agents, no credentials, and nothing to install.</p>\n\n  <div class=\"hero-strip\">\n    <div class=\"hero-strip-title\">Detect the attack. Check what attackers do.</div>\n    <div class=\"hero-strip-sub\">Vulnerability scans plus incident checks. No noise. No card required, live in minutes, built in Indonesia.</div>\n  </div>\n\n  <div class=\"kpi-row\" style=\"margin-bottom:26px;\">\n    <div class=\"kpi\"><div class=\"k-value\">1,425,000+</div><div class=\"k-sub\">Active detection rules</div></div>\n    <div class=\"kpi\"><div class=\"k-value\">4,000+</div><div class=\"k-sub\">CVEs covered</div></div>\n    <div class=\"kpi\"><div class=\"k-value\">30+</div><div class=\"k-sub\">Incident signatures</div></div>\n    <div class=\"kpi\"><div class=\"k-value\">A to F</div><div class=\"k-sub\">Security grades</div></div>\n  </div>\n\n  <div class=\"shot\">\n    <div class=\"shot-bar\"><span class=\"traffic\"><i></i><i></i><i></i></span><span class=\"url\">app.counterattack.com/dashboard</span></div>\n    <div class=\"shot-body\">\n      <div style=\"font-size:12px;color:var(--fg-subtle);margin-bottom:10px;\">Attack Surface Overview</div>\n      <div class=\"kpi-row\">\n        <div class=\"kpi\"><div class=\"k-label\"><i data-lucide=\"server\"></i> Total Assets</div><div class=\"k-value\">128</div><div class=\"k-sub\">+6 this week</div></div>\n        <div class=\"kpi\"><div class=\"k-label\"><i data-lucide=\"alert-triangle\"></i> Open Vulns</div><div class=\"k-value\" style=\"color:var(--sev-critical)\">17</div><div class=\"k-sub\">3 critical</div></div>\n        <div class=\"kpi\"><div class=\"k-label\"><i data-lucide=\"alert-octagon\"></i> Open Incidents</div><div class=\"k-value\" style=\"color:var(--sev-high)\">4</div><div class=\"k-sub\">1 critical</div></div>\n        <div class=\"kpi\"><div class=\"k-label\"><i data-lucide=\"gauge\"></i> Rating</div><div class=\"k-value\" style=\"color:var(--sev-high)\">D</div><div class=\"k-sub\">Needs work</div></div>\n      </div>\n    </div>\n  </div>\n  <p class=\"shot-cap\" data-id=\"Pratinjau &lt;b&gt;Dashboard&lt;/b&gt;, ditampilkan dengan tema dan tata letak yang sama seperti console langsung.\">A preview of the <b>Dashboard</b>, rendered in the same theme and layout as the live console.</p>\n\n  <h2 data-id=\"Dua pemeriksaan, tetap terpisah\">Two checks, kept separate</h2>\n  <p data-id=\"CounterAttack menjalankan dua jenis pemeriksaan dengan bobot yang setara. Sebuah &lt;strong&gt;vulnerability scan&lt;/strong&gt; menemukan kelemahan pada perangkat lunak Anda: CVE yang diketahui, misconfiguration, dan eksposur. Sebuah &lt;strong&gt;incident check&lt;/strong&gt; menyisir web publik untuk mencari tanda-tanda sebuah situs sudah disusupi, seperti defacement, injeksi judi, dan SEO spam tersembunyi. Keduanya berjalan di jalur masing-masing dan masuk ke antrean serta tampilan yang terpisah, sehingga tidak ada yang tertutupi oleh yang lain.\">CounterAttack runs two kinds of check on the same footing. A <strong>vulnerability scan</strong> finds weaknesses in your software: known CVEs, misconfigurations, and exposures. An <strong>incident check</strong> sweeps the public web for signs a site has already been compromised, such as defacement, gambling injection, and hidden SEO spam. The two run on their own tracks and land in separate queues and views, so neither gets buried under the other.</p>\n  <div class=\"callout\" style=\"border-left-color:var(--accent);background:var(--accent-soft);\"><i data-lucide=\"shield-check\" style=\"color:var(--accent)\"></i><div><p style=\"margin:0;color:var(--fg-default)\" data-id=\"&lt;strong&gt;Vulnerabilities dan Incidents tetap terpisah. Selalu.&lt;/strong&gt;\"><strong>Vulnerabilities and Incidents stay separate. Always.</strong></p></div></div>\n\n  <h2 data-id=\"Apa yang CounterAttack lakukan\">What CounterAttack does</h2>\n  <div class=\"feature-grid\">\n    <a class=\"feature-card\" href=\"#/groups\"><div class=\"fc-icon\"><i data-lucide=\"radar\"></i></div><h4 data-id=\"Penemuan berkelanjutan\">Continuous discovery</h4><p data-id=\"Subdomain, host, dan layanan. Selalu terkini.\">Subdomains, hosts, and services. Always current.</p></a>\n    <a class=\"feature-card\" href=\"#/vulnerabilities\"><div class=\"fc-icon\"><i data-lucide=\"alert-triangle\"></i></div><h4>Vulnerabilities</h4><p data-id=\"CVE dan misconfiguration yang nyata. Tingkat keparahan yang sesuai dengan risikonya.\">Real CVEs and misconfigurations. Severity that matches the risk.</p></a>\n    <a class=\"feature-card\" href=\"#/rating\"><div class=\"fc-icon\"><i data-lucide=\"gauge\"></i></div><h4 data-id=\"Heatmap eksposur\">Exposure heatmap</h4><p data-id=\"Security rating A sampai F per Asset Group, dalam sekali lihat.\">An A to F security rating per asset group, at a glance.</p></a>\n    <a class=\"feature-card\" href=\"#/incidents\"><div class=\"fc-icon\"><i data-lucide=\"skull\"></i></div><h4>Incident Check</h4><p data-id=\"Tangkap defacement, injeksi judi, dan SEO spam di situs Anda.\">Catch defacement, gambling injection, and SEO spam on your sites.</p></a>\n    <a class=\"feature-card\" href=\"#/results\"><div class=\"fc-icon\"><i data-lucide=\"activity\"></i></div><h4 data-id=\"Progres scan langsung\">Live scan progress</h4><p data-id=\"Lihat setiap fase saat berjalan. Tanpa menunggu tanpa kabar.\">See each phase as it runs. No silent waits.</p></a>\n    <a class=\"feature-card\" href=\"#/scans\"><div class=\"fc-icon\"><i data-lucide=\"rotate-cw\"></i></div><h4 data-id=\"Pemindaian ulang terjadwal\">Scheduled rescans</h4><p data-id=\"Attack surface Anda dipindai ulang sesuai jadwal, sehingga eksposur baru muncul dengan sendirinya.\">Your surface is re-scanned on a schedule, so new exposures surface on their own.</p></a>\n  </div>\n\n  <h2 data-id=\"Satu scan, lima tahap\">One scan, five stages</h2>\n  <p data-id=\"Setiap scan CounterAttack menjalankan rangkaian yang sama, dengan urutan yang sama, setiap kali. Alur kerja vulnerability dan Incident Check berjalan di jalur masing-masing sehingga hasilnya tidak pernah tercampur.\">Every CounterAttack scan runs the same chain, in the same order, every time. The vulnerability workflow and the Incident Check run on their own tracks so their results never blur together.</p>\n  <ol class=\"steps\">\n    <li><strong>Discover</strong><span class=\"subtle\" data-id=\" Temukan setiap subdomain, menggunakan tiga sumber pasif.\"> Find every subdomain, using three passive sources.</span></li>\n    <li><strong>Probe</strong><span class=\"subtle\" data-id=\" Periksa mana yang aktif, dengan fingerprinting HTTP.\"> Check what is alive, with HTTP fingerprinting.</span></li>\n    <li><strong>Capture</strong><span class=\"subtle\" data-id=\" Ambil screenshot setiap host untuk bukti visual.\"> Screenshot every host for visual evidence.</span></li>\n    <li><strong>Scan vulns</strong><span class=\"subtle\" data-id=\" Munculkan vulnerabilities, satu per kecocokan, terhadap 14.101 template.\"> Raise vulnerabilities, one per match, against 14,101 templates.</span></li>\n    <li><strong>Incident check</strong><span class=\"subtle\" data-id=\" Sisir defacement dan injeksi judi, terhadap 30 signature.\"> Sweep for defacement and gambling injection, against 30 signatures.</span></li>\n  </ol>\n\n  <h2 data-id=\"Bagaimana dokumentasi ini disusun\">How this documentation is organized</h2>\n  <ul>\n    <li data-id=\"&lt;strong&gt;Memulai&lt;/strong&gt; membawa Anda dari pendaftaran sampai scan pertama Anda.\"><strong data-id=\"Memulai\">Getting started</strong> takes you from sign-up to your first scan.</li>\n    <li data-id=\"&lt;strong&gt;Alur kerja inti&lt;/strong&gt; mencakup Dashboard, Asset Groups, menjalankan scan, dan membaca hasil.\"><strong data-id=\"Alur kerja inti\">Core workflow</strong> covers the Dashboard, Asset Groups, running scans, and reading results.</li>\n    <li data-id=\"&lt;strong&gt;Temuan&lt;/strong&gt; menjelaskan Vulnerabilities, Incidents, penyelesaian masalah, Reports, dan Activity.\"><strong data-id=\"Temuan\">Findings</strong> explains Vulnerabilities, Incidents, resolving issues, reports, and activity.</li>\n    <li data-id=\"&lt;strong&gt;Intelijen&lt;/strong&gt; mencakup Security rating, AI insights, dan notifikasi.\"><strong data-id=\"Intelijen\">Intelligence</strong> covers the security rating, AI insights, and alerts.</li>\n    <li data-id=\"&lt;strong&gt;Akun&lt;/strong&gt; mencakup paket, upgrade, dan profil Anda.\"><strong data-id=\"Akun\">Account</strong> covers plans, upgrading, and your profile.</li>\n    <li data-id=\"&lt;strong&gt;Live playground&lt;/strong&gt; memungkinkan Anda menjalankan simulasi Full Scan langsung di dalam dokumentasi ini.\"><strong>Live playground</strong> lets you run a simulated Full Scan right inside these docs.</li>\n  </ul>\n\n  <div class=\"callout tip\"><i data-lucide=\"lightbulb\"></i><div><span class=\"callout-title\" data-id=\"Baru di sini?\">New here?</span><p data-id=\"Langsung menuju &lt;a href=&quot;#/quickstart&quot;&gt;Quickstart&lt;/a&gt;, atau buka &lt;a href=&quot;#/playground&quot;&gt;Live playground&lt;/a&gt; untuk menyaksikan scan berjalan dari awal sampai akhir.\">Jump straight to the <a href=\"#/quickstart\" data-id=\"Mulai cepat\">Quickstart</a>, or open the <a href=\"#/playground\">Live playground</a> to watch a scan run end to end.</p></div></div>\n\n  <div class=\"pager\"><span></span><a class=\"next\" href=\"#/quickstart\"><div class=\"dir\" data-id=\"Berikutnya\">Next</div><div class=\"ttl\">Quickstart &rarr;</div></a></div>"
  },
  "quickstart": {
    "id": "quickstart",
    "title": "Quickstart",
    "eyebrow": "Getting started",
    "lede": "From a fresh account to your first full set of results in about five clicks. A Full Scan runs both the vulnerability workflow and the incident check on one domain, and usually takes 25 to 40 minutes. You can close the tab while it works.",
    "html": "<span class=\"eyebrow\" data-id=\"Memulai\">Getting started</span>\n  <h1 data-id=\"Mulai cepat\">Quickstart</h1>\n  <p class=\"lede\" data-id=\"Dari akun baru sampai kumpulan hasil lengkap pertama Anda hanya dalam sekitar lima klik. Sebuah Full Scan menjalankan alur kerja vulnerability sekaligus incident check pada satu domain, dan biasanya memakan waktu 25 sampai 40 menit. Anda bisa menutup tab selagi prosesnya berjalan.\">From a fresh account to your first full set of results in about five clicks. A Full Scan runs both the vulnerability workflow and the incident check on one domain, and usually takes 25 to 40 minutes. You can close the tab while it works.</p>\n\n  <div class=\"callout warn\"><i data-lucide=\"shield-alert\"></i><div><span class=\"callout-title\" data-id=\"Hanya target yang diizinkan\">Authorized targets only</span><p data-id=\"Hanya scan domain yang Anda miliki atau yang secara eksplisit diizinkan untuk Anda uji di bawah program bug bounty, program pengungkapan kerentanan, atau perjanjian pentest tertulis. CounterAttack meminta Anda mengonfirmasi hal ini sebelum bisa melakukan scan.\">Only scan domains you own or are explicitly authorized to test under a bug bounty, a vulnerability disclosure program, or a written pentest engagement. CounterAttack asks you to confirm this before you can scan.</p></div></div>\n\n  <ol class=\"steps\">\n    <li><strong data-id=\"Buat akun Anda dan verifikasi email Anda.\">Create your account and verify your email.</strong>\n      <p data-id=\"Daftar dengan email dan password, klik tautan verifikasi, lalu setujui Terms penggunaan yang diizinkan. Lihat &lt;a href=&quot;#/accounts&quot;&gt;Akun &amp;amp; pendaftaran&lt;/a&gt;.\">Sign up with an email and password, click the verification link, then accept the authorized-use Terms. See <a href=\"#/accounts\" data-id=\"Akun &amp;amp; pendaftaran\">Accounts &amp; sign-up</a>.</p>\n      <div class=\"shot\">\n        <div class=\"shot-bar\"><span class=\"traffic\"><i></i><i></i><i></i></span><span class=\"url\">app.counterattack.com/signup</span></div>\n        <div class=\"shot-body\">\n          <div class=\"rl-card\" style=\"max-width:420px;margin:0 auto;\"><div class=\"rl-card-body\" style=\"display:flex;gap:12px;align-items:flex-start;\">\n            <i data-lucide=\"mail-check\" style=\"color:var(--status-success);width:22px;height:22px;flex:none;margin-top:2px;\"></i>\n            <div><div style=\"font-size:15px;font-weight:600;\">Check your email</div><div style=\"font-size:12.5px;color:var(--fg-muted);margin-top:4px;\">We sent a verification link to <span class=\"mono\"><a href=\"/cdn-cgi/l/email-protection\" class=\"__cf_email__\" data-cfemail=\"5e27312b1e3b263f332e323b703d3133\">[email&#160;protected]</a></span>. It expires in 24 hours.</div></div>\n          </div></div>\n        </div>\n      </div>\n    </li>\n    <li><strong data-id=\"Buka menu Add.\">Open the Add menu.</strong>\n      <p data-id=\"Di sidebar, klik &lt;strong class=&quot;inline&quot;&gt;Add&lt;/strong&gt; untuk menampilkan tiga opsi scan.\">In the sidebar, click <strong class=\"inline\">Add</strong> to reveal the three scan options.</p>\n      <div class=\"shot\">\n        <div class=\"shot-bar\"><span class=\"traffic\"><i></i><i></i><i></i></span><span class=\"url\">app.counterattack.com/dashboard</span></div>\n        <div class=\"shot-body\">\n          <div style=\"max-width:240px;background:var(--bg-surface-1);border:1px solid var(--border-subtle);border-radius:12px;padding:10px;\">\n            <div style=\"display:flex;align-items:center;justify-content:space-between;padding:7px 10px;border-radius:8px;background:var(--bg-surface-2);\"><span style=\"display:flex;align-items:center;gap:8px;font-size:13.5px;\"><i data-lucide=\"plus\" style=\"width:16px;height:16px;color:var(--accent)\"></i> Add</span><i data-lucide=\"chevron-down\" style=\"width:14px;height:14px;color:var(--fg-muted)\"></i></div>\n            <div style=\"margin:4px 0 0 12px;border-left:1px solid var(--border-subtle);padding-left:8px;\">\n              <div style=\"display:flex;align-items:center;gap:8px;padding:6px 8px;border-radius:8px;background:var(--accent-soft);font-size:13px;color:var(--accent)\"><i data-lucide=\"scan-search\" style=\"width:14px;height:14px;\"></i> Full Scan</div>\n              <div style=\"display:flex;align-items:center;gap:8px;padding:6px 8px;font-size:13px;color:var(--fg-muted)\"><i data-lucide=\"shield-alert\" style=\"width:14px;height:14px;\"></i> Vulnerability Scan</div>\n              <div style=\"display:flex;align-items:center;gap:8px;padding:6px 8px;font-size:13px;color:var(--fg-muted)\"><i data-lucide=\"skull\" style=\"width:14px;height:14px;\"></i> Incident Check</div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </li>\n    <li><strong data-id=\"Mulai sebuah Full Scan.\">Start a Full Scan.</strong>\n      <p data-id=\"Pilih &lt;strong class=&quot;inline&quot;&gt;Full Scan&lt;/strong&gt; dan masukkan sebuah domain seperti &lt;code&gt;example.com&lt;/code&gt;. Tekan &lt;strong class=&quot;inline&quot;&gt;Enter&lt;/strong&gt; untuk memulai. CounterAttack membuat asset group untuk root domain tersebut secara otomatis.\">Pick <strong class=\"inline\">Full Scan</strong> and enter a domain such as <code>example.com</code>. Press <strong class=\"inline\">Enter</strong> to begin. CounterAttack creates an asset group for that root domain automatically.</p>\n      <div class=\"shot\">\n        <div class=\"shot-bar\"><span class=\"traffic\"><i></i><i></i><i></i></span><span class=\"url\">app.counterattack.com/scan/new</span></div>\n        <div class=\"shot-body\">\n          <div class=\"rl-card\" style=\"max-width:520px;margin:0 auto;\"><div class=\"rl-card-body\">\n            <div style=\"font-size:16px;font-weight:600;margin-bottom:4px;\">Run a full scan</div>\n            <div style=\"font-size:12.5px;color:var(--fg-muted);margin-bottom:14px;\">We will run both scans on this domain. This usually takes 25 to 40 minutes.</div>\n            <div class=\"pg-inputrow\"><input class=\"input\" value=\"example.com\" readonly /><button class=\"btn btn-primary\"><i data-lucide=\"corner-down-left\"></i> Enter</button></div>\n            <div style=\"margin-top:12px;font-size:12px;color:var(--fg-subtle);display:flex;align-items:center;gap:6px;\"><i data-lucide=\"sliders-horizontal\" style=\"width:14px;height:14px;\"></i> Scan options &middot; Port scan: Quick &middot; Auto-rescan: Off</div>\n          </div></div>\n        </div>\n      </div>\n    </li>\n    <li><strong data-id=\"Pantau prosesnya berjalan.\">Watch it run.</strong>\n      <p data-id=\"Halaman scan langsung menampilkan setiap tahap saat terjadi: discovery, fingerprinting, port scan, screenshot, vulnerability analysis, lalu incident check.\">The live scan page streams each stage as it happens: discovery, fingerprinting, port scan, screenshots, vulnerability analysis, and then the incident check.</p>\n      <div class=\"shot\">\n        <div class=\"shot-bar\"><span class=\"traffic\"><i></i><i></i><i></i></span><span class=\"url\">app.counterattack.com/scans/a7f3c1</span></div>\n        <div class=\"shot-body\">\n          <div style=\"display:flex;align-items:center;gap:10px;margin-bottom:10px;\"><span class=\"pill run\"><i data-lucide=\"loader-2\" class=\"spin\" style=\"width:12px;height:12px;\"></i> Running</span><span style=\"margin-left:auto;font-size:12px;color:var(--fg-muted);\">48% &middot; 9m elapsed</span></div>\n          <div class=\"pg-track\" style=\"margin-bottom:12px;\"><div class=\"pg-fill\" style=\"width:48%\"></div></div>\n          <div class=\"pg-stage done\"><span class=\"pg-dot\"></span><div><div class=\"pg-stage-name\">Asset Discovery</div></div><span class=\"pg-stage-state\">complete</span></div>\n          <div class=\"pg-stage running\"><span class=\"pg-dot\"></span><div><div class=\"pg-stage-name\">Vulnerability Analysis</div></div><span class=\"pg-stage-state\">running</span></div>\n        </div>\n      </div>\n    </li>\n    <li><strong data-id=\"Baca hasil Anda.\">Read your results.</strong>\n      <p data-id=\"Setelah selesai, buka asset group untuk melihat aset yang ditemukan, Vulnerabilities, Incidents, dan, pada paket berbayar, Security rating A sampai F Anda.\">When it finishes, open the asset group to see discovered assets, Vulnerabilities, Incidents, and, on paid plans, your A to F security rating.</p>\n      <div class=\"shot\">\n        <div class=\"shot-bar\"><span class=\"traffic\"><i></i><i></i><i></i></span><span class=\"url\">app.counterattack.com/groups/example-com</span></div>\n        <div class=\"shot-body\">\n          <div class=\"kpi-row\" style=\"grid-template-columns:repeat(3,1fr);margin-bottom:12px;\">\n            <div class=\"kpi\"><div class=\"k-label\">Assets</div><div class=\"k-value\">40</div></div>\n            <div class=\"kpi\"><div class=\"k-label\">Open Vulns</div><div class=\"k-value\" style=\"color:var(--sev-critical)\">9</div></div>\n            <div class=\"kpi\"><div class=\"k-label\">Rating</div><div class=\"k-value\" style=\"color:var(--sev-high)\">D</div></div>\n          </div>\n          <div class=\"pg-finding\" style=\"border:none;padding:6px 0;\"><span class=\"badge sev-critical\"><span class=\"dot\"></span>Critical</span><div class=\"pg-finding-main\"><div class=\"pg-finding-title\">Subdomain takeover on dangling CNAME</div><div class=\"pg-finding-sub\"><span class=\"mono\">legacy.example.com</span> &middot; Exposure</div></div></div>\n        </div>\n      </div>\n    </li>\n  </ol>\n\n  <div class=\"callout note\"><i data-lucide=\"info\"></i><div><p data-id=\"Setiap paket, termasuk Free, menjalankan seluruh alur kerja scan. Yang ditambahkan paket berbayar adalah kapasitas aset yang lebih besar, hasil aset tanpa batas, laporan, scan berkelanjutan, Security rating, dan akses tim.\">Every plan, including Free, runs the entire scan workflow. What the paid plans add is a larger asset capacity, unlimited asset results, reports, continuous scanning, the security rating, and team access.</p></div></div>\n\n  <div class=\"pager\"><a href=\"#/introduction\"><div class=\"dir\" data-id=\"Sebelumnya\">Previous</div><div class=\"ttl\">&larr; Welcome</div></a><a class=\"next\" href=\"#/accounts\"><div class=\"dir\" data-id=\"Berikutnya\">Next</div><div class=\"ttl\">Accounts &amp; sign-up &rarr;</div></a></div>"
  },
  "accounts": {
    "id": "accounts",
    "title": "Accounts &amp; sign-up",
    "eyebrow": "Getting started",
    "lede": "Every account gets its own private scan workspace. Your assets, findings, and reports are visible only to you. Getting in takes three steps: sign up, verify your email, and accept the Terms.",
    "html": "<span class=\"eyebrow\" data-id=\"Memulai\">Getting started</span>\n  <h1 data-id=\"Akun &amp;amp; pendaftaran\">Accounts &amp; sign-up</h1>\n  <p class=\"lede\" data-id=\"Setiap akun mendapat ruang kerja scan pribadinya sendiri. Aset, temuan, dan laporan Anda hanya bisa dilihat oleh Anda. Untuk masuk ada tiga langkah: daftar, verifikasi email Anda, dan setujui Terms.\">Every account gets its own private scan workspace. Your assets, findings, and reports are visible only to you. Getting in takes three steps: sign up, verify your email, and accept the Terms.</p>\n\n  <h2 data-id=\"1. Daftar\">1. Sign up</h2>\n  <p data-id=\"Di halaman pendaftaran Anda mengisi &lt;strong&gt;email&lt;/strong&gt;, &lt;strong&gt;display name&lt;/strong&gt; opsional, dan &lt;strong&gt;password&lt;/strong&gt; minimal 8 karakter, yang Anda konfirmasi. Klik &lt;strong&gt;Create account&lt;/strong&gt;. CounterAttack tidak otomatis membuat Anda masuk. Sebagai gantinya CounterAttack mengirim email verifikasi, dan formulir diganti dengan panel &quot;Check your email&quot;. Tautan verifikasi kedaluwarsa setelah 24 jam, dan Anda bisa mengirim ulang.\">On the sign-up page you provide an <strong>email</strong>, an optional <strong>display name</strong>, and a <strong>password</strong> of at least 8 characters, which you confirm. Click <strong>Create account</strong>. CounterAttack does not sign you in automatically. Instead it sends a verification email, and the form is replaced by a \"Check your email\" panel. The verification link expires after 24 hours, and you can resend it.</p>\n  <div class=\"shot\">\n    <div class=\"shot-bar\"><span class=\"traffic\"><i></i><i></i><i></i></span><span class=\"url\">app.counterattack.com/signup</span></div>\n    <div class=\"shot-body\">\n      <div class=\"rl-card\" style=\"max-width:400px;margin:0 auto;\"><div class=\"rl-card-body\">\n        <div style=\"font-size:16px;font-weight:600;margin-bottom:14px;\">Create your account</div>\n        <div class=\"field\"><label>Email</label><input class=\"input\" value=\"you@example.com\" readonly /></div>\n        <div class=\"field\"><label>Display name (optional)</label><input class=\"input\" value=\"Andi Pratama\" readonly /></div>\n        <div class=\"field\"><label>Password</label><input class=\"input\" type=\"password\" value=\"secretpass\" readonly /></div>\n        <button class=\"btn btn-primary\" style=\"width:100%;justify-content:center;\">Create account</button>\n      </div></div>\n    </div>\n  </div>\n\n  <h2 data-id=\"2. Verifikasi email Anda\">2. Verify your email</h2>\n  <p data-id=\"Buka email dan klik tautannya. Halaman verifikasi mengonfirmasi akun Anda secara otomatis dan menampilkan &quot;Your account is now active.&quot; Setelah itu Anda bisa masuk.\">Open the email and click the link. The verify page confirms your account automatically and shows \"Your account is now active.\" You can then sign in.</p>\n  <div class=\"shot\">\n    <div class=\"shot-bar\"><span class=\"traffic\"><i></i><i></i><i></i></span><span class=\"url\">app.counterattack.com/verify-email</span></div>\n    <div class=\"shot-body\">\n      <div class=\"rl-card\" style=\"max-width:400px;margin:0 auto;text-align:center;\"><div class=\"rl-card-body\">\n        <i data-lucide=\"check-circle-2\" style=\"color:var(--status-success);width:34px;height:34px;\"></i>\n        <div style=\"font-size:16px;font-weight:600;margin-top:10px;\">Email verified</div>\n        <div style=\"font-size:12.5px;color:var(--fg-muted);margin:4px 0 14px;\">Your account is now active. You can sign in.</div>\n        <button class=\"btn btn-primary\" style=\"justify-content:center;\">Go to sign in</button>\n      </div></div>\n    </div>\n  </div>\n\n  <h2 data-id=\"3. Masuk\">3. Sign in</h2>\n  <p data-id=\"Di halaman login, masukkan email dan password Anda. Ada checkbox &lt;strong&gt;Keep me signed in for 7 days&lt;/strong&gt;. Biarkan tidak aktif dan Anda akan keluar begitu menutup browser. Aktifkan untuk tetap masuk di perangkat tepercaya. Jika Anda lupa password, tautan &lt;strong&gt;Forgot password?&lt;/strong&gt; akan mengirimkan email berisi tautan reset yang berlaku selama satu jam.\">On the login page, enter your email and password. There is a <strong>Keep me signed in for 7 days</strong> checkbox. Leave it off and you will be signed out as soon as you close the browser. Turn it on to stay signed in on a trusted device. If you forget your password, the <strong>Forgot password?</strong> link emails you a reset link that is valid for one hour.</p>\n  <div class=\"shot\">\n    <div class=\"shot-bar\"><span class=\"traffic\"><i></i><i></i><i></i></span><span class=\"url\">app.counterattack.com/login</span></div>\n    <div class=\"shot-body\">\n      <div class=\"rl-card\" style=\"max-width:400px;margin:0 auto;\"><div class=\"rl-card-body\">\n        <div style=\"font-size:16px;font-weight:600;margin-bottom:14px;\">Sign in</div>\n        <div class=\"field\"><label>Email</label><input class=\"input\" value=\"you@example.com\" readonly /></div>\n        <div class=\"field\"><label>Password</label><input class=\"input\" type=\"password\" value=\"secretpass\" readonly /></div>\n        <label class=\"chk-row\" style=\"display:flex;align-items:center;gap:8px;font-size:12.5px;color:var(--fg-muted);margin-bottom:14px;\"><span class=\"chk on\"><i data-lucide=\"check\"></i></span> Keep me signed in for 7 days</label>\n        <button class=\"btn btn-primary\" style=\"width:100%;justify-content:center;\">Sign in</button>\n      </div></div>\n    </div>\n  </div>\n\n  <h2 data-id=\"4. Setujui Terms\">4. Accept the Terms</h2>\n  <p data-id=\"Saat pertama kali masuk, CounterAttack menampilkan gerbang layar penuh berjudul &lt;strong&gt;Scan responsibly&lt;/strong&gt;. Anda harus mencentang dua kotak untuk melanjutkan:\">The first time you sign in, CounterAttack shows a full-screen gate titled <strong>Scan responsibly</strong>. You must tick two boxes to continue:</p>\n  <ul>\n    <li data-id=\"Anda menyetujui Terms of Service dan Privacy Policy.\">You agree to the Terms of Service and Privacy Policy.</li>\n    <li data-id=\"Anda mengonfirmasi bahwa Anda hanya akan scan target yang Anda miliki atau yang diizinkan untuk diuji.\">You confirm you will only scan targets you own or are authorized to test.</li>\n  </ul>\n  <p data-id=\"Setelah keduanya dicentang, &lt;strong&gt;Accept and continue&lt;/strong&gt; membawa Anda ke Dashboard. Scan tanpa izin dapat melanggar hukum termasuk UU ITE dan UU PDP di Indonesia, GDPR di Uni Eropa, dan CFAA di Amerika Serikat, sehingga persetujuan ini tidak opsional.\">Once both are ticked, <strong>Accept and continue</strong> takes you to the Dashboard. Unauthorized scanning can violate laws including Indonesia's UU ITE and UU PDP, the EU GDPR, and the US CFAA, so this consent is not optional.</p>\n  <div class=\"shot\">\n    <div class=\"shot-bar\"><span class=\"traffic\"><i></i><i></i><i></i></span><span class=\"url\">app.counterattack.com/terms/accept</span></div>\n    <div class=\"shot-body\">\n      <div class=\"rl-card\" style=\"max-width:440px;margin:0 auto;\"><div class=\"rl-card-body\">\n        <div style=\"display:flex;align-items:center;gap:8px;margin-bottom:2px;\"><i data-lucide=\"shield-alert\" style=\"color:var(--accent);width:20px;height:20px;\"></i><span style=\"font-size:16px;font-weight:600;\">Scan responsibly</span></div>\n        <div style=\"font-size:12.5px;color:var(--fg-muted);margin-bottom:14px;\">One last step before you can scan.</div>\n        <label class=\"chk-row\" style=\"display:flex;gap:8px;align-items:flex-start;font-size:12.5px;color:var(--fg-muted);margin-bottom:10px;\"><span class=\"chk\" style=\"margin-top:1px;\"><i data-lucide=\"check\"></i></span> I agree to the Terms of Service and Privacy Policy.</label>\n        <label class=\"chk-row\" style=\"display:flex;gap:8px;align-items:flex-start;font-size:12.5px;color:var(--fg-muted);margin-bottom:14px;\"><span class=\"chk\" style=\"margin-top:1px;\"><i data-lucide=\"check\"></i></span> I will only scan targets I own or am authorized to test.</label>\n        <button class=\"btn btn-primary\" style=\"width:100%;justify-content:center;\">Accept and continue</button>\n      </div></div>\n    </div>\n  </div>\n\n  <div class=\"callout note\"><i data-lucide=\"key-round\"></i><div><span class=\"callout-title\" data-id=\"Peran\">Roles</span><p data-id=\"Akun Anda sendiri selalu menjadi &lt;strong&gt;owner&lt;/strong&gt; workspace-nya, dengan akses penuh. Role hanya berlaku ketika Anda diundang ke workspace orang lain, atau ketika Anda mengundang orang lain ke workspace Anda: setiap member memegang role Admin, Analyst, Viewer, atau custom role, dibatasi pada asset group tertentu. Lihat &lt;a href=&quot;#/permissions&quot;&gt;Role &amp;amp; permission&lt;/a&gt;.\">Your own account is always the <strong>owner</strong> of its workspace, with full access. Roles only come into play when you are invited into someone else's workspace, or when you invite other people into yours: each member holds an Admin, Analyst, Viewer or custom role, scoped to particular asset groups. See <a href=\"#/permissions\">Roles &amp; permissions</a>.</p></div></div>\n\n  <div class=\"pager\"><a href=\"#/quickstart\"><div class=\"dir\" data-id=\"Sebelumnya\">Previous</div><div class=\"ttl\">&larr; Quickstart</div></a><a class=\"next\" href=\"#/dashboard\"><div class=\"dir\" data-id=\"Berikutnya\">Next</div><div class=\"ttl\">Dashboard &rarr;</div></a></div>"
  },
  "dashboard": {
    "id": "dashboard",
    "title": "Dashboard",
    "eyebrow": "Core workflow",
    "lede": "The Dashboard is your command center, an Attack Surface Overview that summarizes every asset, open vulnerability, open incident, and your posture across all groups. It refreshes on its own every 60 seconds and shows when it last updated.",
    "html": "<span class=\"eyebrow\" data-id=\"Alur kerja inti\">Core workflow</span>\n  <h1>Dashboard</h1>\n  <p class=\"lede\" data-id=\"Dashboard adalah pusat kendali Anda, sebuah Attack Surface Overview yang merangkum setiap aset, vulnerability terbuka, incident terbuka, dan postur keamanan Anda di seluruh grup. Dashboard menyegarkan dirinya sendiri setiap 60 detik dan menunjukkan kapan terakhir diperbarui.\">The Dashboard is your command center, an Attack Surface Overview that summarizes every asset, open vulnerability, open incident, and your posture across all groups. It refreshes on its own every 60 seconds and shows when it last updated.</p>\n\n  <div class=\"shot\">\n    <div class=\"shot-bar\"><span class=\"traffic\"><i></i><i></i><i></i></span><span class=\"url\">app.counterattack.com/dashboard</span></div>\n    <div class=\"shot-body\">\n      <div class=\"callout\" style=\"border-left-color:var(--sev-critical);background:rgba(239,68,68,0.08);margin-bottom:16px;\"><i data-lucide=\"alert-triangle\" style=\"color:var(--sev-critical)\"></i><div><p style=\"margin:0;color:var(--fg-default)\"><strong>3 critical exposures need attention.</strong> View all open findings.</p></div></div>\n      <div class=\"kpi-row\" style=\"grid-template-columns:repeat(5,1fr);\">\n        <div class=\"kpi\"><div class=\"k-label\">Total Assets</div><div class=\"k-value\">128</div><div class=\"k-sub\">+6 this week</div></div>\n        <div class=\"kpi\"><div class=\"k-label\">Asset Groups</div><div class=\"k-value\">7</div></div>\n        <div class=\"kpi\"><div class=\"k-label\">Open Vulns</div><div class=\"k-value\" style=\"color:var(--sev-critical)\">17</div><div class=\"k-sub\">3 critical</div></div>\n        <div class=\"kpi\"><div class=\"k-label\">Open Incidents</div><div class=\"k-value\" style=\"color:var(--sev-high)\">4</div><div class=\"k-sub\">1 critical</div></div>\n        <div class=\"kpi\"><div class=\"k-label\">Scans / week</div><div class=\"k-value\">21</div></div>\n      </div>\n    </div>\n  </div>\n  <p class=\"shot-cap\" data-id=\"Banner status, lalu deretan kartu KPI yang bisa diklik.\">The status banner, then a row of clickable KPI cards.</p>\n\n  <h2 data-id=\"Banner status\">Status banner</h2>\n  <p data-id=\"Satu garis berwarna di bagian atas memberi tahu posisi Anda dalam sekali lihat. Hijau berarti tidak ada temuan critical atau high-severity yang terbuka. Kuning menandai eksposur high-severity, dan merah menandai yang critical. Mengekliknya membuka antrean temuan lengkap.\">A single colored line at the top tells you where you stand at a glance. Green means no critical or high-severity findings are open. Amber flags high-severity exposures, and red flags critical ones. Clicking it opens the full findings queue.</p>\n\n  <h2 data-id=\"Kartu KPI\">KPI cards</h2>\n  <p data-id=\"Lima kartu, masing-masing bisa diklik, membawa Anda ke tampilan terkait: &lt;strong&gt;Total Assets&lt;/strong&gt;, &lt;strong&gt;Asset Groups&lt;/strong&gt;, &lt;strong&gt;Open Vulnerabilities&lt;/strong&gt;, &lt;strong&gt;Open Incidents&lt;/strong&gt;, dan &lt;strong&gt;Scans This Week&lt;/strong&gt;. Kartu vulnerability dan incident berubah menjadi merah atau kuning sesuai severity terbuka terburuk Anda.\">Five cards, each clickable, take you to the underlying view: <strong>Total Assets</strong>, <strong>Asset Groups</strong>, <strong>Open Vulnerabilities</strong>, <strong>Open Incidents</strong>, and <strong>Scans This Week</strong>. The vulnerability and incident cards turn red or amber to match your worst open severity.</p>\n\n  <h2 data-id=\"Blok Security rating\">Security rating block</h2>\n  <p data-id=\"Pada paket berbayar, dua kartu nilai menampilkan &lt;strong&gt;Vulnerability Rating&lt;/strong&gt; dan &lt;strong&gt;Incident Rating&lt;/strong&gt; tingkat organisasi Anda, dari A sampai F. Di bawahnya, tabel &quot;Groups by Security Rating&quot; menampilkan grup terburuk Anda lebih dulu, masing-masing dengan pil nilai, root domain, dan jumlah asetnya. Paket Free melihat kartu upgrade di sini. Dari blok ini Anda juga bisa &lt;strong&gt;Generate report&lt;/strong&gt;.\">On paid plans, two grade cards show your org-wide <strong>Vulnerability Rating</strong> and <strong>Incident Rating</strong>, from A to F. Below them, a \"Groups by Security Rating\" table lists your worst groups first, each with its grade pills, root domain, and asset count. Free plans see an upgrade card here instead. From this block you can also <strong>Generate report</strong>.</p>\n\n  <h2 data-id=\"Grafik rincian dan tabel terbaru\">Breakdown charts and recent tables</h2>\n  <p data-id=\"Bar severity merinci Vulnerabilities terbuka dan Incidents terbuka, dan grafik kategori mengelompokkannya berdasarkan jenis (CVE, Exposure, Misconfig, Weak Creds, SSL/TLS, DNS, Defacement, Gambling, SEO Spam, dan Other). Dua tabel, &lt;strong&gt;Recent Vulnerabilities&lt;/strong&gt; dan &lt;strong&gt;Recent Incidents&lt;/strong&gt;, menampilkan item terbaru dengan severity, judul, host, kategori, usia, dan status. Baris dapat diklik menuju halaman detail.\">Severity bars break down open Vulnerabilities and open Incidents, and category charts group them by type (CVE, Exposure, Misconfig, Weak Creds, SSL/TLS, DNS, Defacement, Gambling, SEO Spam, and Other). Two tables, <strong>Recent Vulnerabilities</strong> and <strong>Recent Incidents</strong>, list the latest items with severity, title, host, category, age, and status. Rows click through to the detail page.</p>\n\n  <div class=\"callout note\"><i data-lucide=\"eye-off\"></i><div><p data-id=\"Temuan dengan severity info disembunyikan di mana pun dalam CounterAttack. Antrean yang Anda lihat hanya mencakup critical, high, medium, dan low.\">Info-severity findings are hidden everywhere in CounterAttack. The queues you see only include critical, high, medium, and low.</p></div></div>\n\n  <div class=\"pager\"><a href=\"#/accounts\"><div class=\"dir\" data-id=\"Sebelumnya\">Previous</div><div class=\"ttl\">&larr; Accounts</div></a><a class=\"next\" href=\"#/groups\"><div class=\"dir\" data-id=\"Berikutnya\">Next</div><div class=\"ttl\">Asset Groups &rarr;</div></a></div>"
  },
  "groups": {
    "id": "groups",
    "title": "Asset Groups",
    "eyebrow": "Core workflow",
    "lede": "An asset group represents one root domain and holds everything CounterAttack discovered for it: subdomains and hosts, findings, incidents, screenshots, and scan history. You do not create groups by hand. Scan a domain and its group appears.",
    "html": "<span class=\"eyebrow\" data-id=\"Alur kerja inti\">Core workflow</span>\n  <h1>Asset Groups</h1>\n  <p class=\"lede\" data-id=\"Sebuah asset group mewakili satu root domain dan menyimpan semua yang CounterAttack temukan untuknya: subdomain dan host, temuan, incident, screenshot, dan riwayat scan. Anda tidak membuat grup secara manual. Scan sebuah domain dan grupnya akan muncul.\">An asset group represents one root domain and holds everything CounterAttack discovered for it: subdomains and hosts, findings, incidents, screenshots, and scan history. You do not create groups by hand. Scan a domain and its group appears.</p>\n\n  <div class=\"shot\">\n    <div class=\"shot-bar\"><span class=\"traffic\"><i></i><i></i><i></i></span><span class=\"url\">app.counterattack.com/groups</span></div>\n    <div class=\"shot-body\">\n      <div class=\"two-col\">\n        <div class=\"rl-card\"><div class=\"rl-card-body\">\n          <div class=\"mono\" style=\"font-size:14px;\">example.com</div>\n          <div style=\"font-size:12px;color:var(--fg-subtle);margin:6px 0 10px;\">40 assets &middot; last scan 2h ago</div>\n          <div class=\"tag-row\"><span class=\"badge sev-critical\"><span class=\"dot\"></span>3 critical</span><span class=\"badge sev-high\"><span class=\"dot\"></span>9 findings</span></div>\n        </div></div>\n        <div class=\"rl-card\"><div class=\"rl-card-body\">\n          <div class=\"mono\" style=\"font-size:14px;\">shop.example.net</div>\n          <div style=\"font-size:12px;color:var(--fg-subtle);margin:6px 0 10px;\">12 assets &middot; last scan 1d ago</div>\n          <div class=\"tag-row\"><span class=\"pill ok\"><i data-lucide=\"shield-check\" style=\"width:12px;height:12px;\"></i> Secure</span></div>\n        </div></div>\n      </div>\n    </div>\n  </div>\n  <p class=\"shot-cap\" data-id=\"Setiap grup berupa kartu yang menampilkan root domain, jumlah aset, dan badge statusnya.\">Each group is a card showing its root domain, asset count, and status badges.</p>\n\n  <h2 data-id=\"Daftar grup\">The groups list</h2>\n  <p data-id=\"Setiap kartu grup menampilkan root domain, tombol tautan eksternal, jumlah aset dan waktu scan terakhir, serta badge status: merah untuk jumlah critical, kuning untuk temuan lain, oranye untuk incident, atau pil hijau &lt;strong&gt;Secure&lt;/strong&gt; saat semuanya bersih. Grup yang dipindai sebagai satu host membawa badge &lt;strong&gt;single host&lt;/strong&gt;, artinya hanya hostname yang diketik yang dipindai dan penemuan subdomain dilewati.\">Each group card shows the root domain, an external-link button, the asset count and last-scan time, and status badges: red for critical counts, amber for other findings, orange for incidents, or a green <strong>Secure</strong> pill when everything is clean. A group scanned as a single host carries a <strong>single host</strong> badge, meaning only the typed hostname was scanned and subdomain discovery was skipped.</p>\n\n  <h2 data-id=\"Kuota aset\">Asset quota</h2>\n  <p data-id=\"Paket berbayar dibatasi oleh jumlah &lt;strong&gt;total aset&lt;/strong&gt; yang ditemukan di seluruh asset group Anda digabung, bukan oleh jumlah root domain: Starter mencakup 100 aset, Business 500, MSSP sesuai kontrak, dan Enterprise tanpa batas. Pada paket berbayar Anda bisa menambahkan root domain sebanyak yang diperlukan. Free berbeda: satu root domain, dan hanya 20 aset pertama setiap grup yang ditampilkan. Header halaman Asset Groups menampilkan penggunaan aset Anda terhadap batasnya. Lihat &lt;a href=&quot;#/plans&quot;&gt;Paket &amp;amp; upgrade&lt;/a&gt;.\">Paid plans are capped by the number of <strong>total assets</strong> discovered across all your asset groups combined, not by root domains: Starter includes 100 assets, Business 500, MSSP per contract, and Enterprise is unlimited. On a paid plan you can add as many root domains as you need. Free is different: one root domain, and only the first 20 assets of each group are shown. The Asset Groups page header shows your asset usage against the cap. See <a href=\"#/plans\">Plans &amp; upgrading</a>.</p>\n\n  <h2 data-id=\"Detail grup\">Group detail</h2>\n  <p data-id=\"Membuka sebuah grup menampilkan kartu rating-nya, ringkasan temuan dengan chip filter yang bisa diklik (SSL/TLS, host aktif, host di belakang CDN, host dengan vulnerabilities, teknologi unik), deretan chip severity, dan kartu port terbuka. Lima tab menata sisanya:\">Opening a group shows its rating cards, a finding summary with clickable filter chips (SSL/TLS, live hosts, hosts behind a CDN, hosts with vulnerabilities, unique technologies), a severity chip row, and an open-ports card. Five tabs organize the rest:</p>\n  <ul>\n    <li data-id=\"&lt;strong&gt;Assets&lt;/strong&gt;: setiap host yang ditemukan, bisa dicari dan difilter, dengan screenshot, hostname, status HTTP, port, teknologi, status TLS, jumlah temuan terbuka, dan nilai per host.\"><strong>Assets</strong>: every discovered host, searchable and filterable, with screenshot, hostname, HTTP status, ports, technology, TLS state, open-finding count, and a per-host grade.</li>\n    <li data-id=\"&lt;strong&gt;Status&lt;/strong&gt;: indikator alur kerja untuk scan terbaru, dengan pembacaan progres langsung.\"><strong>Status</strong>: the workflow indicator for the latest scan, with a live progress readout.</li>\n    <li data-id=\"&lt;strong&gt;Vulnerabilities&lt;/strong&gt;: vulnerabilities terbuka di grup ini, berdasarkan severity, judul, host, kategori, dan usia.\"><strong>Vulnerabilities</strong>: open vulnerabilities in this group, by severity, title, host, category, and age.</li>\n    <li data-id=\"&lt;strong&gt;Incidents&lt;/strong&gt;: petak incident dengan thumbnail screenshot dan panduan &quot;how to validate&quot;.\"><strong>Incidents</strong>: incident tiles with screenshot thumbnails and a \"how to validate\" advisory.</li>\n    <li data-id=\"&lt;strong&gt;History&lt;/strong&gt;: linimasa scan yang selesai dengan jumlah temuan baru dan yang diselesaikan, durasi, status, dan unduhan laporan.\"><strong>History</strong>: a timeline of completed scans with new and resolved counts, duration, status, and a report download.</li>\n  </ul>\n\n  <h2 data-id=\"Detail aset\">Asset detail</h2>\n  <p data-id=\"Setiap aset memiliki halamannya sendiri: screenshot satu halaman penuh, hostname, status HTTP dan judul halaman, chip teknologi, kartu ikhtisar (alamat IP, CDN, server, TLS, pertama dan terakhir terlihat), vulnerabilities-nya, dan kartu port terbuka yang mencantumkan setiap port dengan protokol, layanan, dan fingerprint versinya.\">Each asset has its own page: a full-page screenshot, hostname, HTTP status and page title, technology chips, an overview card (IP addresses, CDN, server, TLS, first and last seen), its vulnerabilities, and an open-ports card that lists each port with its protocol, service, and version fingerprint.</p>\n\n  <h2 data-id=\"Aksi massal dan pengecualian\">Bulk actions and exclusions</h2>\n  <p data-id=\"Di tabel aset, admin bisa masuk ke mode &lt;strong&gt;Select&lt;/strong&gt; untuk bertindak pada banyak host sekaligus: pindai ulang temuan atau incident, selesaikan, tandai false positive, atau &lt;strong&gt;exclude from scans&lt;/strong&gt;. Host yang dikecualikan (misalnya sebuah honeypot) dilewati di setiap tahap, tanpa paket yang dikirim, dan disembunyikan sampai Anda mengaktifkan &lt;strong&gt;Show excluded&lt;/strong&gt;.\">In the asset table, admins can enter <strong>Select</strong> mode to act on many hosts at once: rescan findings or incidents, resolve, mark false positive, or <strong>exclude from scans</strong>. An excluded host (for example a honeypot) is skipped at every stage, with no packets sent, and is hidden until you toggle <strong>Show excluded</strong>.</p>\n\n  <div class=\"callout warn\"><i data-lucide=\"lock\"></i><div><span class=\"callout-title\" data-id=\"Batas hasil Free\">Free result cap</span><p data-id=\"Scan Free memetakan seluruh attack surface Anda tetapi hanya menampilkan 20 hasil aset pertama per root domain. Sisanya diburamkan di balik kunci yang tetap menunjukkan berapa banyak temuan critical dan high yang tersembunyi. Upgrade ke Starter untuk menampilkan setiap subdomain.\">Free scans map your whole attack surface but reveal only the first 20 asset results per root domain. The rest are blurred behind a lock that still shows how many hidden critical and high findings exist. Upgrade to Starter to reveal every subdomain.</p></div></div>\n\n  <div class=\"pager\"><a href=\"#/dashboard\"><div class=\"dir\" data-id=\"Sebelumnya\">Previous</div><div class=\"ttl\">&larr; Dashboard</div></a><a class=\"next\" href=\"#/scans\"><div class=\"dir\" data-id=\"Berikutnya\">Next</div><div class=\"ttl\">Running scans &rarr;</div></a></div>"
  },
  "scans": {
    "id": "scans",
    "title": "Running scans",
    "eyebrow": "Core workflow",
    "lede": "CounterAttack has three scan entry points, all reached from the Add menu in the sidebar. Scans run one at a time per account, in the order you start them.",
    "html": "<span class=\"eyebrow\" data-id=\"Alur kerja inti\">Core workflow</span>\n  <h1 data-id=\"Menjalankan scan\">Running scans</h1>\n  <p class=\"lede\" data-id=\"CounterAttack memiliki tiga titik masuk scan, semuanya diakses dari menu &lt;strong&gt;Add&lt;/strong&gt; di sidebar. Scan berjalan satu per satu per akun, sesuai urutan Anda memulainya.\">CounterAttack has three scan entry points, all reached from the <strong>Add</strong> menu in the sidebar. Scans run one at a time per account, in the order you start them.</p>\n\n  <h2 data-id=\"Tiga mode scan\">The three scan modes</h2>\n  <div class=\"feature-grid js-select\">\n    <div class=\"feature-card js-opt is-sel\"><div class=\"fc-icon\"><i data-lucide=\"scan-search\"></i></div><h4>Full Scan</h4><p data-id=\"Menjalankan alur kerja vulnerability dan incident check pada satu domain, dari satu input. Penemuan subdomain selalu aktif. Pilihan default terbaik.\">Runs the vulnerability workflow and the incident check on one domain, from a single input. Subdomain discovery is always on. Best default.</p></div>\n    <div class=\"feature-card js-opt\"><div class=\"fc-icon\"><i data-lucide=\"shield-alert\"></i></div><h4>Vulnerability Scan</h4><p data-id=\"Menemukan subdomain, mem-fingerprint teknologi, mengambil screenshot, lalu menganalisis vulnerabilities. Menambahkan toggle scope single-host.\">Discovers subdomains, fingerprints technology, captures screenshots, then analyzes for vulnerabilities. Adds a single-host scope toggle.</p></div>\n    <div class=\"feature-card js-opt\"><div class=\"fc-icon\"><i data-lucide=\"skull\"></i></div><h4>Incident Check</h4><p data-id=\"Mencari signature defacement dan injeksi di web publik, lalu memverifikasi setiap kecocokan pada halaman langsung.\">Searches the public web for defacement and injection signatures, then verifies each hit on the live page.</p></div>\n  </div>\n\n  <h2 data-id=\"Memulai sebuah scan\">Starting a scan</h2>\n  <p data-id=\"Ketik sebuah domain ke input dan tekan &lt;strong&gt;Enter&lt;/strong&gt;. Bagian &lt;strong&gt;Scan options&lt;/strong&gt; yang bisa dilipat memungkinkan Anda menyesuaikan proses:\">Type a domain into the input and press <strong>Enter</strong>. A collapsible <strong>Scan options</strong> section lets you tune the run:</p>\n  <ul>\n    <li data-id=\"&lt;strong&gt;Scope&lt;/strong&gt; (khusus Vulnerability Scan): &lt;em&gt;Discover subdomains&lt;/em&gt; mengenumerasi dan memindai setiap host aktif, atau &lt;em&gt;Single host only&lt;/em&gt; hanya memindai hostname yang Anda ketik.\"><strong>Scope</strong> (Vulnerability Scan only): <em>Discover subdomains</em> enumerates and scans every live host, or <em>Single host only</em> scans just the hostname you typed.</li>\n    <li data-id=\"&lt;strong&gt;Port scan intensity&lt;/strong&gt; (Full Scan): &lt;em&gt;Quick&lt;/em&gt; mencakup port web umum dan port sensitif serta cocok untuk kebanyakan proses, &lt;em&gt;Deep&lt;/em&gt; mencakup 1000 port teratas plus port bernilai tinggi terpilih, dan &lt;em&gt;Stealth&lt;/em&gt; menggunakan sekumpulan kecil port dengan laju kirim yang sangat rendah.\"><strong>Port scan intensity</strong> (Full Scan): <em>Quick</em> covers common web and sensitive ports and suits most runs, <em>Deep</em> covers the top 1000 plus curated high-value ports, and <em>Stealth</em> uses a small port set at a very low send rate.</li>\n    <li data-id=\"&lt;strong&gt;Auto-rescan cadence&lt;/strong&gt;: Off, Daily, Weekly, atau Monthly, dengan jam tertentu dalam waktu lokal Anda. Ini adalah fitur berbayar.\"><strong>Auto-rescan cadence</strong>: Off, Daily, Weekly, or Monthly, with an hour-of-day in your local time. This is a paid feature.</li>\n  </ul>\n  <div class=\"shot\">\n    <div class=\"shot-bar\"><span class=\"traffic\"><i></i><i></i><i></i></span><span class=\"url\">app.counterattack.com/scan/full</span></div>\n    <div class=\"shot-body\">\n      <div class=\"rl-card\" style=\"max-width:540px;margin:0 auto;\"><div class=\"rl-card-body\">\n        <div style=\"font-size:15px;font-weight:600;margin-bottom:10px;\">What do you want to scan?</div>\n        <div class=\"pg-inputrow\" style=\"margin-bottom:12px;\"><input class=\"input\" value=\"example.com\" readonly /><button class=\"btn btn-primary\"><i data-lucide=\"corner-down-left\"></i> Enter</button></div>\n        <div style=\"font-size:11px;text-transform:uppercase;letter-spacing:0.06em;color:var(--fg-subtle);margin-bottom:6px;\">Scope</div>\n        <div class=\"tag-row js-select\"><span class=\"pill js-opt is-sel\">Discover subdomains</span><span class=\"pill js-opt\">Single host only</span></div>\n        <div style=\"border-top:1px solid var(--border-subtle);margin-top:12px;padding-top:12px;\">\n          <div style=\"font-size:11px;text-transform:uppercase;letter-spacing:0.06em;color:var(--fg-subtle);margin-bottom:6px;\">Port scan intensity</div>\n          <div class=\"tag-row js-select\"><span class=\"pill js-opt is-sel\">Quick</span><span class=\"pill js-opt\">Deep</span><span class=\"pill js-opt\">Stealth</span></div>\n          <div style=\"font-size:11px;text-transform:uppercase;letter-spacing:0.06em;color:var(--fg-subtle);margin:10px 0 6px;\">Auto-rescan</div>\n          <div class=\"tag-row js-select\"><span class=\"pill js-opt is-sel\">Off</span><span class=\"pill js-opt\">Daily</span><span class=\"pill js-opt\">Weekly</span><span class=\"pill js-opt\">Monthly</span></div>\n        </div>\n      </div></div>\n    </div>\n  </div>\n\n  <h2 data-id=\"Alur kerja lima tahap\">The five-stage workflow</h2>\n  <p data-id=\"Sebuah vulnerability scan selalu menjalankan lima tahap yang sama secara berurutan:\">A vulnerability scan always runs the same five stages in order:</p>\n  <ol class=\"steps\">\n    <li><strong>Discover</strong><span class=\"subtle\" data-id=\" Enumerasi subdomain menggunakan Subfinder plus sumber publik seperti Certificate Transparency dan HackerTarget.\"> Enumerate subdomains using Subfinder plus public sources like Certificate Transparency and HackerTarget.</span></li>\n    <li><strong>Probe</strong><span class=\"subtle\" data-id=\" Fingerprint setiap host: metadata HTTP, status, judul halaman, dan technology stack.\"> Fingerprint each host: HTTP metadata, status, page title, and technology stack.</span></li>\n    <li><strong>Port scan</strong><span class=\"subtle\" data-id=\" Sisir port terbuka, pada intensitas yang Anda pilih.\"> Sweep for open ports, at the intensity you chose.</span></li>\n    <li><strong>Capture</strong><span class=\"subtle\" data-id=\" Ambil screenshot satu halaman penuh dari setiap host aktif dengan headless Chromium.\"> Take a full-page screenshot of each live host with headless Chromium.</span></li>\n    <li><strong>Scan vulns</strong><span class=\"subtle\" data-id=\" Cocokkan setiap host dengan 14.000+ aturan deteksi, termasuk pengambilalihan dangling-subdomain, bertingkat berdasarkan severity.\"> Match every host against 1,425,000+ detection rules, including dangling-subdomain takeovers, tiered by severity.</span></li>\n  </ol>\n  <p data-id=\"Incident Check berjalan di jalur terpisah: Incident Check menanyakan mesin pencari untuk signature defacement dan SEO spam, lalu mengambil dan memverifikasi setiap halaman kandidat sebelum memunculkan sebuah incident. Sebuah Full Scan menjalankan rangkaian vulnerability, lalu rangkaian incident, sebagai satu pipeline berkelanjutan.\">The Incident Check runs on a separate track: it queries search engines for defacement and SEO-spam signatures, then fetches and verifies each candidate page before raising an incident. A Full Scan runs the vulnerability chain, then the incident chain, as one continuous pipeline.</p>\n\n  <div class=\"callout tip\"><i data-lucide=\"play\"></i><div><p data-id=\"Ingin melihatnya langsung? Buka &lt;a href=&quot;#/playground&quot;&gt;Live playground&lt;/a&gt; dan jalankan simulasi Full Scan melalui keenam tahap.\">Want to see this happen live? Open the <a href=\"#/playground\">Live playground</a> and run a simulated Full Scan through all six stages.</p></div></div>\n\n  <div class=\"pager\"><a href=\"#/groups\"><div class=\"dir\" data-id=\"Sebelumnya\">Previous</div><div class=\"ttl\">&larr; Asset Groups</div></a><a class=\"next\" href=\"#/results\"><div class=\"dir\" data-id=\"Berikutnya\">Next</div><div class=\"ttl\">Scan results &rarr;</div></a></div>"
  },
  "results": {
    "id": "results",
    "title": "Scan results",
    "eyebrow": "Core workflow",
    "lede": "The live scan page shows everything as it happens, then becomes the final result. It streams over a live connection and falls back to polling, so you can leave and come back at any time.",
    "html": "<span class=\"eyebrow\" data-id=\"Alur kerja inti\">Core workflow</span>\n  <h1 data-id=\"Hasil scan\">Scan results</h1>\n  <p class=\"lede\" data-id=\"Halaman scan langsung menampilkan semuanya saat terjadi, lalu menjadi hasil akhir. Halaman ini mengalir melalui koneksi langsung dan beralih ke polling jika perlu, sehingga Anda bisa pergi dan kembali kapan saja.\">The live scan page shows everything as it happens, then becomes the final result. It streams over a live connection and falls back to polling, so you can leave and come back at any time.</p>\n\n  <div class=\"shot\">\n    <div class=\"shot-bar\"><span class=\"traffic\"><i></i><i></i><i></i></span><span class=\"url\">app.counterattack.com/scans/a7f3c1</span></div>\n    <div class=\"shot-body\">\n      <div style=\"display:flex;align-items:center;gap:10px;margin-bottom:12px;\">\n        <span class=\"badge sev-info\" style=\"color:var(--fg-default);border-color:var(--border-default)\">FULL ASM</span>\n        <span class=\"pill run\"><i data-lucide=\"loader-2\" class=\"spin\" style=\"width:12px;height:12px;\"></i> Running</span>\n        <span style=\"margin-left:auto;font-size:12px;color:var(--fg-muted);\">62% &middot; 14m elapsed</span>\n      </div>\n      <div class=\"pg-track\" style=\"margin-bottom:14px;\"><div class=\"pg-fill\" style=\"width:62%\"></div></div>\n      <div class=\"two-col\">\n        <div class=\"pg-stage done\"><span class=\"pg-dot\"></span><div><div class=\"pg-stage-name\">Asset Discovery</div></div><span class=\"pg-stage-state\">complete</span></div>\n        <div class=\"pg-stage running\"><span class=\"pg-dot\"></span><div><div class=\"pg-stage-name\">Vulnerability Analysis</div></div><span class=\"pg-stage-state\">running</span></div>\n      </div>\n    </div>\n  </div>\n  <p class=\"shot-cap\" data-id=\"Header scan langsung: badge mode, status proses, persentase dan waktu berjalan, serta kontrol Stop untuk admin.\">The live scan header: mode badge, run status, percent and elapsed time, and a Stop control for admins.</p>\n\n  <h2 data-id=\"Apa yang ditampilkan halaman ini\">What the page shows</h2>\n  <ul>\n    <li data-id=\"Sebuah &lt;strong&gt;mode badge&lt;/strong&gt; (Full ASM, Vulnerability Scan, Incident Check, atau Asset Discovery), status proses, persentase keseluruhan, serta waktu berjalan dan perkiraan.\">A <strong>mode badge</strong> (Full ASM, Vulnerability Scan, Incident Check, or Asset Discovery), the run status, overall percent, and elapsed and estimated time.</li>\n    <li data-id=\"Sebuah &lt;strong&gt;workflow overview&lt;/strong&gt; berupa kartu langkah bernomor, dan sebuah &lt;strong&gt;stage chain&lt;/strong&gt; di mana setiap pil menunjukkan running, complete, atau pending.\">A <strong>workflow overview</strong> of numbered step cards, and a <strong>stage chain</strong> where each pill shows running, complete, or pending.</li>\n    <li data-id=\"Sebuah &lt;strong&gt;asset table&lt;/strong&gt; langsung yang terisi saat host ditemukan, dan daftar &lt;strong&gt;live findings&lt;/strong&gt; yang diurutkan berdasarkan severity.\">A live <strong>asset table</strong> that fills in as hosts are found, and a <strong>live findings</strong> list sorted by severity.</li>\n    <li data-id=\"Untuk incident check, umpan &lt;strong&gt;live page checks&lt;/strong&gt; menandai setiap URL kandidat sebagai cocok atau bersih, disertai alasan.\">For incident checks, a <strong>live page checks</strong> feed tags each candidate URL as a match or clean, with a reason.</li>\n    <li data-id=\"Bilah ringkasan di sisi kanan dengan jumlah kandidat, host aktif, screenshot, dan vulnerabilities atau incidents.\">A right-hand summary rail with counts for candidates, live hosts, screenshots, and vulnerabilities or incidents.</li>\n  </ul>\n\n  <h2 data-id=\"Ketika selesai\">When it finishes</h2>\n  <p data-id=\"Callout penyelesaian menampilkan salah satu dari tiga hasil: &lt;strong&gt;Scan fully completed&lt;/strong&gt; berwarna hijau, &lt;strong&gt;Scan was not completed&lt;/strong&gt; berwarna kuning (dibatalkan, dengan hasil sebagian tetap disimpan), atau &lt;strong&gt;Scan failed&lt;/strong&gt; berwarna merah. Pada paket berbayar muncul kartu Security rating per scan. Jika setiap kandidat incident kembali bersih, Anda mendapat panel all-clear yang memastikan tidak ada defacement, injeksi judi, atau SEO spam ditemukan pada halaman terindeks. Tombol &lt;strong&gt;View asset group&lt;/strong&gt; membawa Anda ke hasil lengkap.\">A completion callout shows one of three outcomes: <strong>Scan fully completed</strong> in green, <strong>Scan was not completed</strong> in amber (cancelled, with partial results kept), or <strong>Scan failed</strong> in red. On paid plans a per-scan security rating card appears. If every incident candidate came back clean, you get an all-clear panel confirming no defacement, gambling injection, or SEO spam was found on indexed pages. A <strong>View asset group</strong> button takes you to the full results.</p>\n\n  <div class=\"pager\"><a href=\"#/scans\"><div class=\"dir\" data-id=\"Sebelumnya\">Previous</div><div class=\"ttl\">&larr; Running scans</div></a><a class=\"next\" href=\"#/findings\"><div class=\"dir\" data-id=\"Berikutnya\">Next</div><div class=\"ttl\">Understanding findings &rarr;</div></a></div>"
  },
  "findings": {
    "id": "findings",
    "title": "Understanding findings",
    "eyebrow": "Findings",
    "lede": "Everything CounterAttack surfaces is a finding. The product splits findings into two kinds based on what they are: Vulnerabilities and Incidents. A vulnerability is a weakness that could be exploited. An incident is a live page that has already been compromised.",
    "html": "<span class=\"eyebrow\" data-id=\"Temuan\">Findings</span>\n  <h1 data-id=\"Memahami temuan\">Understanding findings</h1>\n  <p class=\"lede\" data-id=\"Semua yang dimunculkan CounterAttack adalah sebuah temuan. Produk ini membagi temuan menjadi dua jenis berdasarkan sifatnya: Vulnerabilities dan Incidents. Sebuah vulnerability adalah kelemahan yang bisa dieksploitasi. Sebuah incident adalah halaman aktif yang sudah disusupi.\">Everything CounterAttack surfaces is a finding. The product splits findings into two kinds based on what they are: Vulnerabilities and Incidents. A vulnerability is a weakness that could be exploited. An incident is a live page that has already been compromised.</p>\n\n  <h2 data-id=\"Tingkat severity\">Severity levels</h2>\n  <p data-id=\"Setiap temuan memiliki satu severity, ditampilkan sebagai pil huruf kapital. Severity info dihapus dan tidak pernah ditampilkan.\">Each finding carries one severity, shown as an uppercase pill. Info-severity is stripped out and never shown.</p>\n  <div class=\"tag-row\" style=\"gap:10px;margin:16px 0 20px;\">\n    <span class=\"badge sev-critical\"><span class=\"dot\"></span>Critical</span>\n    <span class=\"badge sev-high\"><span class=\"dot\"></span>High</span>\n    <span class=\"badge sev-medium\"><span class=\"dot\"></span>Medium</span>\n    <span class=\"badge sev-low\"><span class=\"dot\"></span>Low</span>\n  </div>\n\n  <h2 data-id=\"Apa yang ditampilkan detail temuan\">What a finding detail shows</h2>\n  <p data-id=\"Membuka sebuah temuan menampilkan severity, judul, host, kategori, pil jenis (vulnerability atau incident), pil status (open, resolved, atau false positive), dan kapan terakhir terlihat. Di bawahnya, setiap blok berikut muncul saat ada isinya: deskripsi, catatan, cuplikan pencarian, panduan remediasi, kutipan respons, referensi, dan kapan pertama kali terlihat. Incidents juga menampilkan screenshot. Sebuah panel &lt;strong&gt;AI Analysis&lt;/strong&gt; berada di bagian bawah.\">Opening a finding shows its severity, title, host, category, a kind pill (vulnerability or incident), a status pill (open, resolved, or false positive), and when it was last seen. Below that, each of these blocks appears when it has content: a description, a note, a search snippet, remediation guidance, a response excerpt, references, and when it was first seen. Incidents also show a screenshot. An <strong>AI Analysis</strong> panel sits at the bottom.</p>\n\n  <div class=\"shot\">\n    <div class=\"shot-bar\"><span class=\"traffic\"><i></i><i></i><i></i></span><span class=\"url\">app.counterattack.com/vulnerabilities/3b9e</span></div>\n    <div class=\"shot-body\">\n      <div style=\"display:flex;align-items:center;gap:10px;margin-bottom:8px;\">\n        <span class=\"badge sev-critical\"><span class=\"dot\"></span>Critical</span>\n        <span class=\"pill\" style=\"color:var(--sev-low);border-color:rgba(59,130,246,0.35);background:rgba(59,130,246,0.1)\">vulnerability</span>\n        <span class=\"pill\">open</span>\n      </div>\n      <div style=\"font-size:17px;font-weight:600;margin-bottom:4px;\">Subdomain takeover on dangling CNAME</div>\n      <div class=\"mono\" style=\"font-size:12.5px;color:var(--fg-muted);margin-bottom:14px;\">legacy.example.com &middot; Exposure</div>\n      <div style=\"display:flex;gap:8px;\">\n        <button class=\"btn btn-ghost\"><i data-lucide=\"check\"></i> Mark resolved</button>\n        <button class=\"btn btn-ghost\"><i data-lucide=\"thumbs-down\"></i> False positive</button>\n      </div>\n    </div>\n  </div>\n  <p class=\"shot-cap\" data-id=\"Detail vulnerability dengan pil statusnya dan aksi admin.\">A vulnerability detail with its status pills and admin actions.</p>\n\n  <h2 data-id=\"Tindakan yang bisa Anda lakukan\">Actions you can take</h2>\n  <p data-id=\"Admin bisa bertindak atas sebuah temuan:\">Admins can act on a finding:</p>\n  <ul>\n    <li data-id=\"&lt;strong&gt;Rescan&lt;/strong&gt; (incident): ambil ulang URL dan jalankan ulang classifier. Jika tidak lagi cocok, incident diselesaikan otomatis.\"><strong>Rescan</strong> (incidents): re-fetch the URL and re-run the classifier. If it no longer matches, the incident auto-resolves.</li>\n    <li data-id=\"&lt;strong&gt;Mark as resolved&lt;/strong&gt;: memindahkannya ke Resolved. Ini akan terbuka kembali jika scan berikutnya mendeteksinya lagi.\"><strong>Mark as resolved</strong>: moves it to Resolved. It will reopen if a future scan detects it again.</li>\n    <li data-id=\"&lt;strong&gt;Mark as false positive&lt;/strong&gt;: memindahkannya ke tampilan tertutup dan tidak akan terbuka kembali saat pindai ulang, meskipun polanya muncul lagi.\"><strong>Mark as false positive</strong>: moves it to the closed view and will not reopen on rescan, even if the pattern recurs.</li>\n    <li data-id=\"&lt;strong&gt;Delete&lt;/strong&gt;: permanen, dan untuk incident juga menghapus screenshot.\"><strong>Delete</strong>: permanent, and for incidents also removes the screenshot.</li>\n  </ul>\n  <p data-id=\"Tampilan daftar juga menyediakan mode &lt;strong&gt;Select&lt;/strong&gt; massal sehingga Anda bisa menyelesaikan atau menandai false positive pada banyak temuan sekaligus.\">The list views also offer bulk <strong>Select</strong> mode so you can resolve or mark false positive on many findings at once.</p>\n\n  <div class=\"pager\"><a href=\"#/results\"><div class=\"dir\" data-id=\"Sebelumnya\">Previous</div><div class=\"ttl\">&larr; Scan results</div></a><a class=\"next\" href=\"#/vulnerabilities\"><div class=\"dir\" data-id=\"Berikutnya\">Next</div><div class=\"ttl\">Vulnerabilities &rarr;</div></a></div>"
  },
  "vulnerabilities": {
    "id": "vulnerabilities",
    "title": "Vulnerabilities",
    "eyebrow": "Findings",
    "lede": "A vulnerability is a detected weakness or exposure: a known CVE, an exposed file or service, a misconfiguration, a weak TLS setup, or a dangling subdomain that could be taken over. These come from the Vulnerability Scan.",
    "html": "<span class=\"eyebrow\" data-id=\"Temuan\">Findings</span>\n  <h1>Vulnerabilities</h1>\n  <p class=\"lede\" data-id=\"Sebuah vulnerability adalah kelemahan atau eksposur yang terdeteksi: CVE yang diketahui, file atau layanan yang terekspos, sebuah misconfiguration, konfigurasi TLS yang lemah, atau subdomain menggantung yang bisa diambil alih. Ini berasal dari Vulnerability Scan.\">A vulnerability is a detected weakness or exposure: a known CVE, an exposed file or service, a misconfiguration, a weak TLS setup, or a dangling subdomain that could be taken over. These come from the Vulnerability Scan.</p>\n\n  <h2 data-id=\"Dua cara menjelajah\">Two ways to browse</h2>\n  <p data-id=\"Sidebar memberi Anda dua tampilan:\">The sidebar gives you two surfaces:</p>\n  <ul>\n    <li data-id=\"&lt;strong&gt;All Findings&lt;/strong&gt; adalah satu tabel lintas grup berisi setiap vulnerability dan incident terbuka. Ini adalah antrean pekerjaan terbuka Anda. Filter berdasarkan severity atau jenis (keduanya, vulnerabilities, atau incidents), dan urutkan berdasarkan severity atau terakhir terlihat.\"><strong>All Findings</strong> is a single cross-group table of every open vulnerability and incident. It is your open work queue. Filter by severity or by kind (both, vulnerabilities, or incidents), and sort by severity or by last seen.</li>\n    <li data-id=\"&lt;strong&gt;Vulnerabilities&lt;/strong&gt; dimulai dengan pemilih grup, lalu menampilkan vulnerabilities satu grup sebagai kartu, masing-masing dengan chip severity, judul, badge &lt;strong&gt;New&lt;/strong&gt; opsional untuk item yang pertama terlihat pada scan terbaru, dan detail yang bisa dibuka.\"><strong>Vulnerabilities</strong> starts with a group picker, then shows one group's vulnerabilities as cards, each with a severity chip, title, an optional <strong>New</strong> badge for items first seen in the latest scan, and expandable detail.</li>\n  </ul>\n\n  <div class=\"shot\">\n    <div class=\"shot-bar\"><span class=\"traffic\"><i></i><i></i><i></i></span><span class=\"url\">app.counterattack.com/issues</span></div>\n    <div class=\"shot-body\">\n      <div class=\"tag-row js-select\" data-filter=\"#tbl-issues\" style=\"margin-bottom:12px;\"><span class=\"pill js-opt is-sel\" data-val=\"all\">All 21</span><span class=\"pill js-opt\" data-val=\"critical\">Critical 3</span><span class=\"pill js-opt\" data-val=\"high\">High 9</span><span class=\"pill js-opt\" data-val=\"medium\">Medium 6</span><span class=\"pill js-opt\" data-val=\"low\">Low 3</span></div>\n      <table class=\"tbl\" id=\"tbl-issues\">\n        <thead><tr><th>Sev</th><th>Title</th><th>Host</th><th>Category</th><th>Last seen</th></tr></thead>\n        <tbody>\n          <tr class=\"clickable\" data-sev=\"critical\"><td><span class=\"badge sev-critical\"><span class=\"dot\"></span>Crit</span></td><td>Subdomain takeover</td><td class=\"mono\">legacy.example.com</td><td>Exposure</td><td>2h ago</td></tr>\n          <tr class=\"clickable\" data-sev=\"high\"><td><span class=\"badge sev-high\"><span class=\"dot\"></span>High</span></td><td>Apache RCE (CVE-2021-41773)</td><td class=\"mono\">legacy.example.com</td><td>CVE</td><td>2h ago</td></tr>\n          <tr class=\"clickable\" data-sev=\"high\"><td><span class=\"badge sev-high\"><span class=\"dot\"></span>High</span></td><td>Exposed .git directory</td><td class=\"mono\">staging.example.com</td><td>Exposure</td><td>2h ago</td></tr>\n          <tr class=\"clickable\" data-sev=\"medium\"><td><span class=\"badge sev-medium\"><span class=\"dot\"></span>Med</span></td><td>Weak TLS ciphers accepted</td><td class=\"mono\">mail.example.com</td><td>SSL/TLS</td><td>2h ago</td></tr>\n          <tr class=\"clickable\" data-sev=\"low\"><td><span class=\"badge sev-low\"><span class=\"dot\"></span>Low</span></td><td>Server version disclosed in banner</td><td class=\"mono\">api.example.com</td><td>Misconfig</td><td>2h ago</td></tr>\n        </tbody>\n      </table>\n      <div style=\"font-size:11.5px;color:var(--fg-subtle);margin-top:10px;\">Pick a severity above to filter the table.</div>\n    </div>\n  </div>\n  <p class=\"shot-cap\" data-id=\"Antrean All Findings, difilter berdasarkan severity dan jenis.\">The All Findings queue, filtered by severity and kind.</p>\n\n  <h2 data-id=\"Kategori\">Categories</h2>\n  <p data-id=\"Vulnerabilities dikelompokkan berdasarkan kategori, termasuk CVE, Exposure, Misconfig, Weak Creds, SSL/TLS, dan DNS. Dashboard dan halaman grup membuat grafik jumlah terbuka Anda berdasarkan kategori sehingga Anda bisa melihat di mana eksposur Anda terkonsentrasi.\">Vulnerabilities are grouped by category, including CVE, Exposure, Misconfig, Weak Creds, SSL/TLS, and DNS. The Dashboard and group pages chart your open counts by category so you can see where your exposure concentrates.</p>\n\n  <div class=\"pager\"><a href=\"#/findings\"><div class=\"dir\" data-id=\"Sebelumnya\">Previous</div><div class=\"ttl\">&larr; Understanding findings</div></a><a class=\"next\" href=\"#/incidents\"><div class=\"dir\" data-id=\"Berikutnya\">Next</div><div class=\"ttl\">Incidents &rarr;</div></a></div>"
  },
  "incidents": {
    "id": "incidents",
    "title": "Incidents",
    "eyebrow": "Findings",
    "lede": "An incident is a live page that has already been compromised. The Incident Check sweeps public search results for three kinds of signature and then verifies each hit on the real page. Because an incident is a confirmed compromise, it weighs more heavily on your grade than a vulnerability of the same severity.",
    "html": "<span class=\"eyebrow\" data-id=\"Temuan\">Findings</span>\n  <h1>Incidents</h1>\n  <p class=\"lede\" data-id=\"Sebuah incident adalah halaman aktif yang sudah disusupi. Incident Check menyisir hasil pencarian publik untuk tiga jenis signature lalu memverifikasi setiap kecocokan pada halaman aslinya. Karena sebuah incident adalah kompromi yang terkonfirmasi, bobotnya lebih berat pada nilai Anda dibanding vulnerability dengan severity yang sama.\">An incident is a live page that has already been compromised. The Incident Check sweeps public search results for three kinds of signature and then verifies each hit on the real page. Because an incident is a confirmed compromise, it weighs more heavily on your grade than a vulnerability of the same severity.</p>\n\n  <h2 data-id=\"Apa yang dicari Incident Check\">What the Incident Check looks for</h2>\n  <ul>\n    <li data-id=\"&lt;strong&gt;Defacement&lt;/strong&gt;: halaman hacked-by, penanda &quot;pwned&quot; dan &quot;greetz&quot;, dan konten yang diganti.\"><strong>Defacement</strong>: hacked-by pages, \"pwned\" and \"greetz\" markers, and replaced content.</li>\n    <li data-id=\"&lt;strong&gt;Gambling injection&lt;/strong&gt;: kata kunci yang disuntikkan seperti &quot;slot gacor&quot;, &quot;maxwin&quot;, &quot;judi online&quot;, dan &quot;togel&quot;.\"><strong>Gambling injection</strong>: injected keywords like \"slot gacor\", \"maxwin\", \"judi online\", and \"togel\".</li>\n    <li data-id=\"&lt;strong&gt;SEO spam&lt;/strong&gt;: backlink tersembunyi, halaman doorway, dan peretasan kata kunci, termasuk tautan yang disembunyikan di luar layar atau dengan visibility dimatikan.\"><strong>SEO spam</strong>: hidden backlinks, doorway pages, and keyword hacks, including links hidden off-screen or with visibility turned off.</li>\n  </ul>\n\n  <div class=\"shot\">\n    <div class=\"shot-bar\"><span class=\"traffic\"><i></i><i></i><i></i></span><span class=\"url\">app.counterattack.com/incidents</span></div>\n    <div class=\"shot-body\">\n      <div style=\"display:grid;grid-template-columns:repeat(3,1fr);gap:12px;\">\n        <div class=\"rl-card\"><div class=\"rl-card-body\" style=\"padding:12px;\">\n          <div style=\"height:104px;border-radius:8px;overflow:hidden;background:#050505;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:8px;margin-bottom:10px;\">\n            <div style=\"font-family:'JetBrains Mono',monospace;font-weight:700;font-size:14px;color:#ff2e44;letter-spacing:1.5px;text-shadow:0 0 8px rgba(255,46,68,0.75);\">HACKED BY</div>\n            <div style=\"font-family:'JetBrains Mono',monospace;font-size:11px;color:#22e3a7;margin-top:3px;text-shadow:0 0 6px rgba(34,227,167,0.6);\">x-Ghost-Team</div>\n            <div style=\"font-family:'JetBrains Mono',monospace;font-size:8px;color:#666;margin-top:4px;\">your security is our art</div>\n          </div>\n          <span class=\"badge sev-critical\"><span class=\"dot\"></span>Critical</span>\n          <div style=\"font-size:13.5px;margin-top:8px;\">Defacement detected</div>\n          <div class=\"mono\" style=\"font-size:11.5px;color:var(--fg-subtle);\">www.example.com &middot; Defacement</div>\n        </div></div>\n        <div class=\"rl-card\"><div class=\"rl-card-body\" style=\"padding:12px;\">\n          <div style=\"height:104px;border-radius:8px;overflow:hidden;background:radial-gradient(circle at 50% 30%, #1a1030, #0b0b14);display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:8px;margin-bottom:10px;\">\n            <div style=\"font-family:'JetBrains Mono',monospace;font-weight:700;font-size:16px;color:#FFD200;text-shadow:0 0 10px rgba(255,210,0,0.85);letter-spacing:1px;\">SLOT GACOR</div>\n            <div style=\"font-weight:700;font-size:12px;color:#22e3a7;text-shadow:0 0 8px rgba(34,227,167,0.7);margin-top:2px;\">MAXWIN x500</div>\n            <div style=\"font-size:9px;color:#ff5470;margin-top:4px;letter-spacing:0.5px;\">DAFTAR JUDI ONLINE - BONUS 100%</div>\n          </div>\n          <span class=\"badge sev-critical\"><span class=\"dot\"></span>Critical</span>\n          <div style=\"font-size:13.5px;margin-top:8px;\">Gambling injection detected</div>\n          <div class=\"mono\" style=\"font-size:11.5px;color:var(--fg-subtle);\">staging.example.com &middot; Gambling</div>\n        </div></div>\n        <div class=\"rl-card\"><div class=\"rl-card-body\" style=\"padding:12px;\">\n          <div style=\"height:104px;border-radius:8px;overflow:hidden;background:#f4f4f5;padding:10px;margin-bottom:10px;\">\n            <div style=\"height:7px;width:55%;background:#b8b8bd;border-radius:3px;margin-bottom:7px;\"></div>\n            <div style=\"height:5px;width:88%;background:#dcdce0;border-radius:3px;margin-bottom:4px;\"></div>\n            <div style=\"height:5px;width:78%;background:#dcdce0;border-radius:3px;margin-bottom:9px;\"></div>\n            <div style=\"font-size:7px;line-height:1.5;color:#3b6fe0;opacity:0.55;\">cheap-loans-online &middot; buy-followers &middot; casino-bonus-2026 &middot; replica-watches &middot; payday-advance &middot; discount-pharma &middot; seo-backlinks-cheap</div>\n          </div>\n          <span class=\"badge sev-high\"><span class=\"dot\"></span>High</span>\n          <div style=\"font-size:13.5px;margin-top:8px;\">Hidden SEO spam backlinks</div>\n          <div class=\"mono\" style=\"font-size:11.5px;color:var(--fg-subtle);\">legacy.example.com &middot; SEO Spam</div>\n        </div></div>\n      </div>\n      <div style=\"font-size:11.5px;color:var(--fg-subtle);margin-top:12px;text-align:center;\">Illustrative captures of the three incident types. Real customer URLs stay private.</div>\n    </div>\n  </div>\n  <p class=\"shot-cap\" data-id=\"Incidents ditampilkan sebagai petak dengan screenshot, severity, dan host yang cocok.\">Incidents render as tiles with a screenshot, severity, and matched host.</p>\n\n  <h2 data-id=\"Menjelajahi incidents\">Browsing incidents</h2>\n  <p data-id=\"Seperti vulnerabilities, incidents dibuka dari pemilih grup, lalu menampilkan incidents satu grup sebagai petak dengan thumbnail screenshot, URL yang cocok, dan waktu &quot;first seen&quot;. Setiap incident memiliki halaman detailnya sendiri dengan URL yang terdampak, sebuah screenshot, dan cuplikan pencarian yang cocok. Admin bisa memindai ulang sebuah incident untuk memastikannya kembali, atau menyelesaikannya.\">Like vulnerabilities, incidents open from a group picker, then show one group's incidents as tiles with a screenshot thumbnail, the matched URL, and a \"first seen\" time. Each incident has its own detail page with the affected URL, a screenshot, and the search snippet that matched. Admins can rescan an incident to reconfirm it, or resolve it.</p>\n\n  <div class=\"callout note\"><i data-lucide=\"search\"></i><div><span class=\"callout-title\" data-id=\"Cara memvalidasi\">How to validate</span><p data-id=\"Beberapa tautan SEO yang disuntikkan tersembunyi di dalam source halaman alih-alih terlihat di layar. Untuk memastikannya, buka source halaman dan cari kata kunci cocok yang ditampilkan pada cuplikan pencarian incident.\">Some injected SEO links are hidden in the page source rather than visible on screen. To confirm one, open the page source and look for the matched keyword shown in the incident's search snippet.</p></div></div>\n\n  <div class=\"pager\"><a href=\"#/vulnerabilities\"><div class=\"dir\" data-id=\"Sebelumnya\">Previous</div><div class=\"ttl\">&larr; Vulnerabilities</div></a><a class=\"next\" href=\"#/resolved\"><div class=\"dir\" data-id=\"Berikutnya\">Next</div><div class=\"ttl\">Resolved &amp; false positives &rarr;</div></a></div>"
  },
  "resolved": {
    "id": "resolved",
    "title": "Resolved &amp; false positives",
    "eyebrow": "Findings",
    "lede": "Once you have dealt with a finding, it moves out of the open queue into the Resolved view. CounterAttack keeps two closed states, and they behave differently on the next scan.",
    "html": "<span class=\"eyebrow\" data-id=\"Temuan\">Findings</span>\n  <h1>Resolved &amp; false positives</h1>\n  <p class=\"lede\" data-id=\"Setelah Anda menangani sebuah temuan, temuan itu keluar dari antrean terbuka menuju tampilan Resolved. CounterAttack menyimpan dua status tertutup, dan keduanya berperilaku berbeda pada scan berikutnya.\">Once you have dealt with a finding, it moves out of the open queue into the Resolved view. CounterAttack keeps two closed states, and they behave differently on the next scan.</p>\n\n  <h2>Resolved vs false positive</h2>\n  <div class=\"two-col\" style=\"margin:16px 0 8px;\">\n    <div class=\"rl-card\"><div class=\"rl-card-body\">\n      <span class=\"pill ok\">Resolved</span>\n      <p style=\"margin:10px 0 0;font-size:13.5px;color:var(--fg-muted)\" data-id=\"Anda memperbaiki masalahnya. Temuan keluar dari antrean tetapi &lt;strong&gt;akan terbuka kembali&lt;/strong&gt; jika scan berikutnya mendeteksinya lagi, sehingga Anda selalu tahu jika sebuah perbaikan mengalami regresi.\">You fixed the issue. It moves out of the queue but <strong>will reopen</strong> if a future scan detects it again, so you always know if a fix regressed.</p>\n    </div></div>\n    <div class=\"rl-card\"><div class=\"rl-card-body\">\n      <span class=\"pill warn\">False positive</span>\n      <p style=\"margin:10px 0 0;font-size:13.5px;color:var(--fg-muted)\" data-id=\"Deteksinya salah atau masalahnya sudah diketahui dan diterima. Ini &lt;strong&gt;tidak akan terbuka kembali&lt;/strong&gt; saat pindai ulang, meskipun pola yang sama muncul lagi.\">The detection was wrong or the issue is known and accepted. It <strong>will not reopen</strong> on rescan, even if the same pattern recurs.</p>\n    </div></div>\n  </div>\n\n  <h2 data-id=\"Tampilan Resolved\">The Resolved view</h2>\n  <p data-id=\"Halaman Resolved memiliki dua tab. &lt;strong&gt;By group&lt;/strong&gt; menampilkan pemilih grup, lalu temuan tertutup grup itu dengan sub-tab All, Resolved, dan False positive. &lt;strong&gt;False positives&lt;/strong&gt; adalah tabel datar lintas grup berisi setiap item yang telah Anda abaikan. Pada keduanya, admin bisa &lt;strong&gt;Restore to open&lt;/strong&gt; (yang kembali dihitung untuk nilai Anda) atau &lt;strong&gt;Delete permanently&lt;/strong&gt;.\">The Resolved page has two tabs. <strong>By group</strong> shows a group picker, then that group's closed findings with sub-tabs for All, Resolved, and False positive. <strong>False positives</strong> is a flat cross-group table of every item you have dismissed. In both, admins can <strong>Restore to open</strong> (which counts toward your grade again) or <strong>Delete permanently</strong>.</p>\n  <div class=\"shot\">\n    <div class=\"shot-bar\"><span class=\"traffic\"><i></i><i></i><i></i></span><span class=\"url\">app.counterattack.com/resolved</span></div>\n    <div class=\"shot-body\">\n      <div class=\"tag-row js-select\" data-filter=\"#tbl-resolved\" data-key=\"status\" style=\"margin-bottom:12px;\"><span class=\"pill js-opt is-sel\" data-val=\"all\">All</span><span class=\"pill js-opt\" data-val=\"resolved\">Resolved</span><span class=\"pill js-opt\" data-val=\"false-positive\">False positive</span></div>\n      <table class=\"tbl\" id=\"tbl-resolved\">\n        <thead><tr><th>Sev</th><th>Title</th><th>Host</th><th>Status</th></tr></thead>\n        <tbody>\n          <tr data-status=\"resolved\"><td><span class=\"badge sev-high\"><span class=\"dot\"></span>High</span></td><td>Exposed .git directory</td><td class=\"mono\">staging.example.com</td><td><span class=\"pill ok\">Resolved</span></td></tr>\n          <tr data-status=\"resolved\"><td><span class=\"badge sev-medium\"><span class=\"dot\"></span>Med</span></td><td>Weak TLS ciphers accepted</td><td class=\"mono\">mail.example.com</td><td><span class=\"pill ok\">Resolved</span></td></tr>\n          <tr data-status=\"false-positive\"><td><span class=\"badge sev-low\"><span class=\"dot\"></span>Low</span></td><td>Server banner disclosed</td><td class=\"mono\">api.example.com</td><td><span class=\"pill warn\">False positive</span></td></tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n\n  <div class=\"callout tip\"><i data-lucide=\"wand-2\"></i><div><p data-id=\"Tidak yakin temuan mana yang hanya gangguan? Panel &lt;a href=&quot;#/ai&quot;&gt;AI Triage&lt;/a&gt; pada sebuah grup bisa menandai kemungkinan false positive dengan tingkat keyakinan dan alasan, sehingga Anda bisa membersihkannya lebih cepat.\">Not sure which findings are noise? The <a href=\"#/ai\">AI Triage</a> panel on a group can flag likely false positives with a confidence level and a reason, so you can clear them faster.</p></div></div>\n\n  <div class=\"pager\"><a href=\"#/incidents\"><div class=\"dir\" data-id=\"Sebelumnya\">Previous</div><div class=\"ttl\">&larr; Incidents</div></a><a class=\"next\" href=\"#/reports\"><div class=\"dir\" data-id=\"Berikutnya\">Next</div><div class=\"ttl\">Reports &rarr;</div></a></div>"
  },
  "reports": {
    "id": "reports",
    "title": "Reports",
    "eyebrow": "Findings",
    "lede": "CounterAttack turns any view into a shareable report. Reports are built in your browser and saved to a history so you can download the exact same report again later. Reports are a paid feature.",
    "html": "<span class=\"eyebrow\" data-id=\"Temuan\">Findings</span>\n  <h1>Reports</h1>\n  <p class=\"lede\" data-id=\"CounterAttack mengubah tampilan apa pun menjadi laporan yang bisa dibagikan. Reports dibuat di browser Anda dan disimpan ke riwayat sehingga Anda bisa mengunduh laporan yang persis sama lagi nanti. Reports adalah fitur berbayar.\">CounterAttack turns any view into a shareable report. Reports are built in your browser and saved to a history so you can download the exact same report again later. Reports are a paid feature.</p>\n\n  <h2 data-id=\"Membuat sebuah laporan\">Generating a report</h2>\n  <p data-id=\"Klik &lt;strong&gt;Generate report&lt;/strong&gt; pada Dashboard, sebuah asset group, atau tampilan temuan. Anda mendapat hingga tiga format:\">Click <strong>Generate report</strong> on the Dashboard, an asset group, or a findings view. You get up to three formats:</p>\n  <ul>\n    <li data-id=\"&lt;strong&gt;Color PDF&lt;/strong&gt;: laporan berwarna penuh, paling cocok untuk layar.\"><strong>Color PDF</strong>: a full-color report, best for screen.</li>\n    <li data-id=\"&lt;strong&gt;Print-friendly PDF&lt;/strong&gt;: versi berlatar putih yang menghemat tinta warna.\"><strong>Print-friendly PDF</strong>: a white-background version that saves color ink.</li>\n    <li data-id=\"&lt;strong&gt;CSV&lt;/strong&gt;: satu baris per item, untuk mengurutkan dan memfilter di spreadsheet. Tersedia di tempat yang cocok untuk tabel datar.\"><strong>CSV</strong>: one row per item, for sorting and filtering in a spreadsheet. Offered where a flat table makes sense.</li>\n  </ul>\n  <p data-id=\"Reports bisa dicakup ke seluruh organisasi Anda, satu asset group, vulnerabilities Anda, incidents Anda, atau satu scan. PDF yang siap audit dirancang untuk berfungsi sebagai bukti ISO 27001.\">Reports can be scoped to your whole organization, one asset group, your vulnerabilities, your incidents, or a single scan. The audit-ready PDF is designed to work as ISO 27001 evidence.</p>\n  <div class=\"shot\">\n    <div class=\"shot-bar\"><span class=\"traffic\"><i></i><i></i><i></i></span><span class=\"url\">app.counterattack.com/dashboard</span></div>\n    <div class=\"shot-body\">\n      <div class=\"rl-card\" style=\"max-width:280px;margin:0 auto;\"><div class=\"rl-card-body js-select\" style=\"padding:8px;\">\n        <div class=\"pick js-opt is-sel\" style=\"display:flex;align-items:center;gap:8px;padding:9px 10px;border-radius:8px;font-size:13px;\"><i data-lucide=\"file-text\" style=\"width:15px;height:15px;color:var(--accent)\"></i> Color PDF</div>\n        <div class=\"pick js-opt\" style=\"display:flex;align-items:center;gap:8px;padding:9px 10px;border-radius:8px;font-size:13px;color:var(--fg-muted)\"><i data-lucide=\"printer\" style=\"width:15px;height:15px;\"></i> Print-friendly PDF</div>\n        <div class=\"pick js-opt\" style=\"display:flex;align-items:center;gap:8px;padding:9px 10px;border-radius:8px;font-size:13px;color:var(--fg-muted)\"><i data-lucide=\"table\" style=\"width:15px;height:15px;\"></i> CSV</div>\n      </div></div>\n    </div>\n  </div>\n\n  <h2>Report History</h2>\n  <p data-id=\"Halaman &lt;strong&gt;Report History&lt;/strong&gt; menampilkan setiap laporan yang telah Anda buat, terbaru lebih dulu, dengan cakupan, jenis, jumlah item, tanggal, badge format, dan tombol &lt;strong&gt;Download&lt;/strong&gt; yang membangunnya kembali secara persis. Anda bisa memfilter berdasarkan asset group, vulnerabilities, atau incidents.\">The <strong>Report History</strong> page lists every report you have generated, newest first, with its scope, kind, item count, date, format badge, and a <strong>Download</strong> button that rebuilds it exactly. You can filter by asset group, vulnerabilities, or incidents.</p>\n  <div class=\"shot\">\n    <div class=\"shot-bar\"><span class=\"traffic\"><i></i><i></i><i></i></span><span class=\"url\">app.counterattack.com/reports</span></div>\n    <div class=\"shot-body\">\n      <table class=\"tbl\">\n        <thead><tr><th>Scope</th><th>Kind</th><th>Items</th><th>Date</th><th>Format</th><th></th></tr></thead>\n        <tbody>\n          <tr><td class=\"mono\">example.com</td><td>Asset group</td><td>40</td><td>2h ago</td><td><span class=\"pill\">PDF</span></td><td><button class=\"btn btn-ghost\" style=\"padding:5px 9px;\"><i data-lucide=\"download\" style=\"width:14px;height:14px;\"></i></button></td></tr>\n          <tr><td>Organization</td><td>Vulnerabilities</td><td>17</td><td>1d ago</td><td><span class=\"pill\">CSV</span></td><td><button class=\"btn btn-ghost\" style=\"padding:5px 9px;\"><i data-lucide=\"download\" style=\"width:14px;height:14px;\"></i></button></td></tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n\n  <div class=\"callout pro\"><i data-lucide=\"rocket\"></i><div><span class=\"callout-title\" data-id=\"Fitur berbayar\">Paid feature</span><p data-id=\"Laporan PDF dan CSV tersedia pada Starter ke atas. Pada Free, tombol Reports terkunci dan mengarah ke halaman upgrade.\">PDF and CSV reports are available on Starter and above. On Free, the Reports button is locked and links to the upgrade page.</p></div></div>\n\n  <div class=\"pager\"><a href=\"#/resolved\"><div class=\"dir\" data-id=\"Sebelumnya\">Previous</div><div class=\"ttl\">&larr; Resolved</div></a><a class=\"next\" href=\"#/activity\"><div class=\"dir\" data-id=\"Berikutnya\">Next</div><div class=\"ttl\">Activity &rarr;</div></a></div>"
  },
  "activity": {
    "id": "activity",
    "title": "Activity",
    "eyebrow": "Findings",
    "lede": "The Activity feed is the running log of every scan: what is queued, what is live right now, and what has finished. Live rows update every couple of seconds.",
    "html": "<span class=\"eyebrow\" data-id=\"Temuan\">Findings</span>\n  <h1>Activity</h1>\n  <p class=\"lede\" data-id=\"Umpan Activity adalah log berjalan dari setiap scan: apa yang mengantre, apa yang sedang berjalan sekarang, dan apa yang sudah selesai. Baris langsung diperbarui setiap beberapa detik.\">The Activity feed is the running log of every scan: what is queued, what is live right now, and what has finished. Live rows update every couple of seconds.</p>\n\n  <div class=\"shot\">\n    <div class=\"shot-bar\"><span class=\"traffic\"><i></i><i></i><i></i></span><span class=\"url\">app.counterattack.com/activity</span></div>\n    <div class=\"shot-body\">\n      <div class=\"tag-row js-select\" data-filter=\"#act-rows\" data-key=\"status\" style=\"margin-bottom:12px;\"><span class=\"pill js-opt is-sel\" data-val=\"all\">All 19</span><span class=\"pill js-opt\" data-val=\"live\">Live 1</span><span class=\"pill js-opt\" data-val=\"completed\">Completed 18</span><span class=\"pill js-opt\" data-val=\"failed\">Failed 0</span></div>\n      <div id=\"act-rows\" style=\"display:flex;flex-direction:column;gap:8px;max-height:360px;overflow-y:auto;\"></div>\n    </div>\n  </div>\n  <p class=\"shot-cap\" data-id=\"Pil filter, lalu satu baris per scan dengan bar progres langsung.\">Filter pills, then one row per scan with a live progress bar.</p>\n\n  <h2 data-id=\"Apa yang ditampilkan setiap baris\">What each row shows</h2>\n  <p data-id=\"Badge status (Running, Queued, Fully completed, Warnings, Failed, atau Stopped early), ikon mode, target, badge opsional untuk pindai ulang satu aset atau pindai ulang otomatis, jenis scan, grup, waktu mulai dan selesai, bar progres langsung, dan statistik per sisi untuk aset aktif, vulnerabilities, dan incidents. Admin bisa &lt;strong&gt;Stop&lt;/strong&gt; scan yang berjalan, &lt;strong&gt;Delete&lt;/strong&gt; catatan yang selesai, atau &lt;strong&gt;View&lt;/strong&gt; detail scan.\">A status badge (Running, Queued, Fully completed, Warnings, Failed, or Stopped early), a mode icon, the target, optional badges for a single-asset rescan or an auto rescan, the scan type, the group, start and finish times, a live progress bar, and per-side stats for live assets, vulnerabilities, and incidents. Admins can <strong>Stop</strong> a live scan, <strong>Delete</strong> a finished record, or <strong>View</strong> the scan detail.</p>\n\n  <div class=\"callout note\"><i data-lucide=\"git-merge\"></i><div><p data-id=\"Sebuah Full Scan sebenarnya adalah dua scan yang bekerja bersama (proses vulnerability dan incident check). Activity menggabungkannya menjadi satu baris &quot;Full Scan&quot; yang menampilkan kedua bagian dan kedua jumlahnya. Menghentikan atau menghapus baris itu berlaku untuk keduanya.\">A Full Scan is really two scans working together (the vulnerability run and the incident check). Activity folds them into one \"Full Scan\" row that shows both halves and both counts. Stopping or deleting that row acts on both.</p></div></div>\n\n  <div class=\"pager\"><a href=\"#/reports\"><div class=\"dir\" data-id=\"Sebelumnya\">Previous</div><div class=\"ttl\">&larr; Reports</div></a><a class=\"next\" href=\"#/rating\"><div class=\"dir\" data-id=\"Berikutnya\">Next</div><div class=\"ttl\">Security rating &rarr;</div></a></div>"
  },
  "rating": {
    "id": "rating",
    "title": "Security rating",
    "eyebrow": "Intelligence",
    "lede": "CounterAttack grades each asset group from A to F, in two separate categories: a Vulnerability Rating and an Incident Rating. The grade is deliberately driven by your single most serious open issue, not an average, so it reflects real risk rather than being diluted by clean assets.",
    "html": "<span class=\"eyebrow\" data-id=\"Intelijen\">Intelligence</span>\n  <h1>Security rating</h1>\n  <p class=\"lede\" data-id=\"CounterAttack menilai setiap asset group dari A sampai F, dalam dua kategori terpisah: Vulnerability Rating dan Incident Rating. Nilai ini sengaja ditentukan oleh satu masalah terbuka paling serius Anda, bukan rata-rata, sehingga mencerminkan risiko nyata alih-alih diencerkan oleh aset yang bersih.\">CounterAttack grades each asset group from A to F, in two separate categories: a Vulnerability Rating and an Incident Rating. The grade is deliberately driven by your single most serious open issue, not an average, so it reflects real risk rather than being diluted by clean assets.</p>\n\n  <div class=\"shot\">\n    <div class=\"shot-body\" style=\"display:flex;gap:24px;justify-content:center;align-items:center;padding:28px;\">\n      <div style=\"text-align:center;\"><div class=\"grade\" style=\"color:var(--sev-high);margin:0 auto 8px;\">D</div><div style=\"font-size:12px;color:var(--fg-muted);\">Vulnerability Rating</div><div style=\"font-size:11px;color:var(--fg-subtle);\">64% &middot; Needs work</div></div>\n      <div style=\"text-align:center;\"><div class=\"grade\" style=\"color:var(--sev-critical);margin:0 auto 8px;\">F</div><div style=\"font-size:12px;color:var(--fg-muted);\">Incident Rating</div><div style=\"font-size:11px;color:var(--fg-subtle);\">41% &middot; Failing</div></div>\n    </div>\n  </div>\n  <p class=\"shot-cap\" data-id=\"Dua kartu nilai, berdampingan, satu per kategori.\">Two grade cards, side by side, one per category.</p>\n\n  <h2 data-id=\"Rentang nilai\">The grade bands</h2>\n  <table class=\"tbl\" style=\"margin:8px 0 20px;\">\n    <thead><tr><th>Grade</th><th>Score</th><th>Meaning</th></tr></thead>\n    <tbody>\n      <tr><td><span class=\"badge sev-low\" style=\"color:var(--status-success);border-color:rgba(16,185,129,0.35);background:rgba(16,185,129,0.1)\">A</span></td><td>90% and up</td><td>Clean</td></tr>\n      <tr><td><span class=\"badge sev-low\">B</span></td><td>80 to 89%</td><td>Good</td></tr>\n      <tr><td><span class=\"badge sev-medium\">C</span></td><td>70 to 79%</td><td>Acceptable</td></tr>\n      <tr><td><span class=\"badge sev-high\">D</span></td><td>60 to 69%</td><td>Needs work</td></tr>\n      <tr><td><span class=\"badge sev-critical\">F</span></td><td>Below 60%</td><td>Failing</td></tr>\n    </tbody>\n  </table>\n\n  <h2 data-id=\"Cara kerja nilai\">How the grade works</h2>\n  <p data-id=\"Satu masalah terbuka terburuk Anda menentukan nilai terbaik yang bisa Anda capai. Satu critical terbuka membatasi Anda di F, satu high di C, satu medium di B, dan satu low masih memungkinkan A. Sebuah incident berdampak lebih keras dibanding vulnerability dengan severity yang sama. Menambah lebih banyak masalah pada level yang sama menekan skor lebih rendah, dengan beberapa yang pertama paling berpengaruh. Membereskan masalah terburuk Anda langsung menaikkan nilai, dan menambah subdomain yang bersih tidak pernah menaikkan nilai yang buruk.\">Your worst single open issue sets the best grade you can reach. One open critical caps you at F, one high at C, one medium at B, and one low still allows an A. An incident hits harder than a vulnerability of the same severity. Adding more issues of the same level pushes the score lower, with the first few counting the most. Clearing your worst issue lifts the grade immediately, and adding clean subdomains never lifts a bad grade.</p>\n\n  <div class=\"callout pro\"><i data-lucide=\"rocket\"></i><div><span class=\"callout-title\" data-id=\"Fitur berbayar\">Paid feature</span><p data-id=\"Free menjalankan scan yang sama, tetapi rating A sampai F, skor per domain, dan laporan yang dapat diunduh tersedia pada Starter ke atas.\">Free runs the same scans, but the A to F rating, the per-domain scores, and downloadable reports come with Starter and above.</p></div></div>\n\n  <div class=\"pager\"><a href=\"#/activity\"><div class=\"dir\" data-id=\"Sebelumnya\">Previous</div><div class=\"ttl\">&larr; Activity</div></a><a class=\"next\" href=\"#/ai\"><div class=\"dir\" data-id=\"Berikutnya\">Next</div><div class=\"ttl\">AI insights &rarr;</div></a></div>"
  },
  "ai": {
    "id": "ai",
    "title": "AI insights",
    "eyebrow": "Intelligence",
    "lede": "CounterAttack can put a language model to work on your findings. All three AI features are on demand, meaning nothing is generated until you click, and none of them ever change your actual findings. Results are cached and always carry a reminder to verify before acting.",
    "html": "<span class=\"eyebrow\" data-id=\"Intelijen\">Intelligence</span>\n  <h1>AI insights</h1>\n  <p class=\"lede\" data-id=\"CounterAttack bisa menugaskan sebuah language model untuk menangani temuan Anda. Ketiga fitur AI bersifat on demand, artinya tidak ada yang dihasilkan sampai Anda mengklik, dan tak satu pun dari mereka mengubah temuan Anda yang sebenarnya. Hasilnya di-cache dan selalu menyertakan pengingat untuk memverifikasi sebelum bertindak.\">CounterAttack can put a language model to work on your findings. All three AI features are on demand, meaning nothing is generated until you click, and none of them ever change your actual findings. Results are cached and always carry a reminder to verify before acting.</p>\n\n  <h2 data-id=\"Tiga fitur AI\">Three AI features</h2>\n  <ul>\n    <li data-id=\"&lt;strong&gt;Explain this finding&lt;/strong&gt;: pada detail temuan mana pun, menghasilkan &lt;strong&gt;AI Analysis&lt;/strong&gt; berbahasa sederhana tentang apa masalahnya dan mengapa itu penting.\"><strong>Explain this finding</strong>: on any finding detail, produces a plain-language <strong>AI Analysis</strong> of what the issue is and why it matters.</li>\n    <li data-id=\"&lt;strong&gt;Summarize this group&lt;/strong&gt;: pada sebuah asset group, menghasilkan &lt;strong&gt;AI Summary&lt;/strong&gt;, ikhtisar eksekutif dari temuan terbuka grup tersebut.\"><strong>Summarize this group</strong>: on an asset group, produces an <strong>AI Summary</strong>, an executive overview of the group's open findings.</li>\n    <li data-id=\"&lt;strong&gt;Triage findings&lt;/strong&gt;: pada sebuah asset group, menghasilkan &lt;strong&gt;AI Triage&lt;/strong&gt; yang melabeli setiap temuan terbuka sebagai &quot;Looks real&quot; atau &quot;Likely false positive&quot;, dengan tingkat keyakinan, alasan, dan saran severity bila berbeda. Kemungkinan false positive diurutkan ke atas.\"><strong>Triage findings</strong>: on an asset group, produces an <strong>AI Triage</strong> that labels each open finding as \"Looks real\" or \"Likely false positive\", with a confidence level, a reason, and a suggested severity when it differs. Likely false positives are sorted to the top.</li>\n  </ul>\n\n  <div class=\"shot\">\n    <div class=\"shot-body\">\n      <div class=\"rl-card\"><div class=\"rl-card-header\"><span class=\"rl-card-title\"><i data-lucide=\"bot\" style=\"width:15px;height:15px;vertical-align:-2px;color:var(--accent)\"></i> AI Triage</span></div><div class=\"rl-card-body\">\n        <div style=\"display:flex;align-items:center;gap:10px;margin-bottom:10px;\"><span class=\"pill warn\">Likely false positive</span><span class=\"subtle\" style=\"font-size:12px;\">confidence: medium</span></div>\n        <div style=\"font-size:13.5px;margin-bottom:4px;\">Server version disclosed in banner</div>\n        <div class=\"subtle\" style=\"font-size:12.5px;\">This is informational and low impact on a host already behind a CDN. Suggested severity: <span class=\"mono\">low &rarr; info</span></div>\n        <div style=\"margin-top:12px;font-size:11.5px;font-style:italic;color:var(--fg-subtle);\">AI-generated, advisory only. Nothing was changed.</div>\n      </div></div>\n    </div>\n  </div>\n  <p class=\"shot-cap\" data-id=\"AI Triage menyarankan temuan mana yang kemungkinan hanya gangguan, tanpa mengubahnya.\">AI Triage suggests which findings are likely noise, without touching them.</p>\n\n  <div class=\"callout note\"><i data-lucide=\"info\"></i><div><p data-id=\"AI insights hanya muncul ketika sebuah penyedia model sudah dikonfigurasi untuk workspace, seperti dijelaskan di &lt;a href=&quot;#/ai-settings&quot;&gt;Konfigurasi AI&lt;/a&gt;. Jika penyedia sudah disiapkan tetapi paket Anda tidak bisa menggunakannya, yang muncul adalah ajakan upgrade. AI insights adalah fitur berbayar.\">AI insights appear only when a model provider has been configured for the workspace, as described in <a href=\"#/ai-settings\">AI configuration</a>. If a provider is set up but your plan cannot use it, an upgrade prompt shows instead. AI insights are a paid feature.</p></div></div>\n\n  <div class=\"pager\"><a href=\"#/rating\"><div class=\"dir\" data-id=\"Sebelumnya\">Previous</div><div class=\"ttl\">&larr; Security rating</div></a><a class=\"next\" href=\"#/ai-settings\"><div class=\"dir\" data-id=\"Berikutnya\">Next</div><div class=\"ttl\">AI configuration &rarr;</div></a></div>"
  },
  "ai-settings": {
    "id": "ai-settings",
    "title": "AI configuration",
    "eyebrow": "Intelligence",
    "lede": "Connect your AI provider once on the AI Settings page and every AI feature in your workspace uses it. Setup takes about two minutes, and each step and each provider below has a screenshot of a working example.",
    "html": "<span class=\"eyebrow\" data-id=\"Intelijen\">Intelligence</span>\n  <h1 data-id=\"Konfigurasi AI\">AI configuration</h1>\n  <p class=\"lede\" data-id=\"Hubungkan penyedia AI Anda satu kali di halaman AI Settings, dan setiap fitur AI di workspace Anda memakainya. Penyiapannya sekitar dua menit, dan setiap langkah serta setiap penyedia di bawah ini disertai screenshot contoh yang berhasil.\">Connect your AI provider once on the AI Settings page and every AI feature in your workspace uses it. Setup takes about two minutes, and each step and each provider below has a screenshot of a working example.</p>\n\n  <h2 data-id=\"Sebelum mulai\">Before you start</h2>\n  <p data-id=\"Anda memerlukan paket CounterAttack berbayar, dan Anda harus menjadi owner workspace atau Admin. Siapkan hal-hal ini dari penyedia AI Anda:\">You need a paid CounterAttack plan, and you must be the workspace owner or an Admin. Have these ready from your AI provider:</p>\n  <ul>\n    <li data-id=\"&lt;strong&gt;API key&lt;/strong&gt;, dibuat di dashboard penyedia Anda.\"><strong>API key</strong>, created in your provider's dashboard.</li>\n    <li data-id=\"&lt;strong&gt;Nama model&lt;/strong&gt; yang ingin Anda pakai (CounterAttack menampilkan daftarnya setelah key dimasukkan).\"><strong>Model name</strong> you want to use (CounterAttack lists them once the key is in).</li>\n    <li data-id=\"&lt;strong&gt;Base URL&lt;/strong&gt;, hanya jika Anda memakai AI router atau gateway Anda sendiri.\"><strong>Base URL</strong>, only if you use an AI router or your own gateway.</li>\n  </ul>\n  <p data-id=\"Satu kali penyiapan berlaku untuk seluruh workspace. Anggota tim memakainya secara otomatis dan tidak pernah melihat key-nya.\">One setup covers the whole workspace. Team members use it automatically and never see the key.</p>\n\n  <h2 data-id=\"Menyiapkan penyedia\">Setting up the provider</h2>\n  <ol class=\"steps\">\n    <li data-id=\"&lt;strong&gt;Buka AI Settings.&lt;/strong&gt; Klik &lt;strong class=&quot;inline&quot;&gt;AI Settings&lt;/strong&gt; di sidebar kiri. Anda juga bisa mengklik tombol &lt;strong class=&quot;inline&quot;&gt;AI Agent&lt;/strong&gt; di kanan bawah halaman mana pun: selama AI belum disiapkan, tombol itu menampilkan pesan ini beserta pintasannya.\"><strong>Open AI Settings.</strong> Click <strong class=\"inline\">AI Settings</strong> in the left sidebar. You can also click the <strong class=\"inline\">AI Agent</strong> button at the bottom right of any page: until AI is set up, it shows this message with a shortcut.</li>\n    <li data-id=\"&lt;strong&gt;Pilih Provider.&lt;/strong&gt; Pilih layanan yang key-nya Anda miliki. Memakai 9router, LiteLLM, vLLM, atau Groq? Pilih &lt;strong class=&quot;inline&quot;&gt;Other or AI router&lt;/strong&gt;.\"><strong>Pick the Provider.</strong> Choose the service you have a key for. Using 9router, LiteLLM, vLLM or Groq? Choose <strong class=\"inline\">Other or AI router</strong>.</li>\n    <li data-id=\"&lt;strong&gt;Isi field khusus penyedia.&lt;/strong&gt; Hanya sebagian penyedia yang menampilkannya.\"><strong>Fill in the provider-specific fields.</strong> Only some providers show them.\n      <ul>\n        <li data-id=\"&lt;strong&gt;Request format&lt;/strong&gt; (Other or AI router): biarkan &lt;strong&gt;OpenAI-compatible&lt;/strong&gt; kecuali penyedia Anda menyatakan memakai format Anthropic.\"><strong>Request format</strong> (Other or AI router): keep <strong>OpenAI-compatible</strong> unless your provider says it uses Anthropic's format.</li>\n        <li data-id=\"&lt;strong&gt;Base URL&lt;/strong&gt; (Other or AI router): alamat endpoint Anda, biasanya diakhiri &lt;code&gt;/v1&lt;/code&gt;.\"><strong>Base URL</strong> (Other or AI router): your endpoint's address, usually ending in <code>/v1</code>.</li>\n        <li data-id=\"&lt;strong&gt;AWS region&lt;/strong&gt; (Amazon Bedrock): misalnya &lt;code&gt;ap-southeast-1&lt;/code&gt;.\"><strong>AWS region</strong> (Amazon Bedrock): for example <code>ap-southeast-1</code>.</li>\n      </ul>\n    </li>\n    <li data-id=\"&lt;strong&gt;Tempel API key.&lt;/strong&gt; &lt;strong class=&quot;inline&quot;&gt;Enable AI features&lt;/strong&gt; tercentang dengan sendirinya saat pertama kali Anda menambahkan key.\"><strong>Paste the API key.</strong> <strong class=\"inline\">Enable AI features</strong> ticks itself the first time you add a key.</li>\n    <li data-id=\"&lt;strong&gt;Pilih Model.&lt;/strong&gt; Klik field-nya lalu pilih dari daftar yang dimuat CounterAttack dari penyedia Anda, atau ketik nama persisnya.\"><strong>Choose the Model.</strong> Click the field and pick from the list CounterAttack loads from your provider, or type the exact name.</li>\n    <li data-id=\"&lt;strong&gt;Tes, lalu simpan.&lt;/strong&gt; Klik &lt;strong class=&quot;inline&quot;&gt;Test connection&lt;/strong&gt;, lalu &lt;strong class=&quot;inline&quot;&gt;Save&lt;/strong&gt;. Keduanya dijelaskan di bawah.\"><strong>Test, then save.</strong> Click <strong class=\"inline\">Test connection</strong>, then <strong class=\"inline\">Save</strong>. Both are covered below.</li>\n  </ol>\n  <p data-id=\"Biarkan &lt;strong&gt;Advanced&lt;/strong&gt; tertutup. Satu-satunya pengaturan di dalamnya, Max answer length, bernilai bawaan 1500 token, yang sudah pas untuk semua fitur CounterAttack.\">Leave <strong>Advanced</strong> closed. Its only setting, Max answer length, defaults to 1500 tokens, which suits every CounterAttack feature.</p>\n\n  <div class=\"shot\" style=\"max-width:300px;\">\n    <img class=\"shot-img\" src=\"assets/ai-agent-button.png\" width=\"440\" height=\"890\" loading=\"lazy\"\n         alt=\"The AI Agent panel before AI is set up: AI features aren't enabled yet, with an Open AI Settings button.\" />\n  </div>\n  <p class=\"shot-cap\" data-id=\"Panel AI Agent sebelum AI disiapkan, lengkap dengan pintasan Open AI Settings.\">The AI Agent panel before AI is set up, with its Open AI Settings shortcut.</p>\n\n  <div class=\"shot\">\n    <img class=\"shot-img\" src=\"assets/ai-settings-empty.png\" width=\"1344\" height=\"1148\" loading=\"lazy\"\n         alt=\"The AI Settings page before any configuration: Enable AI features unticked, Provider on OpenAI, empty API key and Model fields.\" />\n  </div>\n  <p class=\"shot-cap\" data-id=\"Workspace baru membuka formulir kosong dengan OpenAI terpilih.\">A new workspace opens on an empty form with OpenAI selected.</p>\n\n  <div class=\"shot\">\n    <img class=\"shot-img\" src=\"assets/ai-settings-openai.png\" width=\"1344\" height=\"1248\" loading=\"lazy\"\n         alt=\"AI Settings filled in for OpenAI with model gpt-4o-mini and a green Provider reachable test result.\" />\n  </div>\n  <p class=\"shot-cap\" data-id=\"Formulir yang sudah terisi untuk OpenAI, setelah tes berhasil.\">A completed form for OpenAI, after a passing test.</p>\n\n  <h2 data-id=\"Contoh konfigurasi\">Example configurations</h2>\n  <p data-id=\"Gunakan key Anda sendiri dan model yang bisa diakses akun Anda; nilai di bawah ini hanyalah contoh.\">Use your own key and a model your account can access; the values below are examples.</p>\n\n  <h3>OpenAI</h3>\n  <table class=\"tbl\" style=\"margin:8px 0 10px;\">\n    <thead><tr><th>Field</th><th data-id=\"Nilai\">Value</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Provider</strong></td><td>OpenAI</td></tr>\n      <tr><td><strong>API key</strong></td><td data-id=\"Diawali &lt;code&gt;sk-&lt;/code&gt;, dari dashboard OpenAI Anda\">Starts with <code>sk-</code>, from your OpenAI dashboard</td></tr>\n      <tr><td><strong>Model</strong></td><td class=\"mono\">gpt-4o-mini</td></tr>\n    </tbody>\n  </table>\n  <p data-id=\"Screenshot: lihat formulir lengkap di atas.\">Screenshot: see the completed form above.</p>\n\n  <h3>Anthropic (Claude)</h3>\n  <table class=\"tbl\" style=\"margin:8px 0 10px;\">\n    <thead><tr><th>Field</th><th data-id=\"Nilai\">Value</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Provider</strong></td><td>Anthropic (Claude)</td></tr>\n      <tr><td><strong>API key</strong></td><td data-id=\"Diawali &lt;code&gt;sk-ant-&lt;/code&gt;, dari Anthropic Console\">Starts with <code>sk-ant-</code>, from the Anthropic Console</td></tr>\n      <tr><td><strong>Model</strong></td><td class=\"mono\">claude-sonnet-5-5</td></tr>\n    </tbody>\n  </table>\n  <div class=\"shot\">\n    <img class=\"shot-img\" src=\"assets/ai-settings-anthropic.png\" width=\"1344\" height=\"1148\" loading=\"lazy\"\n         alt=\"AI Settings filled in for Anthropic with model claude-sonnet-5-5.\" />\n  </div>\n\n  <h3>OpenRouter</h3>\n  <table class=\"tbl\" style=\"margin:8px 0 10px;\">\n    <thead><tr><th>Field</th><th data-id=\"Nilai\">Value</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Provider</strong></td><td>OpenRouter</td></tr>\n      <tr><td><strong>API key</strong></td><td data-id=\"Diawali &lt;code&gt;sk-or-&lt;/code&gt;, dari akun OpenRouter Anda\">Starts with <code>sk-or-</code>, from your OpenRouter account</td></tr>\n      <tr><td><strong>Model</strong></td><td class=\"mono\">deepseek/deepseek-v4.1-flash</td></tr>\n    </tbody>\n  </table>\n  <div class=\"shot\">\n    <img class=\"shot-img\" src=\"assets/ai-settings-openrouter.png\" width=\"1344\" height=\"1148\" loading=\"lazy\"\n         alt=\"AI Settings filled in for OpenRouter with model deepseek/deepseek-v4.1-flash.\" />\n  </div>\n\n  <h3 data-id=\"AI router (9router, LiteLLM, dan sejenisnya)\">AI router (9router, LiteLLM and similar)</h3>\n  <table class=\"tbl\" style=\"margin:8px 0 10px;\">\n    <thead><tr><th>Field</th><th data-id=\"Nilai\">Value</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Provider</strong></td><td>Other or AI router</td></tr>\n      <tr><td><strong>Request format</strong></td><td>OpenAI-compatible</td></tr>\n      <tr><td><strong>Base URL</strong></td><td data-id=\"Alamat router Anda ditambah &lt;code&gt;/v1&lt;/code&gt;, misalnya &lt;code&gt;https://9router.example.com/v1&lt;/code&gt;\">Your router's address plus <code>/v1</code>, for example <code>https://9router.example.com/v1</code></td></tr>\n      <tr><td><strong>API key</strong></td><td data-id=\"Key yang diberikan router Anda\">The key your router gives you</td></tr>\n      <tr><td><strong>Model</strong></td><td data-id=\"Sesuai yang didaftarkan router Anda, misalnya &lt;code&gt;kr/glm-5&lt;/code&gt;\">As your router lists it, for example <code>kr/glm-5</code></td></tr>\n    </tbody>\n  </table>\n  <div class=\"shot\">\n    <img class=\"shot-img\" src=\"assets/ai-settings-router.png\" width=\"1344\" height=\"1532\" loading=\"lazy\"\n         alt=\"AI Settings filled in for a 9router endpoint with model kr/glm-5 and a passing connection test.\" />\n  </div>\n\n  <h3>Amazon Bedrock</h3>\n  <table class=\"tbl\" style=\"margin:8px 0 10px;\">\n    <thead><tr><th>Field</th><th data-id=\"Nilai\">Value</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Provider</strong></td><td>Amazon Bedrock</td></tr>\n      <tr><td><strong>AWS region</strong></td><td data-id=\"Region tempat model Anda berjalan, misalnya &lt;code&gt;ap-southeast-1&lt;/code&gt;\">The region your models run in, for example <code>ap-southeast-1</code></td></tr>\n      <tr><td><strong>API key</strong></td><td data-id=\"Sebuah Bedrock API key\">A Bedrock API key</td></tr>\n      <tr><td><strong>Model</strong></td><td data-id=\"ID model Bedrock, misalnya &lt;code&gt;anthropic.claude-3-5-sonnet-20241022-v2:0&lt;/code&gt;\">The Bedrock model ID, for example <code>anthropic.claude-3-5-sonnet-20241022-v2:0</code></td></tr>\n    </tbody>\n  </table>\n  <p data-id=\"CounterAttack menyusun alamatnya dari region tersebut dan menampilkannya di bawah field. Jika daftar model tidak muncul, ketik sendiri model ID dari console Bedrock.\">CounterAttack builds the address from the region and shows it under the field. If no model list appears, type the model ID from the Bedrock console.</p>\n  <div class=\"shot\">\n    <img class=\"shot-img\" src=\"assets/ai-settings-bedrock.png\" width=\"1344\" height=\"1350\" loading=\"lazy\"\n         alt=\"AI Settings filled in for Amazon Bedrock in region ap-southeast-1.\" />\n  </div>\n\n  <h2 data-id=\"Tes dan simpan\">Test and save</h2>\n  <p data-id=\"Klik &lt;strong&gt;Test connection&lt;/strong&gt; sebelum menyimpan. CounterAttack mengirim satu prompt tes singkat memakai apa yang ada di layar, baik sudah tersimpan maupun belum.\">Click <strong>Test connection</strong> before saving. It sends one short test prompt using what is on screen, saved or not.</p>\n  <ul>\n    <li data-id=\"&lt;strong&gt;Hijau:&lt;/strong&gt; &lt;em&gt;Provider reachable&lt;/em&gt;, diikuti balasan model. Klik &lt;strong&gt;Save&lt;/strong&gt;.\"><strong>Green:</strong> <em>Provider reachable</em>, followed by the model's reply. Click <strong>Save</strong>.</li>\n    <li data-id=\"&lt;strong&gt;Merah:&lt;/strong&gt; alasan dari penyedia. Perbaiki field yang ditunjuknya lalu tes lagi; lihat Troubleshooting.\"><strong>Red:</strong> the provider's reason. Fix the field it points to and test again; see Troubleshooting.</li>\n  </ul>\n  <div class=\"shot\">\n    <img class=\"shot-img\" src=\"assets/ai-settings-test-failed.png\" width=\"1344\" height=\"1248\" loading=\"lazy\"\n         alt=\"A failed connection test in AI Settings: AI provider rejected the request, incorrect API key.\" />\n  </div>\n  <p class=\"shot-cap\" data-id=\"Tes yang gagal karena API key salah.\">A failed test with a wrong API key.</p>\n  <p data-id=\"Setelah &lt;strong&gt;Save&lt;/strong&gt;, halaman menampilkan pengaturan Anda dengan key tersembunyi. Fitur AI kini tersedia untuk semua orang di workspace.\">After <strong>Save</strong>, the page shows your settings with the key hidden. AI features are now available to everyone in the workspace.</p>\n  <div class=\"shot\">\n    <img class=\"shot-img\" src=\"assets/ai-settings-saved.png\" width=\"1344\" height=\"1546\" loading=\"lazy\"\n         alt=\"AI Settings after saving: the API key shows as Saved key (hidden).\" />\n  </div>\n  <p class=\"shot-cap\" data-id=\"Setelah disimpan, key ditampilkan sebagai Saved key (hidden).\">After saving, the key shows as Saved key (hidden).</p>\n\n  <h2 data-id=\"Mengganti key, mengganti model, atau mematikan AI\">Change the key, the model, or turn AI off</h2>\n  <table class=\"tbl\" style=\"margin:8px 0 22px;\">\n    <thead><tr><th data-id=\"Untuk\">To</th><th data-id=\"Lakukan ini\">Do this</th></tr></thead>\n    <tbody>\n      <tr><td><strong data-id=\"Mengganti key\">Replace the key</strong></td><td data-id=\"Ketik key baru di &lt;strong&gt;API key&lt;/strong&gt;, tes, lalu &lt;strong&gt;Save&lt;/strong&gt;. Membiarkan field-nya kosong berarti key yang tersimpan tetap dipakai.\">Type the new key in <strong>API key</strong>, test, then <strong>Save</strong>. Leaving the field empty keeps the saved key.</td></tr>\n      <tr><td><strong data-id=\"Menghapus key\">Remove the key</strong></td><td data-id=\"Klik &lt;strong&gt;Remove saved key&lt;/strong&gt;, lalu &lt;strong&gt;Save&lt;/strong&gt;.\">Click <strong>Remove saved key</strong>, then <strong>Save</strong>.</td></tr>\n      <tr><td><strong data-id=\"Mengganti model atau penyedia\">Switch model or provider</strong></td><td data-id=\"Ubah field-nya, tes, lalu &lt;strong&gt;Save&lt;/strong&gt;. Hasil AI yang tersimpan akan diperbarui saat berikutnya dihasilkan.\">Change the field, test, then <strong>Save</strong>. Saved AI results refresh the next time they are generated.</td></tr>\n      <tr><td><strong data-id=\"Mematikan AI\">Turn AI off</strong></td><td data-id=\"Hilangkan centang &lt;strong&gt;Enable AI features&lt;/strong&gt;, lalu &lt;strong&gt;Save&lt;/strong&gt;. Fitur AI menghilang dan tidak ada apa pun yang dikirim ke penyedia Anda.\">Untick <strong>Enable AI features</strong>, then <strong>Save</strong>. AI features disappear and nothing is sent to your provider.</td></tr>\n    </tbody>\n  </table>\n\n  <h2 data-id=\"Pemecahan masalah\">Troubleshooting</h2>\n  <p data-id=\"Sebagian besar kegagalan disebabkan Base URL, key, atau nama model yang salah. Cari pesan yang Anda lihat:\">Most failures are a wrong Base URL, key or model name. Find the message you see:</p>\n  <table class=\"tbl\" style=\"margin:8px 0 22px;\">\n    <thead><tr><th data-id=\"Pesan\">Message</th><th data-id=\"Perbaikan\">Fix</th></tr></thead>\n    <tbody>\n      <tr><td>Set a base URL, API key, and model first.</td><td data-id=\"Isi semua field yang ditampilkan penyedia Anda.\">Fill in every field your provider shows.</td></tr>\n      <tr><td>AI provider rejected the request: ...</td><td data-id=\"Baca alasan setelah tanda titik dua. Biasanya key salah, nama model salah, atau kredit habis.\">Read the reason after the colon. Usually a wrong key, a wrong model name, or no credit left.</td></tr>\n      <tr><td>Could not reach the AI provider: ...</td><td data-id=\"Periksa Base URL dari salah ketik, lalu coba lagi nanti.\">Check the Base URL for typos, then try again later.</td></tr>\n      <tr><td>The AI provider returned a non-JSON response ...</td><td data-id=\"Base URL mengarah ke sebuah halaman web. Tambahkan path API-nya, biasanya &lt;code&gt;/v1&lt;/code&gt;, di bagian akhir.\">The Base URL points at a web page. Add the API path, usually <code>/v1</code>, to the end.</td></tr>\n      <tr><td>Unexpected response shape from the AI provider.</td><td data-id=\"Ganti &lt;strong&gt;Request format&lt;/strong&gt; ke pilihan satunya lalu tes lagi.\">Switch <strong>Request format</strong> to the other option and test again.</td></tr>\n      <tr><td>The AI provider did not respond in time.</td><td data-id=\"Coba lagi, atau pilih model yang lebih cepat.\">Try again, or choose a faster model.</td></tr>\n      <tr><td>The provider rejected the API key. <span class=\"subtle\" data-id=\"(di bawah Model)\">(under Model)</span></td><td data-id=\"Tempel ulang key-nya.\">Paste the key again.</td></tr>\n      <tr><td>This provider doesn't offer a model list. Type the model id instead.</td><td data-id=\"Ketik nama model persis seperti yang dituliskan penyedia Anda.\">Type the model name exactly as your provider writes it.</td></tr>\n    </tbody>\n  </table>\n  <div class=\"callout warn\"><i data-lucide=\"alert-triangle\"></i><div><p data-id=\"Base URL harus bisa dijangkau dari internet: server CounterAttack yang mengirim permintaannya, jadi &lt;code&gt;localhost&lt;/code&gt; menunjuk ke server CounterAttack, bukan ke komputer Anda.\">The Base URL must be reachable from the internet: CounterAttack's server sends the requests, so <code>localhost</code> points at CounterAttack's server, not your computer.</p></div></div>\n\n  <div class=\"pager\"><a href=\"#/ai\"><div class=\"dir\" data-id=\"Sebelumnya\">Previous</div><div class=\"ttl\">&larr; AI insights</div></a><a class=\"next\" href=\"#/alerts\"><div class=\"dir\" data-id=\"Berikutnya\">Next</div><div class=\"ttl\">Telegram &amp; email alerts &rarr;</div></a></div>"
  },
  "alerts": {
    "id": "alerts",
    "title": "Telegram &amp; email alerts",
    "eyebrow": "Intelligence",
    "lede": "CounterAttack reaches you where you already are. Email keeps you posted on your scans, and Telegram gives you push alerts plus read-only commands scoped to your own assets.",
    "html": "<span class=\"eyebrow\" data-id=\"Intelijen\">Intelligence</span>\n  <h1 data-id=\"Notifikasi Telegram &amp;amp; email\">Telegram &amp; email alerts</h1>\n  <p class=\"lede\" data-id=\"CounterAttack menjangkau Anda di tempat Anda berada. Email memberi kabar tentang scan Anda, dan Telegram memberi Anda notifikasi push plus perintah read-only yang dibatasi pada aset Anda sendiri.\">CounterAttack reaches you where you already are. Email keeps you posted on your scans, and Telegram gives you push alerts plus read-only commands scoped to your own assets.</p>\n\n  <h2 data-id=\"Notifikasi email\">Email notifications</h2>\n  <p data-id=\"Secara default Anda mendapat email saat sebuah scan dimulai dan sekali lagi berisi ringkasan saat scan selesai atau dihentikan. Anda mengatur ini dari tautan di email scan mana pun, pada halaman &lt;strong&gt;Email preferences&lt;/strong&gt; dengan tiga pilihan:\">By default you get an email when a scan starts and again with a summary when it finishes or is stopped. You control this from a link in any scan email, on an <strong>Email preferences</strong> page with three choices:</p>\n  <ul>\n    <li data-id=\"&lt;strong&gt;Keep everything&lt;/strong&gt;: kirimi saya email saat scan dimulai dan sekali lagi berisi ringkasan.\"><strong>Keep everything</strong>: email me when a scan starts and again with the summary.</li>\n    <li data-id=\"&lt;strong&gt;Fewer emails&lt;/strong&gt;: hanya saat scan selesai atau dihentikan, melewati pemberitahuan &quot;started&quot;.\"><strong>Fewer emails</strong>: only when a scan finishes or is stopped, skipping the \"started\" note.</li>\n    <li data-id=\"&lt;strong&gt;Stop all scan emails&lt;/strong&gt;: tidak ada apa pun tentang scan. Hasil Anda tetap muncul di dashboard.\"><strong>Stop all scan emails</strong>: nothing about scans. Your results still appear on the dashboard.</li>\n  </ul>\n  <p data-id=\"Preferensi ini hanya mencakup notifikasi scan. Email akun, seperti verifikasi alamat dan tanda terima pembayaran, selalu dikirim.\">These preferences cover scan notifications only. Account email, such as address verification and payment receipts, is always sent.</p>\n  <div class=\"shot\">\n    <div class=\"shot-bar\"><span class=\"traffic\"><i></i><i></i><i></i></span><span class=\"url\">app.counterattack.com/unsubscribe</span></div>\n    <div class=\"shot-body\">\n      <div class=\"rl-card\" style=\"max-width:440px;margin:0 auto;\"><div class=\"rl-card-body\">\n        <div style=\"font-size:15px;font-weight:600;margin-bottom:12px;\">Email preferences</div>\n        <div class=\"js-select\">\n          <div class=\"radio-opt js-opt is-sel\"><span class=\"radio-dot\"></span><div><div class=\"ro-title\">Keep everything</div><div class=\"ro-sub\">Email me on start and again with the summary.</div></div></div>\n          <div class=\"radio-opt js-opt\"><span class=\"radio-dot\"></span><div><div class=\"ro-title\">Fewer emails</div><div class=\"ro-sub\">Only when a scan finishes or is stopped.</div></div></div>\n          <div class=\"radio-opt js-opt\"><span class=\"radio-dot\"></span><div><div class=\"ro-title\">Stop all scan emails</div><div class=\"ro-sub\">Nothing about scans.</div></div></div>\n        </div>\n      </div></div>\n    </div>\n  </div>\n\n  <h2 data-id=\"Notifikasi Telegram\">Telegram alerts</h2>\n  <p data-id=\"Hubungkan Telegram dari &lt;a href=&quot;#/profile&quot;&gt;Profile&lt;/a&gt; Anda. CounterAttack memberi tahu Anda saat sebuah scan selesai dan saat temuan critical atau high baru muncul pada aset Anda, serta menjawab perintah chat read-only yang hanya melihat scan dan temuan Anda sendiri.\">Connect Telegram from your <a href=\"#/profile\">Profile</a>. CounterAttack pings you when a scan finishes and when new critical or high findings appear on your assets, and it answers read-only chat commands that only ever see your own scans and findings.</p>\n  <ol class=\"steps\">\n    <li data-id=\"&lt;strong&gt;Klik Connect Telegram.&lt;/strong&gt; CounterAttack membuat kode sekali pakai dan menampilkan sebuah QR code.\"><strong>Click Connect Telegram.</strong> CounterAttack mints a one-time code and shows a QR code.</li>\n    <li data-id=\"&lt;strong&gt;Buka bot.&lt;/strong&gt; Scan QR dengan ponsel Anda, atau buka bot di Telegram dan tekan Start. Kirim kodenya jika diminta.\"><strong>Open the bot.</strong> Scan the QR with your phone, or open the bot in Telegram and press Start. Send the code if asked.</li>\n    <li data-id=\"&lt;strong&gt;Anda sudah terhubung.&lt;/strong&gt; Kartu berubah menjadi Connected dengan sendirinya dan menampilkan username Telegram Anda. Tombol Disconnect memutus tautannya kapan saja.\"><strong>You are linked.</strong> The card flips to Connected on its own and shows your Telegram username. A Disconnect button unlinks it any time.</li>\n  </ol>\n  <div class=\"shot\">\n    <div class=\"shot-bar\"><span class=\"traffic\"><i></i><i></i><i></i></span><span class=\"url\">app.counterattack.com/profile</span></div>\n    <div class=\"shot-body\">\n      <div class=\"rl-card\" style=\"max-width:340px;margin:0 auto;text-align:center;\"><div class=\"rl-card-body\">\n        <div style=\"font-size:14px;font-weight:600;margin-bottom:12px;\">Connect Telegram</div>\n        <svg width=\"120\" height=\"120\" viewBox=\"0 0 25 25\" role=\"img\" aria-label=\"Sample QR code\" style=\"border-radius:8px;background:#fff;margin:0 auto;display:block;\">\n          <rect width=\"25\" height=\"25\" fill=\"#fff\"/>\n          <defs><pattern id=\"qm\" width=\"2\" height=\"2\" patternUnits=\"userSpaceOnUse\"><rect width=\"1\" height=\"1\" fill=\"#0A0A0B\"/><rect x=\"1\" y=\"1\" width=\"1\" height=\"1\" fill=\"#0A0A0B\"/></pattern></defs>\n          <rect x=\"10\" y=\"2\" width=\"13\" height=\"21\" fill=\"url(#qm)\"/>\n          <rect x=\"2\" y=\"10\" width=\"8\" height=\"13\" fill=\"url(#qm)\"/>\n          <g fill=\"#0A0A0B\">\n            <rect x=\"2\" y=\"2\" width=\"7\" height=\"7\"/><rect x=\"3\" y=\"3\" width=\"5\" height=\"5\" fill=\"#fff\"/><rect x=\"4\" y=\"4\" width=\"3\" height=\"3\"/>\n            <rect x=\"16\" y=\"2\" width=\"7\" height=\"7\"/><rect x=\"17\" y=\"3\" width=\"5\" height=\"5\" fill=\"#fff\"/><rect x=\"18\" y=\"4\" width=\"3\" height=\"3\"/>\n            <rect x=\"2\" y=\"16\" width=\"7\" height=\"7\"/><rect x=\"3\" y=\"17\" width=\"5\" height=\"5\" fill=\"#fff\"/><rect x=\"4\" y=\"18\" width=\"3\" height=\"3\"/>\n          </g>\n        </svg>\n        <div style=\"font-size:12px;color:var(--fg-muted);margin-top:12px;\">Scan with your phone, or open the bot and press Start.</div>\n      </div></div>\n    </div>\n  </div>\n\n  <div class=\"callout pro\"><i data-lucide=\"rocket\"></i><div><span class=\"callout-title\" data-id=\"Fitur berbayar\">Paid feature</span><p data-id=\"Notifikasi Telegram tersedia pada Starter ke atas. Pada Free, tombol connect terkunci dan mengarah ke halaman upgrade. Jika akun yang tertaut nanti turun di bawah Starter, notifikasi berhenti sampai Anda upgrade lagi.\">Telegram alerts are available on Starter and above. On Free, the connect button is locked and links to the upgrade page. If a linked account later drops below Starter, alerts pause until you upgrade again.</p></div></div>\n\n  <div class=\"pager\"><a href=\"#/ai-settings\"><div class=\"dir\" data-id=\"Sebelumnya\">Previous</div><div class=\"ttl\">&larr; AI configuration</div></a><a class=\"next\" href=\"#/team\"><div class=\"dir\" data-id=\"Berikutnya\">Next</div><div class=\"ttl\">Team access &rarr;</div></a></div>"
  },
  "team": {
    "id": "team",
    "title": "Team access",
    "eyebrow": "Team",
    "lede": "Team access lets you invite other people into your CounterAttack account and decide, per person, what they can do and which asset groups they can see. It is available on the Business, MSSP and Enterprise plans; Free and Starter accounts stay single-user.",
    "html": "<span class=\"eyebrow\" data-id=\"Tim\">Team</span>\n  <h1 data-id=\"Akses tim\">Team access</h1>\n  <p class=\"lede\" data-id=\"Akses tim memungkinkan Anda mengundang orang lain ke akun CounterAttack Anda dan menentukan, per orang, apa yang boleh mereka lakukan dan asset group mana yang boleh mereka lihat. Tersedia pada paket Business, MSSP, dan Enterprise; akun Free dan Starter tetap satu pengguna.\">Team access lets you invite other people into your CounterAttack account and decide, per person, what they can do and which asset groups they can see. It is available on the Business, MSSP and Enterprise plans; Free and Starter accounts stay single-user.</p>\n\n  <p data-id=\"Semuanya dikelola dari halaman &lt;strong&gt;Team&lt;/strong&gt; di sidebar, yang memiliki tiga tab: &lt;strong&gt;Members&lt;/strong&gt;, &lt;strong&gt;Roles&lt;/strong&gt;, dan &lt;strong&gt;Audit log&lt;/strong&gt;.\">Everything is managed from the <strong>Team</strong> page in the sidebar, which has three tabs: <strong>Members</strong>, <strong>Roles</strong>, and <strong>Audit log</strong>.</p>\n\n  <h2 data-id=\"Konsep utama\">Key concepts</h2>\n  <table class=\"tbl\" style=\"margin:8px 0 22px;\">\n    <thead><tr><th>Term</th><th>Meaning</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Workspace</strong></td><td data-id=\"Sebuah akun CounterAttack dan segala isinya: asset group, scan, temuan, laporan. Setiap akun adalah sebuah workspace. Namanya mengikuti display name pemiliknya dan bisa diganti oleh pemilik.\">A CounterAttack account and everything in it: asset groups, scans, findings, reports. Every account is a workspace. Its name defaults to the owner's display name and the owner can rename it.</td></tr>\n      <tr><td><strong>Owner</strong></td><td data-id=\"Orang yang memiliki workspace tersebut. Selalu memiliki akses penuh ke semuanya, termasuk penagihan. Hanya ada satu owner dan ia tidak bisa dihapus.\">The person whose account the workspace is. Always has full access to everything, including billing. There is exactly one owner and they can't be removed.</td></tr>\n      <tr><td><strong>Member</strong></td><td data-id=\"Orang yang diundang ke sebuah workspace. Seorang member tetap memiliki akun dan workspace CounterAttack-nya sendiri.\">Someone invited into a workspace. A member keeps their own separate CounterAttack account and workspace as well.</td></tr>\n      <tr><td><strong>Role</strong></td><td data-id=\"Apa yang boleh dilakukan seorang member: role bawaan (Admin, Analyst, Viewer) atau custom role yang disusun dari daftar permission. Setiap member memiliki tepat satu role.\">What a member can do: a built-in role (Admin, Analyst, Viewer) or a custom role made from a list of permissions. Each member has exactly one role.</td></tr>\n      <tr><td><strong data-id=\"Cakupan grup\">Group scope</strong></td><td data-id=\"Asset group mana yang boleh dilihat seorang member: &lt;strong&gt;All asset groups&lt;/strong&gt; (termasuk grup yang ditambahkan kemudian) atau &lt;strong&gt;Only selected groups&lt;/strong&gt;. Hasil incident check sebuah domain selalu ikut bersama domainnya.\">Which asset groups a member can see: <strong>All asset groups</strong> (including groups added later) or <strong>Only selected groups</strong>. A domain's incident-check results come along with it automatically.</td></tr>\n      <tr><td><strong>Seat</strong></td><td data-id=\"Satu orang di dalam workspace. Owner, setiap member, dan setiap undangan yang masih tertunda masing-masing memakai satu seat.\">One person in the workspace. The owner, every member and every pending invitation each use one seat.</td></tr>\n    </tbody>\n  </table>\n\n  <h2 data-id=\"Paket dan seat\">Plans and seats</h2>\n  <p data-id=\"Akses tim adalah fitur paket. Member selalu memakai paket, batas aset, dan seat milik owner workspace, bukan milik mereka sendiri.\">Team access is a plan feature. Members always use the workspace owner's plan, asset limit and seats, never their own.</p>\n  <table class=\"tbl\" style=\"margin:8px 0 22px;\">\n    <thead><tr><th>Plan</th><th data-id=\"Akses tim\">Team access</th><th data-id=\"Seat (termasuk owner)\">Seats (owner included)</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Free</strong></td><td data-id=\"Tidak\">No</td><td>1</td></tr>\n      <tr><td><strong>Starter</strong></td><td data-id=\"Tidak\">No</td><td>1</td></tr>\n      <tr><td><strong>Business</strong></td><td data-id=\"Ya\">Yes</td><td>10</td></tr>\n      <tr><td><strong>MSSP</strong></td><td data-id=\"Ya\">Yes</td><td data-id=\"Ditentukan per kontrak (tanpa batas kecuali disepakati sebuah angka)\">Set per contract (unlimited unless a number is agreed)</td></tr>\n      <tr><td><strong>Enterprise</strong></td><td data-id=\"Ya\">Yes</td><td data-id=\"Ditentukan per kontrak (tanpa batas kecuali disepakati sebuah angka)\">Set per contract (unlimited unless a number is agreed)</td></tr>\n    </tbody>\n  </table>\n  <p data-id=\"Business, MSSP, dan Enterprise memiliki fitur tim yang sama persis: mengundang member, role bawaan, custom role, membatasi member ke asset group tertentu, dan audit log workspace. Yang membedakan hanyalah jumlah seat, jumlah aset, dan dukungan.\">Business, MSSP and Enterprise have exactly the same team features: inviting members, the built-in roles, custom roles, limiting members to specific asset groups, and the workspace audit log. They differ only in seats, assets and support.</p>\n\n  <div class=\"callout note\"><i data-lucide=\"users\"></i><div><span class=\"callout-title\" data-id=\"Undangan tertunda memakai seat\">Pending invitations use seats</span><p data-id=\"Undangan yang belum diterima tetap dihitung sebagai seat sampai diterima, dibatalkan, atau kedaluwarsa. Ketika seluruh seat terpakai, undangan baru tidak bisa dikirim. Member yang sudah ada tidak pernah dihapus karena alasan seat, dan menurunkan jumlah seat tidak pernah mengeluarkan siapa pun.\">Pending invitations count as seats until they are accepted, cancelled or expire. When all seats are in use, no new invitations can be sent. Existing members are never removed because of seats, and lowering the seat number never removes anyone.</p></div></div>\n\n  <h2 data-id=\"Jika paket berubah\">If the plan changes</h2>\n  <p data-id=\"Jika paket owner turun di bawah Business, baik karena downgrade maupun lisensi yang kedaluwarsa, semua member &lt;strong&gt;ditangguhkan&lt;/strong&gt;: mereka tidak bisa membuka workspace tersebut dan workspace itu tampil sebagai tidak tersedia di pemilih workspace mereka. Tidak ada data yang dihapus. Begitu paketnya aktif kembali, setiap member otomatis mendapatkan kembali role dan grup yang sama.\">If the owner's plan drops below Business, whether through a downgrade or an expired license, all members are <strong>suspended</strong>: they can't open the workspace and it shows as unavailable in their workspace selector. Nothing is deleted. When the plan is back, every member regains the same role and groups automatically.</p>\n\n  <h2 data-id=\"Ke mana selanjutnya\">Where to go next</h2>\n  <div class=\"feature-grid\">\n    <a class=\"feature-card\" href=\"#/permissions\"><div class=\"fc-icon\"><i data-lucide=\"key-round\"></i></div><h4 data-id=\"Role &amp;amp; permission\">Roles &amp; permissions</h4><p data-id=\"Empat role bawaan, matriks permission lengkap, dan custom role.\">The four built-in roles, the full permission matrix, and custom roles.</p></a>\n    <a class=\"feature-card\" href=\"#/permissions\"><div class=\"fc-icon\"><i data-lucide=\"user-plus\"></i></div><h4 data-id=\"Undang tim Anda\">Invite your team</h4><p data-id=\"Kirim undangan, atur role dan cakupan grup, kelola member.\">Send invitations, set a role and group scope, manage members.</p></a>\n    <a class=\"feature-card\" href=\"#/join\"><div class=\"fc-icon\"><i data-lucide=\"log-in\"></i></div><h4 data-id=\"Bergabung ke workspace\">Join a workspace</h4><p data-id=\"Menerima undangan, berpindah workspace, dan keluar dari satu workspace.\">Accepting an invitation, switching workspaces, and leaving one.</p></a>\n    <a class=\"feature-card\" href=\"#/mssp\"><div class=\"fc-icon\"><i data-lucide=\"building-2\"></i></div><h4 data-id=\"Akses klien untuk MSSP\">Client access for MSSPs</h4><p data-id=\"Beri setiap klien tampilan read-only atas domain mereka sendiri saja.\">Give each client a read-only view of their own domains only.</p></a>\n  </div>\n\n  <div class=\"pager\"><a href=\"#/alerts\"><div class=\"dir\" data-id=\"Sebelumnya\">Previous</div><div class=\"ttl\">&larr; Alerts</div></a><a class=\"next\" href=\"#/permissions\"><div class=\"dir\" data-id=\"Berikutnya\">Next</div><div class=\"ttl\">Roles &amp; permissions &rarr;</div></a></div>"
  },
  "permissions": {
    "id": "permissions",
    "title": "Roles &amp; permissions",
    "eyebrow": "Team",
    "lede": "A role defines what a member can do inside a workspace. Each member has exactly one role, plus a group scope that decides which asset groups it applies to. This page covers the four roles, every permission they carry, and how to invite and manage people.",
    "html": "<span class=\"eyebrow\" data-id=\"Tim\">Team</span>\n  <h1 data-id=\"Role &amp;amp; permission\">Roles &amp; permissions</h1>\n  <p class=\"lede\" data-id=\"Sebuah role menentukan apa yang boleh dilakukan seorang member di dalam workspace. Setiap member memiliki tepat satu role, ditambah cakupan grup yang menentukan asset group mana yang berlaku baginya. Halaman ini mencakup keempat role, setiap permission yang dibawanya, dan cara mengundang serta mengelola orang.\">A role defines what a member can do inside a workspace. Each member has exactly one role, plus a group scope that decides which asset groups it applies to. This page covers the four roles, every permission they carry, and how to invite and manage people.</p>\n\n  <h2 data-id=\"Role\">Roles</h2>\n  <p data-id=\"Diurutkan dari permission paling sedikit ke paling banyak. Role bawaan tidak bisa diubah; untuk variasi lain, buat sebuah custom role.\">Ordered from the fewest permissions to the most. Built-in roles can't be edited; to get a variation, create a custom role.</p>\n  <table class=\"tbl\" style=\"margin:8px 0 22px;\">\n    <thead><tr><th>Role</th><th data-id=\"Deskripsi\">Description</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Viewer</strong></td><td data-id=\"Hanya baca. Tidak bisa mengubah data, memulai scan, membuat laporan, atau menggunakan AI.\">Read-only. Cannot change data, start scans, generate reports, or use AI.</td></tr>\n      <tr><td><strong>Analyst</strong></td><td data-id=\"Melihat, melakukan triase, menjalankan scan, dan membuat laporan. Tidak bisa menghapus apa pun, menambah domain, atau mengelola orang.\">View, triage, scan, and generate reports. Cannot delete anything, add domains, or manage people.</td></tr>\n      <tr><td><strong>Admin</strong></td><td data-id=\"Akses penuh atas pekerjaan dan orang, termasuk custom role dan audit log. Tidak bisa mengurus penagihan atau menghapus workspace.\">Full access to the work and the people, including custom roles and the audit log. Cannot touch billing or delete the workspace.</td></tr>\n      <tr><td><strong>Owner</strong></td><td data-id=\"Pemegang akun. Segalanya, termasuk penagihan, paket, dan Factory Reset. Tidak bisa diberikan kepada siapa pun.\">The account holder. Everything, including billing, plans, and Factory Reset. Not assignable to anyone.</td></tr>\n    </tbody>\n  </table>\n\n  <h2 data-id=\"Permission asset group\">Asset group permissions</h2>\n  <table class=\"tbl\" style=\"margin:8px 0 22px;\">\n    <thead><tr><th data-id=\"Tindakan\">Action</th><th>Viewer</th><th>Analyst</th><th>Admin</th><th>Owner</th></tr></thead>\n    <tbody>\n      <tr><td data-id=\"Melihat asset group dan dashboard\">View asset groups and the dashboard</td><td>&#10003;</td><td>&#10003;</td><td>&#10003;</td><td>&#10003;</td></tr>\n      <tr><td data-id=\"Melihat aset dan detail aset\">View assets and asset details</td><td>&#10003;</td><td>&#10003;</td><td>&#10003;</td><td>&#10003;</td></tr>\n      <tr><td data-id=\"Melihat DNS dan subdomain\">View DNS and subdomains</td><td>&#10003;</td><td>&#10003;</td><td>&#10003;</td><td>&#10003;</td></tr>\n      <tr><td data-id=\"Melihat screenshot aset\">View asset screenshots</td><td>&#10003;</td><td>&#10003;</td><td>&#10003;</td><td>&#10003;</td></tr>\n      <tr><td data-id=\"Menambahkan domain baru ke workspace\">Add a new domain to the workspace</td><td></td><td></td><td>&#10003;</td><td>&#10003;</td></tr>\n      <tr><td data-id=\"Mengatur jadwal rescan dan pengecualian aset\">Set the rescan schedule and asset exclusions</td><td></td><td></td><td>&#10003;</td><td>&#10003;</td></tr>\n      <tr><td data-id=\"Menghapus grup beserta seluruh datanya\">Delete a group and all its data</td><td></td><td></td><td>&#10003;</td><td>&#10003;</td></tr>\n    </tbody>\n  </table>\n\n  <h2 data-id=\"Permission temuan\">Finding permissions</h2>\n  <table class=\"tbl\" style=\"margin:8px 0 22px;\">\n    <thead><tr><th data-id=\"Tindakan\">Action</th><th>Viewer</th><th>Analyst</th><th>Admin</th><th>Owner</th></tr></thead>\n    <tbody>\n      <tr><td data-id=\"Melihat vulnerability\">View vulnerabilities</td><td>&#10003;</td><td>&#10003;</td><td>&#10003;</td><td>&#10003;</td></tr>\n      <tr><td data-id=\"Melihat incident\">View incidents</td><td>&#10003;</td><td>&#10003;</td><td>&#10003;</td><td>&#10003;</td></tr>\n      <tr><td data-id=\"Melihat halaman Activity\">View the Activity page</td><td>&#10003;</td><td>&#10003;</td><td>&#10003;</td><td>&#10003;</td></tr>\n      <tr><td data-id=\"Melakukan triase vulnerability: status, false positive, resolve\">Triage vulnerabilities: status, false positive, resolve</td><td></td><td>&#10003;</td><td>&#10003;</td><td>&#10003;</td></tr>\n      <tr><td data-id=\"Melakukan triase incident: status, false positive, verifikasi ulang\">Triage incidents: status, false positive, re-verify</td><td></td><td>&#10003;</td><td>&#10003;</td><td>&#10003;</td></tr>\n      <tr><td data-id=\"Menghapus sebuah temuan\">Delete a finding</td><td></td><td></td><td>&#10003;</td><td>&#10003;</td></tr>\n    </tbody>\n  </table>\n\n  <h2 data-id=\"Permission scan dan laporan\">Scan and report permissions</h2>\n  <table class=\"tbl\" style=\"margin:8px 0 22px;\">\n    <thead><tr><th data-id=\"Tindakan\">Action</th><th>Viewer</th><th>Analyst</th><th>Admin</th><th>Owner</th></tr></thead>\n    <tbody>\n      <tr><td data-id=\"Melihat dan mengunduh laporan\">View and download reports</td><td>&#10003;</td><td>&#10003;</td><td>&#10003;</td><td>&#10003;</td></tr>\n      <tr><td data-id=\"Menjalankan scan dan rescan\">Run scans and rescans</td><td></td><td>&#10003;</td><td>&#10003;</td><td>&#10003;</td></tr>\n      <tr><td data-id=\"Membatalkan scan yang sedang berjalan\">Cancel a running scan</td><td></td><td>&#10003;</td><td>&#10003;</td><td>&#10003;</td></tr>\n      <tr><td data-id=\"Membuat laporan PDF dan CSV\">Generate PDF and CSV reports</td><td></td><td>&#10003;</td><td>&#10003;</td><td>&#10003;</td></tr>\n      <tr><td data-id=\"Menghapus sebuah laporan\">Delete a report</td><td></td><td></td><td>&#10003;</td><td>&#10003;</td></tr>\n    </tbody>\n  </table>\n\n  <h2 data-id=\"Permission AI\">AI permissions</h2>\n  <table class=\"tbl\" style=\"margin:8px 0 22px;\">\n    <thead><tr><th data-id=\"Tindakan\">Action</th><th>Viewer</th><th>Analyst</th><th>Admin</th><th>Owner</th></tr></thead>\n    <tbody>\n      <tr><td data-id=\"Menggunakan analisis dan triase AI\">Use AI analysis and triage</td><td></td><td>&#10003;</td><td>&#10003;</td><td>&#10003;</td></tr>\n      <tr><td data-id=\"Menggunakan chat asisten AI\">Use the AI assistant chat</td><td></td><td>&#10003;</td><td>&#10003;</td><td>&#10003;</td></tr>\n      <tr><td data-id=\"Mengubah pengaturan AI provider&lt;sup&gt;1&lt;/sup&gt;\">Change AI provider settings<sup>1</sup></td><td></td><td></td><td>&#10003;</td><td>&#10003;</td></tr>\n    </tbody>\n  </table>\n\n  <h2 data-id=\"Permission workspace\">Workspace permissions</h2>\n  <table class=\"tbl\" style=\"margin:8px 0 22px;\">\n    <thead><tr><th data-id=\"Tindakan\">Action</th><th>Viewer</th><th>Analyst</th><th>Admin</th><th>Owner</th></tr></thead>\n    <tbody>\n      <tr><td data-id=\"Mengundang, mengubah, dan menghapus member&lt;sup&gt;1&lt;/sup&gt;\">Invite, change, and remove members<sup>1</sup></td><td></td><td></td><td>&#10003;</td><td>&#10003;</td></tr>\n      <tr><td data-id=\"Membuat, mengubah, dan menghapus custom role&lt;sup&gt;1&lt;/sup&gt;\">Create, edit, and delete custom roles<sup>1</sup></td><td></td><td></td><td>&#10003;</td><td>&#10003;</td></tr>\n      <tr><td data-id=\"Melihat audit log workspace&lt;sup&gt;1&lt;/sup&gt;\">View the workspace audit log<sup>1</sup></td><td></td><td></td><td>&#10003;</td><td>&#10003;</td></tr>\n      <tr><td data-id=\"Mengelola penagihan dan mengubah paket\">Manage billing and change the plan</td><td></td><td></td><td></td><td>&#10003;</td></tr>\n      <tr><td data-id=\"Mengganti nama workspace\">Rename the workspace</td><td></td><td></td><td></td><td>&#10003;</td></tr>\n      <tr><td data-id=\"Factory Reset: menghapus seluruh data workspace\">Factory Reset: delete all workspace data</td><td></td><td></td><td></td><td>&#10003;</td></tr>\n    </tbody>\n  </table>\n\n  <p class=\"subtle\" data-id=\"&lt;strong&gt;1&lt;/strong&gt; Hanya untuk semua grup. Keempat permission ini hanya berfungsi bagi member yang memiliki akses ke &lt;strong&gt;semua&lt;/strong&gt; asset group, dan otomatis dilepas dari member yang dibatasi pada grup tertentu.\"><strong>1</strong> All-groups only. These four permissions only work for a member with access to <strong>all</strong> asset groups, and are dropped automatically for a member limited to selected groups.</p>\n\n  <h2 data-id=\"Cakupan grup\">Group scope</h2>\n  <p data-id=\"Permission menentukan &lt;em&gt;apa&lt;/em&gt; yang boleh dilakukan seseorang; cakupan grup menentukan &lt;em&gt;di mana&lt;/em&gt;. Setiap member diatur ke &lt;strong&gt;All asset groups&lt;/strong&gt;, yang juga mencakup grup yang ditambahkan nanti, atau ke &lt;strong&gt;Only selected groups&lt;/strong&gt;.\">Permissions decide <em>what</em> someone can do; group scope decides <em>where</em>. Every member is set to <strong>All asset groups</strong>, which also covers groups added later, or to <strong>Only selected groups</strong>.</p>\n  <p data-id=\"Cakupan berlaku di seluruh produk: daftar grup, dashboard, temuan, incident, laporan, activity, dan asisten AI. Member yang dibatasi pada grup tertentu melihat tautan ke grup lain sebagai &quot;Not found&quot;. Hasil incident check selalu mengikuti domainnya. Lihat &lt;a href=&quot;#/mssp&quot;&gt;Akses klien untuk MSSP&lt;/a&gt; untuk contoh lengkapnya.\">Scope applies everywhere in the product: the groups list, dashboard, findings, incidents, reports, activity and the AI assistant. A member limited to selected groups sees a link to another group as \"Not found\". A domain's incident-check results always follow the domain. See <a href=\"#/mssp\">Client access for MSSPs</a> for a worked example.</p>\n\n  <h2 data-id=\"Custom role\">Custom roles</h2>\n  <p data-id=\"Butuh permission &lt;strong&gt;Manage roles&lt;/strong&gt;. Buka &lt;strong&gt;Team &amp;rarr; Roles&lt;/strong&gt;, klik &lt;strong&gt;New custom role&lt;/strong&gt;, beri nama, centang permission yang diinginkan, lalu simpan. Role baru itu muncul di pemilih role saat mengundang atau mengubah member.\">Requires the <strong>Manage roles</strong> permission. Open <strong>Team &rarr; Roles</strong>, click <strong>New custom role</strong>, give it a name, tick the permissions you want, and save. The new role appears in the role picker when inviting or editing members.</p>\n  <ul>\n    <li data-id=\"Anda hanya bisa mencentang permission yang Anda miliki sendiri; sisanya tampil abu-abu.\">You can only tick permissions you hold yourself; the others are greyed out.</li>\n    <li data-id=\"Sebuah nama tidak boleh memakai nama role bawaan: Owner, Admin, Analyst, atau Viewer.\">A name can't reuse a built-in role's name: Owner, Admin, Analyst or Viewer.</li>\n    <li data-id=\"Mengubah sebuah custom role mengubah akses semua orang yang memegangnya, pada klik berikutnya.\">Editing a custom role changes access for everyone who has it, on their next click.</li>\n    <li data-id=\"Sebuah role tidak bisa dihapus selama masih ada member yang memegangnya; pindahkan mereka ke role lain dulu. Undangan tertunda yang memakai role yang dihapus tidak bisa lagi diterima.\">A role can't be deleted while members have it; move them to another role first. A pending invitation that used a deleted role can no longer be accepted.</li>\n  </ul>\n  <table class=\"tbl\" style=\"margin:8px 0 22px;\">\n    <thead><tr><th data-id=\"Contoh custom role\">Example custom role</th><th>Permissions</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Client read-only</strong></td><td class=\"mono\">Asset groups: View &middot; Assets: View &middot; Vulnerabilities: View &middot; Reports: View</td></tr>\n      <tr><td><strong>Vulnerability analyst</strong></td><td class=\"mono\">Asset groups: View &middot; Assets: View &middot; Vulnerabilities: View, Triage &middot; Scans: Run &middot; Reports: View, Generate</td></tr>\n      <tr><td><strong>Report reader</strong></td><td class=\"mono\">Asset groups: View &middot; Reports: View</td></tr>\n    </tbody>\n  </table>\n\n  <h2 data-id=\"Mengundang orang\">Inviting people</h2>\n  <p data-id=\"Butuh permission &lt;strong&gt;Manage members&lt;/strong&gt;, yang dimiliki owner dan Admin dengan akses ke semua grup. Anda hanya bisa memberikan role yang permission-nya Anda miliki sendiri, dan hanya grup yang bisa Anda lihat.\">Requires the <strong>Manage members</strong> permission, held by the owner and by Admins with access to all groups. You can only hand out a role whose permissions you hold yourself, and only groups you can see.</p>\n  <ol class=\"steps\">\n    <li data-id=\"&lt;strong&gt;Buka Team di sidebar.&lt;/strong&gt; Halaman ini menampilkan nama workspace dan penghitung seat, misalnya &quot;Seats 3 / 10&quot;.\"><strong>Open Team in the sidebar.</strong> The page shows the workspace name and the seat counter, for example \"Seats 3 / 10\".</li>\n    <li data-id=\"&lt;strong&gt;Masukkan alamat email.&lt;/strong&gt; Pada tab &lt;strong class=&quot;inline&quot;&gt;Members&lt;/strong&gt;, di bawah &lt;strong class=&quot;inline&quot;&gt;Invite someone&lt;/strong&gt;, ketik alamat email orang tersebut.\"><strong>Enter the email address.</strong> On the <strong class=\"inline\">Members</strong> tab, under <strong class=\"inline\">Invite someone</strong>, type the person's email address.</li>\n    <li data-id=\"&lt;strong&gt;Pilih sebuah Role.&lt;/strong&gt; Admin, Analyst, Viewer, atau custom role.\"><strong>Pick a Role.</strong> Admin, Analyst, Viewer, or a custom role.</li>\n    <li data-id=\"&lt;strong&gt;Pilih cakupan grupnya.&lt;/strong&gt; Di bawah &lt;strong class=&quot;inline&quot;&gt;Access to&lt;/strong&gt;, pilih &lt;strong class=&quot;inline&quot;&gt;All asset groups&lt;/strong&gt;, atau &lt;strong class=&quot;inline&quot;&gt;Only selected groups&lt;/strong&gt; lalu centang domainnya.\"><strong>Choose the group scope.</strong> Under <strong class=\"inline\">Access to</strong>, choose <strong class=\"inline\">All asset groups</strong>, or <strong class=\"inline\">Only selected groups</strong> and tick the domains.</li>\n    <li data-id=\"&lt;strong&gt;Klik Send invite.&lt;/strong&gt;\"><strong>Click Send invite.</strong></li>\n  </ol>\n\n  <div class=\"shot\">\n    <img class=\"shot-img\" src=\"assets/team-invite.png\" width=\"2022\" height=\"822\" loading=\"lazy\"\n         alt=\"The Team page Members tab, showing the Invite someone form with Email, Role and Access to fields and a Send invite button.\" />\n  </div>\n  <p class=\"shot-cap\" data-id=\"Formulir undangan pada tab Members: email, role, lalu cakupan grup.\">The invite form on the Members tab: email, role, then the group scope.</p>\n\n  <h3 data-id=\"Cara kerja undangan\">How invitations work</h3>\n  <ul>\n    <li data-id=\"Orang yang diundang menerima email dengan tombol &lt;strong&gt;Accept invitation&lt;/strong&gt;. Tautannya berlaku &lt;strong&gt;7 hari&lt;/strong&gt;, hanya bisa dipakai sekali, dan hanya untuk alamat yang dituju.\">The invitee gets an email with an <strong>Accept invitation</strong> button. The link is valid for <strong>7 days</strong>, works once, and only for the address it was sent to.</li>\n    <li data-id=\"Jika emailnya gagal terkirim, halaman Team menampilkan tautan undangan beserta tombol &lt;strong&gt;Copy&lt;/strong&gt;.\">If the email can't be sent, the Team page shows the invitation link with a <strong>Copy</strong> button.</li>\n    <li data-id=\"Undangan tertunda muncul sebagai &lt;strong&gt;Pending&lt;/strong&gt;, dengan tombol &lt;strong&gt;Resend&lt;/strong&gt; dan &lt;strong&gt;Cancel&lt;/strong&gt;. Mengundang alamat yang sama lagi akan menggantikan undangan sebelumnya.\">Pending invitations appear as <strong>Pending</strong>, with <strong>Resend</strong> and <strong>Cancel</strong> buttons. Inviting the same address again replaces the earlier invitation.</li>\n    <li data-id=\"Owner, member, dan undangan tertunda semuanya memakai seat. Ketika semuanya terpakai, mengundang diblokir sampai ada seat yang kosong.\">The owner, members and pending invitations all use seats. When all are in use, inviting is blocked until a seat frees up.</li>\n  </ul>\n\n  <h3 data-id=\"Mengelola member\">Managing members</h3>\n  <p data-id=\"Daftar member di &lt;strong&gt;Team &amp;rarr; Members&lt;/strong&gt; menampilkan nama dan email setiap orang, role-nya, grup mana yang bisa diaksesnya, dan kapan ia terakhir aktif. Klik ikon pensil untuk mengubah role dan cakupan grup, atau ikon tempat sampah untuk menghapus seseorang. Perubahan berlaku pada klik berikutnya orang tersebut; tidak perlu keluar dan masuk lagi, dan akun CounterAttack miliknya sendiri tidak terpengaruh.\">The member list at <strong>Team &rarr; Members</strong> shows each person's name and email, their role, which groups they can access, and when they were last active. Click the pencil icon to change their role and group scope, or the trash icon to remove them. Changes apply on their next click, with no sign-out needed, and their own CounterAttack account is unaffected.</p>\n  <p data-id=\"&lt;strong&gt;Team &amp;rarr; Audit log&lt;/strong&gt; mencatat perubahan tim dan tindakan lain, terbaru lebih dulu: undangan, bergabungnya anggota, perubahan role dan akses, penghapusan member, custom role, scan yang dimulai, dan laporan yang dibuat.\"><strong>Team &rarr; Audit log</strong> records team changes and other actions, newest first: invitations, joins, role and access changes, removals, custom roles, scans started, and reports generated.</p>\n\n  <h2 data-id=\"Pengaman eskalasi\">Escalation guards</h2>\n  <ul>\n    <li data-id=\"Tidak ada yang bisa memberikan permission yang tidak ia miliki, atau grup yang tidak bisa ia lihat.\">Nobody can grant a permission they don't have, or groups they can't see.</li>\n    <li data-id=\"Keempat permission bertanda &lt;sup&gt;1&lt;/sup&gt; di atas hanya berfungsi bagi member dengan akses ke semua grup. Memberi seorang Admin hanya grup tertentu otomatis melepas keempatnya.\">The four permissions marked <sup>1</sup> above only work for members with access to all groups. Giving an Admin only selected groups automatically removes those four.</li>\n    <li data-id=\"Tidak ada yang bisa mengubah atau menghapus keanggotaannya sendiri, atau orang dengan permission lebih banyak daripada dirinya. Owner tidak bisa diubah, dihapus, atau keluar dari workspace-nya sendiri.\">Nobody can change or remove their own membership, or someone with more permissions than they have. The owner can't be changed, removed, or leave their own workspace.</li>\n    <li data-id=\"Member yang boleh menjalankan scan hanya bisa memindai domain yang ada dalam cakupannya.\">A member who can run scans can only scan domains in their scope.</li>\n  </ul>\n\n  <div class=\"pager\"><a href=\"#/team\"><div class=\"dir\" data-id=\"Sebelumnya\">Previous</div><div class=\"ttl\">&larr; Team access</div></a><a class=\"next\" href=\"#/join\"><div class=\"dir\" data-id=\"Berikutnya\">Next</div><div class=\"ttl\">Join a workspace &rarr;</div></a></div>"
  },
  "join": {
    "id": "join",
    "title": "Join a workspace",
    "eyebrow": "Team",
    "lede": "When someone invites you into their workspace, you accept with your own CounterAttack account. Your own account doesn't change: your workspace and data stay separate, and you switch between them from the sidebar.",
    "html": "<span class=\"eyebrow\" data-id=\"Tim\">Team</span>\n  <h1 data-id=\"Bergabung ke workspace\">Join a workspace</h1>\n  <p class=\"lede\" data-id=\"Ketika seseorang mengundang Anda ke workspace mereka, Anda menerima undangan itu dengan akun CounterAttack Anda sendiri. Akun Anda sendiri tidak berubah: workspace dan data Anda tetap terpisah, dan Anda berpindah di antara keduanya dari sidebar.\">When someone invites you into their workspace, you accept with your own CounterAttack account. Your own account doesn't change: your workspace and data stay separate, and you switch between them from the sidebar.</p>\n\n  <h2 data-id=\"Menerima undangan\">Accepting an invitation</h2>\n  <ol class=\"steps\">\n    <li data-id=\"&lt;strong&gt;Klik Accept invitation di email.&lt;/strong&gt; Tautan itu membuka halaman undangan di counterattack.com.\"><strong>Click Accept invitation in the email.</strong> It opens the invitation page on counterattack.com.</li>\n    <li data-id=\"&lt;strong&gt;Masuk atau buat akun.&lt;/strong&gt; Jika Anda belum masuk, pilih Sign in jika sudah punya akun, atau Create account jika baru di CounterAttack. Akun baru memverifikasi emailnya dulu; setelah masuk pertama kali, CounterAttack membawa Anda kembali ke undangan secara otomatis.\"><strong>Sign in or create an account.</strong> If you're not signed in, choose <strong class=\"inline\">Sign in</strong> for an existing account, or <strong class=\"inline\">Create account</strong> if you're new to CounterAttack. New accounts verify their email first; after the first sign-in, CounterAttack takes you back to the invitation automatically.</li>\n    <li data-id=\"&lt;strong&gt;Periksa detailnya, lalu bergabung.&lt;/strong&gt; Halaman ini menampilkan siapa yang mengundang Anda, ke workspace mana, dan dengan role apa. Klik Join lalu nama workspace-nya.\"><strong>Check the details, then join.</strong> The page shows who invited you, to which workspace, and with which role. Click <strong class=\"inline\">Join &lt;workspace name&gt;</strong>.</li>\n    <li data-id=\"&lt;strong&gt;Anda mendarat di dashboard workspace tersebut.&lt;/strong&gt;\"><strong>You land on that workspace's dashboard.</strong></li>\n  </ol>\n  <p data-id=\"Jika Anda masuk dengan email yang berbeda dari yang diundang, halaman itu akan memberi tahu: keluar lalu masuk dengan alamat yang diundang.\">If you're signed in with a different email than the one invited, the page says so: sign out and sign in with the invited address.</p>\n\n  <h2 data-id=\"Berpindah workspace\">Switching workspaces</h2>\n  <p data-id=\"Siapa pun yang tergabung di lebih dari satu workspace akan melihat pemilih &lt;strong&gt;Workspace&lt;/strong&gt; di bagian atas sidebar, yang mencantumkan workspace miliknya sendiri, ditandai &quot;(yours)&quot;, dan setiap workspace yang ia ikuti beserta role-nya di sana. Memilih salah satunya akan memuat ulang CounterAttack di workspace tersebut. Sidebar menampilkan role member di sebelah namanya selama ia berada di workspace orang lain.\">Anyone who belongs to more than one workspace sees a <strong>Workspace</strong> selector at the top of the sidebar, listing their own workspace, marked \"(yours)\", and each workspace they joined with their role in it. Picking one reloads CounterAttack in that workspace. The sidebar shows the member's role next to their name while they're in someone else's workspace.</p>\n\n  <h2 data-id=\"Keluar dari sebuah workspace\">Leaving a workspace</h2>\n  <p data-id=\"Di bawah pemilih workspace, &lt;strong&gt;Leave this workspace&lt;/strong&gt; menghapus keanggotaan Anda setelah sebuah konfirmasi. Seseorang harus mengundang Anda lagi agar Anda bisa kembali. Owner tidak bisa keluar dari workspace-nya sendiri.\">Under the selector, <strong>Leave this workspace</strong> removes your membership after a confirmation. Someone has to invite you again for you to come back. The owner can't leave their own workspace.</p>\n\n  <div class=\"callout note\"><i data-lucide=\"shield\"></i><div><span class=\"callout-title\" data-id=\"Akun Anda sendiri tetap milik Anda\">Your own account stays yours</span><p data-id=\"Bergabung ke workspace orang lain tidak memberi mereka akses apa pun ke workspace Anda sendiri, dan tidak memakai salah satu root domain Anda. Saat berada di workspace mereka, Anda memakai paket, batas aset, dan seat milik mereka.\">Joining someone else's workspace gives them no access at all to your own workspace, and uses none of your root domains. While you're in their workspace, you use their plan, asset limit and seats.</p></div></div>\n\n  <div class=\"pager\"><a href=\"#/permissions\"><div class=\"dir\" data-id=\"Sebelumnya\">Previous</div><div class=\"ttl\">&larr; Roles &amp; permissions</div></a><a class=\"next\" href=\"#/mssp\"><div class=\"dir\" data-id=\"Berikutnya\">Next</div><div class=\"ttl\">Client access for MSSPs &rarr;</div></a></div>"
  },
  "mssp": {
    "id": "mssp",
    "title": "Client access for MSSPs",
    "eyebrow": "Team",
    "lede": "The usual pattern: the MSSP adds each client's domains as asset groups, gives its analysts access to the clients they handle, and invites each client's own staff with a read-only role limited to that client's groups. Each person sees only their groups, everywhere in the product.",
    "html": "<span class=\"eyebrow\" data-id=\"Tim\">Team</span>\n  <h1 data-id=\"Akses klien untuk MSSP\">Client access for MSSPs</h1>\n  <p class=\"lede\" data-id=\"Pola yang biasa dipakai: MSSP menambahkan domain setiap klien sebagai asset group, memberi analisnya akses ke klien yang mereka tangani, dan mengundang staf masing-masing klien dengan role read-only yang dibatasi pada grup klien tersebut. Setiap orang hanya melihat grupnya sendiri, di seluruh produk.\">The usual pattern: the MSSP adds each client's domains as asset groups, gives its analysts access to the clients they handle, and invites each client's own staff with a read-only role limited to that client's groups. Each person sees only their groups, everywhere in the product.</p>\n\n  <h2 data-id=\"Menyiapkannya\">Setting it up</h2>\n  <ol class=\"steps\">\n    <li data-id=\"&lt;strong&gt;Tambahkan domain setiap klien sebagai asset group.&lt;/strong&gt; Satu grup per root domain, dipindai dari workspace MSSP.\"><strong>Add each client's domains as asset groups.</strong> One group per root domain, scanned from the MSSP's workspace.</li>\n    <li data-id=\"&lt;strong&gt;Buat custom role read-only.&lt;/strong&gt; Misalnya &quot;Client read-only&quot;: Asset groups: View, Assets: View, Vulnerabilities: View, Reports: View. Lihat &lt;a href=&quot;#/permissions&quot;&gt;Custom role&lt;/a&gt;.\"><strong>Create a read-only custom role.</strong> For example \"Client read-only\": Asset groups: View, Assets: View, Vulnerabilities: View, Reports: View. See <a href=\"#/permissions\">Custom roles</a>.</li>\n    <li data-id=\"&lt;strong&gt;Undang analis Anda.&lt;/strong&gt; Berikan role Analyst, dibatasi pada grup klien yang mereka tangani, atau semua grup jika mereka menangani seluruh portofolio.\"><strong>Invite your analysts.</strong> Give them the Analyst role, limited to the client groups they handle, or all groups if they cover the whole portfolio.</li>\n    <li data-id=\"&lt;strong&gt;Undang staf klien.&lt;/strong&gt; Berikan role read-only dan pilih &lt;strong class=&quot;inline&quot;&gt;Only selected groups&lt;/strong&gt;, lalu centang domain milik klien itu saja.\"><strong>Invite the client's staff.</strong> Give them the read-only role and choose <strong class=\"inline\">Only selected groups</strong>, ticking that client's domains only.</li>\n  </ol>\n\n  <h2 data-id=\"Apa yang dilihat member dengan grup terbatas\">What a member limited to some groups sees</h2>\n  <p data-id=\"Contoh: MSSP A mengelola Bank A, Bank B, dan Bank C. Security lead Bank A diundang dengan custom role &quot;Client read-only&quot; dan akses hanya ke dua domain milik Bank A.\">Example: MSSP A manages Bank A, Bank B and Bank C. Bank A's security lead is invited with the custom role \"Client read-only\" and access to Bank A's two domains only.</p>\n  <table class=\"tbl\" style=\"margin:8px 0 22px;\">\n    <thead><tr><th data-id=\"Di mana\">Where</th><th data-id=\"Yang dilihat lead Bank A\">What Bank A's lead sees</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Asset Groups</strong></td><td data-id=\"Hanya domain Bank A. Bank B dan C tidak muncul sama sekali.\">Only Bank A's domains. Bank B and C don't appear at all.</td></tr>\n      <tr><td><strong data-id=\"Dashboard, security rating\">Dashboard, security rating</strong></td><td data-id=\"Jumlah dan nilai dihitung hanya dari grup Bank A.\">Counts and grades calculated from Bank A's groups only.</td></tr>\n      <tr><td><strong>All Findings, Vulnerabilities, Incidents, Resolved</strong></td><td data-id=\"Hanya item milik Bank A, dan hanya jenis yang boleh dilihat role-nya. Role ini melihat vulnerability, bukan incident.\">Only Bank A's items, and only the kinds their role can view. This role sees vulnerabilities, not incidents.</td></tr>\n      <tr><td><strong data-id=\"Tab halaman grup\">Group page tabs</strong></td><td data-id=\"Hanya tab yang diizinkan role-nya; di sini: Status, Assets, Vulnerabilities, History, tetapi bukan DNS atau Incidents.\">Only the tabs the role allows; here: Status, Assets, Vulnerabilities, History, but not DNS or Incidents.</td></tr>\n      <tr><td><strong>Activity</strong></td><td data-id=\"Disembunyikan untuk role ini. Dengan permission Activity: View, hanya scan atas grup mereka.\">Hidden for this role. With Activity: View, only scans of their groups.</td></tr>\n      <tr><td><strong>Report History</strong></td><td data-id=\"Hanya laporan yang mereka buat sendiri.\">Only reports they generated themselves.</td></tr>\n      <tr><td><strong data-id=\"Asisten AI\">AI assistant</strong></td><td data-id=\"Disembunyikan untuk role ini. Jika diizinkan, asisten hanya mengetahui grup mereka, dan setiap percakapan bersifat pribadi per orang.\">Hidden for this role. When allowed, it only knows about their groups, and chats are private to each person.</td></tr>\n      <tr><td><strong>Team, AI Settings, Upgrade</strong></td><td data-id=\"Tidak ditampilkan.\">Not shown.</td></tr>\n      <tr><td><strong data-id=\"Tautan ke halaman Bank B\">A link to Bank B's page</strong></td><td data-id=\"&quot;Not found&quot;, sama seperti halaman yang memang tidak ada.\">\"Not found\", the same as a page that doesn't exist.</td></tr>\n    </tbody>\n  </table>\n\n  <h2 data-id=\"Scan di dalam cakupan\">Scanning within a scope</h2>\n  <p data-id=\"Member yang boleh menjalankan scan hanya bisa memindai domain yang ada dalam cakupannya. Memulai scan pada domain klien lain akan ditolak. Menambahkan domain yang benar-benar baru memerlukan permission &lt;strong&gt;Add domains&lt;/strong&gt;, dan grup baru itu otomatis ditambahkan ke cakupan orang tersebut.\">A member who can run scans can only scan domains in their scope. Starting a scan on another client's domain is refused. Adding a brand-new domain needs the <strong>Add domains</strong> permission, and the new group is added to their scope automatically.</p>\n\n  <div class=\"callout note\"><i data-lucide=\"link\"></i><div><span class=\"callout-title\" data-id=\"Incident mengikuti domainnya\">Incidents follow the domain</span><p data-id=\"Hasil incident check sebuah domain disimpan terpisah di dalam CounterAttack tetapi selalu mengikuti domainnya: memberi seseorang sebuah domain juga memberi mereka incident domain tersebut, selama role mereka boleh melihat incident.\">A domain's incident-check results are stored separately inside CounterAttack but always follow the domain: giving someone a domain gives them its incidents too, provided their role can view incidents.</p></div></div>\n\n  <h2 data-id=\"Seat pada kontrak MSSP\">Seats on an MSSP contract</h2>\n  <p data-id=\"Kunci MSSP dan Enterprise membawa jumlah seat per kontrak, yang tanpa batas kecuali ada angka yang disepakati. Karena undangan tertunda juga dihitung, sepakati jumlah seat dengan mempertimbangkan setiap staf klien yang akan Anda undang, bukan hanya analis Anda sendiri. Hubungi CounterAttack untuk menambah seat pada sebuah kontrak.\">MSSP and Enterprise keys carry a per-contract seat number, unlimited unless a number is agreed. Because pending invitations count too, agree the seat number with every client staff member you plan to invite in mind, not just your own analysts. Contact CounterAttack to raise the seats on a contract.</p>\n\n  <div class=\"pager\"><a href=\"#/join\"><div class=\"dir\" data-id=\"Sebelumnya\">Previous</div><div class=\"ttl\">&larr; Join a workspace</div></a><a class=\"next\" href=\"#/team-troubleshooting\"><div class=\"dir\" data-id=\"Berikutnya\">Next</div><div class=\"ttl\">Team troubleshooting &rarr;</div></a></div>"
  },
  "team-troubleshooting": {
    "id": "team-troubleshooting",
    "title": "Team troubleshooting",
    "eyebrow": "Team",
    "lede": "Every message CounterAttack may show while inviting, joining or managing access, what it means, and what to do about it.",
    "html": "<span class=\"eyebrow\" data-id=\"Tim\">Team</span>\n  <h1 data-id=\"Pemecahan masalah tim\">Team troubleshooting</h1>\n  <p class=\"lede\" data-id=\"Setiap pesan yang mungkin ditampilkan CounterAttack saat mengundang, bergabung, atau mengelola akses, beserta artinya dan apa yang harus dilakukan.\">Every message CounterAttack may show while inviting, joining or managing access, what it means, and what to do about it.</p>\n\n  <h2 data-id=\"Mengundang dan seat\">Inviting and seats</h2>\n  <table class=\"tbl\" style=\"margin:8px 0 22px;\">\n    <thead><tr><th data-id=\"Pesan\">Message</th><th data-id=\"Kapan\">When</th><th data-id=\"Yang harus dilakukan\">What to do</th></tr></thead>\n    <tbody>\n      <tr><td class=\"mono\">Team members are available on Professional, MSSP and Enterprise plans.</td><td data-id=\"Mengundang dari workspace Free atau Starter\">Inviting from a Free or Starter workspace</td><td data-id=\"Upgrade paketnya\">Upgrade the plan</td></tr>\n      <tr><td class=\"mono\">All N seats are in use. Remove a member or cancel an invite first.</td><td data-id=\"Mengundang saat seluruh seat terpakai\">Inviting when every seat is taken</td><td data-id=\"Kosongkan satu seat, atau minta tambahan seat ke CounterAttack (MSSP / Enterprise)\">Free a seat, or ask CounterAttack for more (MSSP / Enterprise)</td></tr>\n      <tr><td class=\"mono\">That person is already a member.</td><td data-id=\"Mengundang orang yang sudah menjadi member\">Inviting an existing member</td><td data-id=\"Ubah aksesnya saja\">Edit their access instead</td></tr>\n      <tr><td class=\"mono\">That's the workspace owner.</td><td data-id=\"Mengundang email owner sendiri\">Inviting the owner's own email</td><td data-id=\"Tidak perlu apa-apa\">Nothing needed</td></tr>\n    </tbody>\n  </table>\n\n  <h2 data-id=\"Menerima undangan\">Accepting an invitation</h2>\n  <table class=\"tbl\" style=\"margin:8px 0 22px;\">\n    <thead><tr><th data-id=\"Pesan\">Message</th><th data-id=\"Kapan\">When</th><th data-id=\"Yang harus dilakukan\">What to do</th></tr></thead>\n    <tbody>\n      <tr><td class=\"mono\">This invitation was sent to (email). Sign in with that address to accept it.</td><td data-id=\"Menerima undangan saat masuk dengan email lain\">Accepting while signed in with another email</td><td data-id=\"Keluar, lalu masuk dengan alamat yang diundang\">Sign out, sign in with the invited address</td></tr>\n      <tr><td class=\"mono\">Verify your email address first.</td><td data-id=\"Menerima undangan sebelum memverifikasi akun baru\">Accepting before verifying a new account</td><td data-id=\"Buka email verifikasinya, lalu terima undangannya\">Open the verification email, then accept</td></tr>\n      <tr><td class=\"mono\">This invitation is expired / revoked / accepted.</td><td data-id=\"Tautan lama, dibatalkan, atau sudah dipakai\">Old, cancelled or already-used link</td><td data-id=\"Minta undangan baru\">Ask for a new invitation</td></tr>\n      <tr><td class=\"mono\">This invitation link is not valid.</td><td data-id=\"Tautan rusak atau salah ketik\">Broken or mistyped link</td><td data-id=\"Minta undangan baru\">Ask for a new invitation</td></tr>\n      <tr><td class=\"mono\">This workspace's plan no longer includes team members.</td><td data-id=\"Menerima undangan setelah paket owner berakhir\">Accepting after the owner's plan lapsed</td><td data-id=\"Owner memperpanjang paketnya\">The owner renews the plan</td></tr>\n      <tr><td class=\"mono\">The role in this invitation no longer exists.</td><td data-id=\"Menerima undangan setelah role-nya dihapus\">Accepting after the role was deleted</td><td data-id=\"Minta diundang kembali\">Ask to be invited again</td></tr>\n    </tbody>\n  </table>\n\n  <h2 data-id=\"Permission dan cakupan\">Permissions and scope</h2>\n  <table class=\"tbl\" style=\"margin:8px 0 22px;\">\n    <thead><tr><th data-id=\"Pesan\">Message</th><th data-id=\"Kapan\">When</th><th data-id=\"Yang harus dilakukan\">What to do</th></tr></thead>\n    <tbody>\n      <tr><td class=\"mono\">your role in this workspace does not allow this</td><td data-id=\"Tindakan apa pun yang tidak tercakup role tersebut\">Any action the role doesn't include</td><td data-id=\"Minta role lain kepada owner atau admin\">Ask the owner or an admin for a different role</td></tr>\n      <tr><td class=\"mono\">This domain is not available to you in this workspace.</td><td data-id=\"Memindai domain yang dipegang grup di luar cakupan Anda\">Scanning a domain held for a group outside your scope</td><td data-id=\"Minta akses ke grup tersebut\">Ask for access to that group</td></tr>\n      <tr><td class=\"mono\">Your role in this workspace can't add new domains.</td><td data-id=\"Memindai domain baru tanpa permission Add domains\">Scanning a new domain without Add domains</td><td data-id=\"Minta permission tersebut, atau minta admin menambahkan domainnya\">Ask for the permission, or an admin adds the domain</td></tr>\n      <tr><td class=\"mono\">only the workspace owner can do this</td><td data-id=\"Mengganti nama workspace atau Factory Reset sebagai member\">Renaming the workspace or Factory Reset as a member</td><td data-id=\"Minta ke owner\">Ask the owner</td></tr>\n    </tbody>\n  </table>\n\n  <h2 data-id=\"Mengelola orang dan role\">Managing people and roles</h2>\n  <table class=\"tbl\" style=\"margin:8px 0 22px;\">\n    <thead><tr><th data-id=\"Pesan\">Message</th><th data-id=\"Kapan\">When</th><th data-id=\"Yang harus dilakukan\">What to do</th></tr></thead>\n    <tbody>\n      <tr><td class=\"mono\">You can't grant a role with permissions you don't have.</td><td data-id=\"Mengundang atau mengubah seseorang dengan role yang lebih kuat\">Inviting or editing someone with a stronger role</td><td data-id=\"Minta ke owner atau admin yang lebih lengkap\">Ask the owner or a fuller admin</td></tr>\n      <tr><td class=\"mono\">You can't grant groups you can't see.</td><td data-id=\"Memberikan grup di luar akses Anda sendiri\">Giving groups outside your own access</td><td data-id=\"Sama\">Same</td></tr>\n      <tr><td class=\"mono\">You can't change your own access. Ask another admin or the owner.</td><td data-id=\"Mengubah baris Anda sendiri\">Editing your own row</td><td data-id=\"Minta orang lain melakukannya\">Ask someone else</td></tr>\n      <tr><td class=\"mono\">You can't change someone with more access than you. / You can't remove someone with more access than you.</td><td data-id=\"Mengubah atau menghapus member yang lebih kuat\">Editing or removing a stronger member</td><td data-id=\"Minta ke owner\">Ask the owner</td></tr>\n      <tr><td class=\"mono\">N member(s) have this role. Give them another role first.</td><td data-id=\"Menghapus role yang sedang dipakai\">Deleting a role in use</td><td data-id=\"Pindahkan member tersebut ke role lain\">Reassign those members</td></tr>\n      <tr><td class=\"mono\">That name is taken by a built-in role.</td><td data-id=\"Memberi custom role nama Owner, Admin, Analyst, atau Viewer\">Naming a custom role Owner, Admin, Analyst or Viewer</td><td data-id=\"Pilih nama lain\">Pick another name</td></tr>\n      <tr><td class=\"mono\">You can't leave your own workspace.</td><td data-id=\"Owner mencoba keluar\">The owner trying to leave</td><td data-id=\"Tidak perlu apa-apa\">Nothing needed</td></tr>\n    </tbody>\n  </table>\n\n  <div class=\"callout note\"><i data-lucide=\"bot\"></i><div><span class=\"callout-title\" data-id=\"&quot;Set up your AI provider in your profile&quot;\">\"Set up your AI provider in your profile\"</span><p data-id=\"Member melihat pesan ini jika workspace belum memiliki AI provider yang dikonfigurasi. Bagi seorang member, perbaikannya bukan di profilnya sendiri: owner yang harus mengatur provider di bawah AI Settings.\">Members see this when the workspace has no AI provider configured. For a member, the fix isn't in their own profile: the owner has to configure the provider under AI Settings.</p></div></div>\n\n  <div class=\"pager\"><a href=\"#/mssp\"><div class=\"dir\" data-id=\"Sebelumnya\">Previous</div><div class=\"ttl\">&larr; Client access for MSSPs</div></a><a class=\"next\" href=\"#/plans\"><div class=\"dir\" data-id=\"Berikutnya\">Next</div><div class=\"ttl\">Plans &amp; upgrading &rarr;</div></a></div>"
  },
  "plans": {
    "id": "plans",
    "title": "Plans &amp; upgrading",
    "eyebrow": "Account",
    "lede": "Every plan runs the full scanning workflow. Upgrading buys more assets, unlimited asset results, PDF and CSV reports, continuous scanning, the security rating, AI insights, and team access. There are five tiers.",
    "html": "<span class=\"eyebrow\" data-id=\"Akun\">Account</span>\n  <h1 data-id=\"Paket &amp;amp; upgrade\">Plans &amp; upgrading</h1>\n  <p class=\"lede\" data-id=\"Setiap paket menjalankan alur kerja scan lengkap. Upgrade membeli lebih banyak aset, hasil aset tanpa batas, laporan PDF dan CSV, scan berkelanjutan, Security rating, AI insights, dan akses tim. Ada lima tingkatan.\">Every plan runs the full scanning workflow. Upgrading buys more assets, unlimited asset results, PDF and CSV reports, continuous scanning, the security rating, AI insights, and team access. There are five tiers.</p>\n\n  <div class=\"callout note\"><i data-lucide=\"box\"></i><div><span class=\"callout-title\" data-id=\"Paket berbayar dibatasi oleh jumlah aset\">Paid plans are gated by asset count</span><p data-id=\"Paket berbayar tidak lagi membatasi jumlah root domain: Anda bisa menambahkan sebanyak apa pun yang Anda perlukan. Yang dibatasi adalah jumlah &lt;strong&gt;total aset&lt;/strong&gt; yang ditemukan di seluruh asset group Anda. Free adalah satu-satunya tingkatan yang masih dibatasi per domain.\">Paid plans no longer cap root domains: you can add as many as you need. What they cap is the number of <strong>total assets</strong> discovered across all your asset groups combined. Free is the only tier still limited by domain count.</p></div></div>\n\n  <h2 data-id=\"Lima tingkatan\">The five tiers</h2>\n  <table class=\"tbl\" style=\"margin:8px 0 22px;\">\n    <thead><tr><th>Plan</th><th data-id=\"Batas\">Limit</th><th data-id=\"Paling cocok untuk\">Best for</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Free</strong></td><td data-id=\"1 root domain, maksimal 20 aset\">1 root domain, max 20 assets</td><td data-id=\"Mencoba CounterAttack pada satu domain.\">Trying CounterAttack on a single domain.</td></tr>\n      <tr><td><strong>Starter</strong></td><td data-id=\"Hingga 100 aset\">Up to 100 assets</td><td data-id=\"Scan berkelanjutan, ekspor PDF dan CSV, ruang untuk tumbuh.\">Continuous scanning, PDF and CSV exports, room to grow.</td></tr>\n      <tr><td><strong>Business</strong></td><td data-id=\"Hingga 500 aset\">Up to 500 assets</td><td data-id=\"Alur kerja yang sama, untuk portofolio yang jauh lebih luas. Menambahkan akses tim (10 seat).\">The same workflow, room for a much wider portfolio. Adds team access (10 seats).</td></tr>\n      <tr><td><strong>MSSP</strong></td><td data-id=\"Aset khusus, per kontrak\">Custom assets, per contract</td><td data-id=\"Penyedia terkelola: kapasitas khusus, dukungan langsung, dan akses tim per klien.\">Managed providers: dedicated capacity, hands-on support, and team access per client.</td></tr>\n      <tr><td><strong>Enterprise</strong></td><td data-id=\"Aset tanpa batas\">Unlimited assets</td><td data-id=\"Skala tanpa batas dengan infrastruktur khusus.\">Unlimited scale with dedicated infrastructure.</td></tr>\n    </tbody>\n  </table>\n  <p data-id=\"Starter dan Business dibeli sendiri lewat halaman upgrade. MSSP dan Enterprise dilayani tim penjualan dan diterbitkan sebagai license key.\">Starter and Business are bought self-serve from the upgrade page. MSSP and Enterprise are sales-led and issued as license keys.</p>\n\n  <h2 data-id=\"Yang termasuk di setiap tingkatan\">What each tier includes</h2>\n  <table class=\"tbl\" style=\"margin:8px 0 22px;\">\n    <thead><tr><th data-id=\"Fitur\">Feature</th><th>Free</th><th>Starter</th><th>Business</th><th>MSSP</th><th>Enterprise</th></tr></thead>\n    <tbody>\n      <tr><td data-id=\"Total aset\">Total assets</td><td data-id=\"Maks 20\">Max 20</td><td>100</td><td>500</td><td data-id=\"Khusus\">Custom</td><td data-id=\"Tanpa batas\">Unlimited</td></tr>\n      <tr><td data-id=\"Root domain\">Root domains</td><td>1</td><td data-id=\"Tanpa batas\">Unlimited</td><td data-id=\"Tanpa batas\">Unlimited</td><td data-id=\"Tanpa batas\">Unlimited</td><td data-id=\"Tanpa batas\">Unlimited</td></tr>\n      <tr><td data-id=\"Alur kerja scan lengkap\">Full scan workflow</td><td data-id=\"Ya\">Yes</td><td data-id=\"Ya\">Yes</td><td data-id=\"Ya\">Yes</td><td data-id=\"Ya\">Yes</td><td data-id=\"Ya\">Yes</td></tr>\n      <tr><td data-id=\"Vulnerability scan dan Incident Check\">Vulnerability scan and Incident Check</td><td data-id=\"Ya\">Yes</td><td data-id=\"Ya\">Yes</td><td data-id=\"Ya\">Yes</td><td data-id=\"Ya\">Yes</td><td data-id=\"Ya\">Yes</td></tr>\n      <tr><td data-id=\"Screenshot aset\">Asset screenshots</td><td data-id=\"Ya\">Yes</td><td data-id=\"Ya\">Yes</td><td data-id=\"Ya\">Yes</td><td data-id=\"Ya\">Yes</td><td data-id=\"Ya\">Yes</td></tr>\n      <tr><td data-id=\"Hasil aset per group\">Asset results per group</td><td data-id=\"20 pertama\">First 20</td><td data-id=\"Tanpa batas\">Unlimited</td><td data-id=\"Tanpa batas\">Unlimited</td><td data-id=\"Tanpa batas\">Unlimited</td><td data-id=\"Tanpa batas\">Unlimited</td></tr>\n      <tr><td data-id=\"Data historis\">Historical data</td><td data-id=\"7 hari\">7 days</td><td data-id=\"Disimpan\">Kept</td><td data-id=\"Disimpan\">Kept</td><td data-id=\"Disimpan\">Kept</td><td data-id=\"Disimpan\">Kept</td></tr>\n      <tr><td data-id=\"Laporan PDF dan CSV\">PDF and CSV reports</td><td data-id=\"Tidak\">No</td><td data-id=\"Ya\">Yes</td><td data-id=\"Ya\">Yes</td><td data-id=\"Ya\">Yes</td><td data-id=\"Ya\">Yes</td></tr>\n      <tr><td data-id=\"Scan berkelanjutan\">Continuous scanning</td><td data-id=\"Tidak\">No</td><td data-id=\"Ya\">Yes</td><td data-id=\"Ya\">Yes</td><td data-id=\"Ya\">Yes</td><td data-id=\"Ya\">Yes</td></tr>\n      <tr><td data-id=\"Security rating (A sampai F)\">Security rating (A to F)</td><td data-id=\"Tidak\">No</td><td data-id=\"Ya\">Yes</td><td data-id=\"Ya\">Yes</td><td data-id=\"Ya\">Yes</td><td data-id=\"Ya\">Yes</td></tr>\n      <tr><td data-id=\"Notifikasi Telegram dan AI insights\">Telegram alerts and AI insights</td><td data-id=\"Tidak\">No</td><td data-id=\"Ya\">Yes</td><td data-id=\"Ya\">Yes</td><td data-id=\"Ya\">Yes</td><td data-id=\"Ya\">Yes</td></tr>\n      <tr><td data-id=\"Member tim &amp;amp; role\">Team members &amp; roles</td><td data-id=\"Tidak\">No</td><td data-id=\"Tidak\">No</td><td data-id=\"10 seat\">10 seats</td><td data-id=\"Seat khusus\">Custom seats</td><td data-id=\"Seat khusus\">Custom seats</td></tr>\n      <tr><td data-id=\"Node scanner khusus, SLA\">Dedicated scanner node, SLA</td><td data-id=\"Tidak\">No</td><td data-id=\"Tidak\">No</td><td data-id=\"Tidak\">No</td><td data-id=\"Ya\">Yes</td><td data-id=\"Ya\">Yes</td></tr>\n      <tr><td data-id=\"Penetration Test, Threat Intel feed\">Penetration Test, Threat Intel feed</td><td data-id=\"Tidak\">No</td><td data-id=\"Tidak\">No</td><td data-id=\"Tidak\">No</td><td data-id=\"Tidak\">No</td><td data-id=\"Ya\">Yes</td></tr>\n    </tbody>\n  </table>\n\n  <div class=\"callout warn\"><i data-lucide=\"clock\"></i><div><span class=\"callout-title\" data-id=\"Retensi Free\">Free retention</span><p data-id=\"Free menyimpan data scan selama 7 hari. Asset group yang lebih tua dari itu dihapus. Upgrade untuk menyimpan riwayat scan Anda. Paket berbayar menyimpannya tanpa batas waktu.\">Free keeps scan data for 7 days. Asset groups older than that are removed. Upgrade to keep your scan history. Paid plans keep it indefinitely.</p></div></div>\n\n  <h2 data-id=\"Ketika batas aset tercapai\">When the asset limit is reached</h2>\n  <p data-id=\"Batas aset dihitung dari seluruh asset group Anda digabung; aset yang hanya berasal dari incident check tidak dihitung. Begitu akun Anda mencapai atau melewati batasnya, scan baru diblokir sampai Anda upgrade atau menghapus aset. Scan yang sedang berjalan tidak dihentikan.\">The asset limit counts across all your asset groups combined; assets found only by the incident check don't count toward it. Once your account is at or over the cap, new scans are blocked until you upgrade or delete assets. A scan already running is not stopped.</p>\n\n  <h2 data-id=\"Upgrade\">Upgrading</h2>\n  <p data-id=\"Halaman upgrade menampilkan kelima paket berdampingan beserta penghitung penggunaan aset Anda yang langsung, toggle bulanan atau tahunan di mana tahunan memberi dua bulan gratis, dan toggle mata uang &lt;strong&gt;IDR / USD&lt;/strong&gt;. Starter dan Business melakukan pembayaran melalui Midtrans dalam Rupiah. Harga USD bersifat indikatif dan dilayani tim penjualan.\">The upgrade page shows all five plans side by side with a live counter of your asset usage, a monthly or yearly toggle where yearly gives two months free, and an <strong>IDR / USD</strong> currency toggle. Starter and Business check out through Midtrans in Rupiah. USD prices are indicative and sales-led.</p>\n  <p data-id=\"Jika Anda memiliki &lt;strong&gt;discount code&lt;/strong&gt;, buka &quot;Have a discount code?&quot;, masukkan kodenya, dan terapkan. MSSP dan Enterprise menggunakan &lt;strong&gt;Contact us&lt;/strong&gt;, yang membuka formulir pertanyaan agar seorang spesialis bisa menindaklanjuti; keduanya diaktifkan dengan license key, bukan lewat checkout.\">If you have a <strong>discount code</strong>, expand \"Have a discount code?\", enter it, and apply. MSSP and Enterprise use <strong>Contact us</strong>, which opens an enquiry form so a specialist can follow up; both are activated with a license key rather than through checkout.</p>\n\n  <div class=\"pager\"><a href=\"#/team-troubleshooting\"><div class=\"dir\" data-id=\"Sebelumnya\">Previous</div><div class=\"ttl\">&larr; Team troubleshooting</div></a><a class=\"next\" href=\"#/profile\"><div class=\"dir\" data-id=\"Berikutnya\">Next</div><div class=\"ttl\">Profile &amp; settings &rarr;</div></a></div>"
  },
  "profile": {
    "id": "profile",
    "title": "Profile &amp; settings",
    "eyebrow": "Account",
    "lede": "Your Profile page holds your identity and preferences. Each section is its own small form with its own save button, so you can change one thing without touching the rest.",
    "html": "<span class=\"eyebrow\" data-id=\"Akun\">Account</span>\n  <h1 data-id=\"Profile &amp;amp; pengaturan\">Profile &amp; settings</h1>\n  <p class=\"lede\" data-id=\"Halaman Profile Anda menyimpan identitas dan preferensi Anda. Setiap bagian adalah formulir kecil tersendiri dengan tombol simpannya sendiri, sehingga Anda bisa mengubah satu hal tanpa menyentuh yang lain.\">Your Profile page holds your identity and preferences. Each section is its own small form with its own save button, so you can change one thing without touching the rest.</p>\n\n  <h2 data-id=\"Yang bisa Anda ubah\">What you can change</h2>\n  <ul>\n    <li data-id=\"&lt;strong&gt;Display name&lt;/strong&gt;: ditampilkan di header sidebar Anda dan pada sampul laporan.\"><strong>Display name</strong>: shown in your sidebar header and on report covers.</li>\n    <li data-id=\"&lt;strong&gt;Email address&lt;/strong&gt;: Anda bisa masuk menggunakan username atau email ini.\"><strong>Email address</strong>: you can sign in with either your username or this email.</li>\n    <li data-id=\"&lt;strong&gt;Password&lt;/strong&gt;: masukkan password Anda saat ini dan password baru minimal 8 karakter.\"><strong>Password</strong>: enter your current password and a new one of at least 8 characters.</li>\n    <li data-id=\"&lt;strong&gt;Telegram alerts&lt;/strong&gt;: hubungkan atau putuskan bot, seperti dijelaskan di &lt;a href=&quot;#/alerts&quot;&gt;Alerts&lt;/a&gt;.\"><strong data-id=\"Notifikasi Telegram\">Telegram alerts</strong>: connect or disconnect the bot, as described in <a href=\"#/alerts\">Alerts</a>.</li>\n    <li data-id=\"&lt;strong&gt;Scan tier or license&lt;/strong&gt;: tukarkan license key dengan format &lt;code&gt;DETK-XXXX-XXXX-XXXX-XXXX&lt;/code&gt; untuk membuka scan.\"><strong>Scan tier or license</strong>: redeem a license key in the form <code>DETK-XXXX-XXXX-XXXX-XXXX</code> to unlock scanning.</li>\n  </ul>\n  <p data-id=\"Username Anda tetap dan tidak bisa diubah.\">Your username is fixed and cannot be changed.</p>\n\n  <div class=\"shot\">\n    <div class=\"shot-bar\"><span class=\"traffic\"><i></i><i></i><i></i></span><span class=\"url\">app.counterattack.com/profile</span></div>\n    <div class=\"shot-body\">\n      <div class=\"rl-card\" style=\"max-width:460px;\"><div class=\"rl-card-body\">\n        <div class=\"field\"><label>Display name</label><input class=\"input\" value=\"Andi Pratama\" readonly /></div>\n        <div class=\"field\" style=\"margin-bottom:0;\"><label>Email address</label><input class=\"input\" value=\"you@example.com\" readonly /></div>\n      </div></div>\n    </div>\n  </div>\n  <p class=\"shot-cap\" data-id=\"Setiap pengaturan adalah formulir independen dengan penyimpanan inline.\">Each setting is an independent form with an inline save.</p>\n\n  <div class=\"pager\"><a href=\"#/plans\"><div class=\"dir\" data-id=\"Sebelumnya\">Previous</div><div class=\"ttl\">&larr; Plans</div></a><a class=\"next\" href=\"#/playground\"><div class=\"dir\" data-id=\"Berikutnya\">Next</div><div class=\"ttl\">Live playground &rarr;</div></a></div>"
  },
  "playground": {
    "id": "playground",
    "title": "Live playground",
    "eyebrow": "Try it",
    "lede": "This is a fully interactive, simulated Full Scan running right inside the docs. Enter a domain and press start to watch CounterAttack move through all six stages, stream in assets, and surface vulnerabilities and incidents. No real network traffic is sent. It is a faithful walkthrough of what the live scan page does.",
    "html": "<span class=\"eyebrow\" data-id=\"Coba\">Try it</span>\n  <h1>Live playground</h1>\n  <p class=\"lede\" data-id=\"Ini adalah simulasi Full Scan yang sepenuhnya interaktif dan berjalan langsung di dalam dokumentasi. Masukkan sebuah domain dan tekan mulai untuk menyaksikan CounterAttack melewati keenam tahap, mengalirkan aset, dan memunculkan vulnerabilities serta incidents. Tidak ada lalu lintas jaringan nyata yang dikirim. Ini adalah panduan yang setia terhadap apa yang dilakukan halaman scan langsung.\">This is a fully interactive, simulated Full Scan running right inside the docs. Enter a domain and press start to watch CounterAttack move through all six stages, stream in assets, and surface vulnerabilities and incidents. No real network traffic is sent. It is a faithful walkthrough of what the live scan page does.</p>\n\n  <div class=\"pg\" id=\"pg\">\n    <div class=\"pg-top\">\n      <div class=\"pg-inputrow\">\n        <input class=\"input\" id=\"pg-domain\" value=\"acme-demo.test\" spellcheck=\"false\" />\n        <button class=\"btn btn-primary\" id=\"pg-run\"><i data-lucide=\"scan-search\"></i> Start Full Scan</button>\n        <button class=\"btn btn-ghost\" id=\"pg-reset\"><i data-lucide=\"rotate-ccw\"></i> Reset</button>\n      </div>\n      <div class=\"pg-progress\">\n        <div class=\"pg-progress-head\"><span id=\"pg-stage-label\">Idle. Enter a domain and start a scan.</span><span id=\"pg-percent\">0%</span></div>\n        <div class=\"pg-track\"><div class=\"pg-fill\" id=\"pg-bar\"></div></div>\n      </div>\n    </div>\n\n    <div class=\"pg-kpis\" id=\"pg-kpis\" style=\"opacity:0.35;\">\n      <div class=\"pg-kpi\"><div class=\"v\" id=\"pg-k-assets\">0</div><div class=\"l\">Assets</div></div>\n      <div class=\"pg-kpi\"><div class=\"v\" id=\"pg-k-vulns\" style=\"color:var(--sev-critical)\">0</div><div class=\"l\">Vulnerabilities</div></div>\n      <div class=\"pg-kpi\"><div class=\"v\" id=\"pg-k-incidents\" style=\"color:var(--sev-high)\">0</div><div class=\"l\">Incidents</div></div>\n      <div class=\"pg-kpi\"><div class=\"v\" id=\"pg-grade\" style=\"color:var(--fg-subtle)\">-</div><div class=\"l\">Grade</div></div>\n    </div>\n\n    <div class=\"pg-grid\">\n      <div class=\"pg-col\">\n        <div class=\"pg-col-title\">Workflow stages</div>\n        <div id=\"pg-stages\"></div>\n      </div>\n      <div class=\"pg-col\">\n        <div class=\"pg-col-title\">Discovered assets</div>\n        <div id=\"pg-assets\"></div>\n        <div class=\"pg-col-title\" style=\"margin-top:18px;\">Vulnerabilities &amp; incidents</div>\n        <div id=\"pg-findings\"></div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"callout note\" style=\"margin-top:20px;\"><i data-lucide=\"info\"></i><div><p data-id=\"Ketik domain apa pun dan tekan mulai. Hostname dibentuk dari apa yang Anda masukkan, sementara aset dan temuan adalah data contoh ilustratif. Pada produk sebenarnya, jalankan sebuah scan dari menu &lt;strong&gt;Add&lt;/strong&gt; terhadap domain yang Anda diizinkan untuk menguji.\">Type any domain and press start. The hostnames build from what you enter, while the assets and findings are illustrative sample data. In the real product, run a scan from the <strong>Add</strong> menu against a domain you are authorized to test.</p></div></div>\n\n  <h2 data-id=\"Apa yang baru saja Anda saksikan\">What you just watched</h2>\n  <p data-id=\"Playground mencerminkan pipeline nyata: discovery dan fingerprinting mengalirkan host, tahap port scan dan screenshot berjalan, vulnerability analysis memunculkan kelemahan, dan akhirnya incident check memastikan halaman yang disusupi. Di console langsung halaman yang sama juga memungkinkan admin menghentikan sebuah scan, menampilkan perkiraan waktu selesai, dan menghasilkan Security rating saat selesai.\">The playground mirrors the real pipeline: discovery and fingerprinting stream hosts in, the port scan and screenshot stages run, vulnerability analysis raises weaknesses, and finally the incident check confirms compromised pages. In the live console the same page also lets admins stop a scan, shows an estimated finish time, and produces a security rating on completion.</p>\n\n  <div class=\"pager\"><a href=\"#/profile\"><div class=\"dir\" data-id=\"Sebelumnya\">Previous</div><div class=\"ttl\">&larr; Profile</div></a><a class=\"next\" href=\"#/introduction\"><div class=\"dir\" data-id=\"Berikutnya\">Next</div><div class=\"ttl\">Back to Welcome &rarr;</div></a></div>"
  }
};
